app/components/blueprint/anatomy/flow.ts:
"use client";

import { cn } from "@/lib/client/utils";
import { StateChip } from "@/components/ui/state";
import { rowId, type Anatomy } from "@/lib/blueprint/schema";
import type { RowCtx } from "@/components/blueprint/anatomy";
import { rowClass } from "@/components/blueprint/anatomy/layout";
import { Caret } from "@/components/blueprint/anatomy/glyphs";

export function FlowBlock({
  owner,
  block,
  ctx,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "flow" }>;
  ctx: RowCtx;
}) {
  return (
    <ol className="flex flex-col">
      {block.rows.map((s, i) => {
        const id = rowId(owner, s.n);
        const isLit = ctx.traced === id;
        return (
          <li key={s.n} className="flex gap-2.5">
            {/* The rail: a numbered dot with a line to the next step, so the
                sequence reads as one path rather than four cards. */}
            <div className="flex flex-col items-center">
              <span
                className={cn(
                  "flex size-[18px] shrink-0 items-center justify-center rounded-full border font-mono text-[9px] font-semibold transition-colors",
                  isLit
                    ? "border-accent bg-accent text-on-accent"
                    : s.state === "derived"
                      ? "border-accent-line bg-accent-surface text-accent"
                      : "border-amber-line bg-amber-surface text-amber-ink",
                )}
              >
                {s.n}
              </span>
              {i < block.rows.length - 1 ? (
                <span className="w-px flex-1 bg-border-gray" />
              ) : null}
            </div>
            <button
              data-row={id}
              data-code-step={s.at && ctx.onStepCode ? "" : undefined}
              // See the blueprint row above: the click must not reach the card.
              onClick={(e) => {
                if (s.at && ctx.onStepCode) {
                  e.stopPropagation();
                  return ctx.onStepCode(s.at, `Step ${s.n} · ${s.title}`, s.detail);
                }
                if (!s.under) return ctx.onTrace(id);
                e.stopPropagation();
                ctx.onOpenRow(id);
              }}
              className={rowClass(
                id,
                ctx,
                cn(
                  "min-w-0 flex-1 px-1.5 py-0.5",
                  i < block.rows.length - 1 && "mb-2.5",
                ),
              )}
            >
              <span className="flex items-center gap-1.5">
                <span
                  className={cn(
                    "text-[11px] font-semibold leading-tight",
                    isLit || ctx.open === id ? "text-accent" : "text-ink",
                  )}
                >
                  {s.title}
                </span>
                <StateChip state={s.state} />
                {s.at && ctx.onStepCode ? (
                  <span className="ml-auto shrink-0 font-mono text-[9px] text-faint" title="Show the code for this step">
                    {"</>"}
                  </span>
                ) : null}
                {s.under ? (
                  <span className="ml-auto">
                    <Caret open={ctx.open === id} />
                  </span>
                ) : null}
              </span>
              {/* A step that has somewhere to go shows its TITLE and nothing
                  else. Its `detail` is the level behind the click, and
                  printing it here painted the next level onto this one — 226
                  words on this card alone, measured, of which four paragraphs
                  were the four children it already had.

                  A step with no `under` keeps its line, because for that row
                  there is no deeper level to defer to and the sentence is the
                  whole fact. */}
              {s.under ? null : (
                <span className="mt-0.5 block text-[10px] leading-relaxed text-on-surface-variant">
                  {s.detail}
                </span>
              )}
            </button>
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { cn } from "@/lib/client/utils";

/**
 * Points right, and turns green when this row's card is open.
 *
 * It does NOT rotate to point down any more. Down means "expands below me",
 * which is what this used to do and is exactly the thing that crushed 700px of
 * flow into a 340px column. The card opens to the RIGHT, so the mark keeps
 * pointing that way and only changes colour.
 */
export function Caret({ open }: { open: boolean }) {
  return (
    <svg
      width="9"
      height="9"
      viewBox="0 0 12 12"
      fill="none"
      aria-hidden="true"
      className={cn(
        "shrink-0 transition-colors duration-200",
        open ? "text-accent" : "text-faint",
      )}
    >
      <path
        d="M4.5 2.5L8 6l-3.5 3.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function KeyTag({ k, lit }: { k: "PK" | "FK" | "UQ"; lit?: boolean }) {
  return (
    <span
      className={cn(
        "shrink-0 px-1 py-px font-mono text-[8.5px] font-semibold leading-none",
        lit
          ? "bg-card text-accent ring-1 ring-accent/45"
          : k === "PK"
            ? "bg-accent-surface text-accent"
            : "bg-surface-container text-muted-slate",
      )}
    >
      {k}
    </span>
  );
}

const METHOD_TONE: Record<string, string> = {
  GET: "bg-surface-container text-muted-slate",
  POST: "bg-accent-surface text-accent",
  PATCH: "bg-amber-surface text-amber-ink",
  DELETE: "bg-clay-surface text-clay-ink",
};

export function Method({ method }: { method: string }) {
  return (
    <span
      className={cn(
        "w-[42px] shrink-0 px-1 py-px text-center font-mono text-[8.5px] font-semibold leading-[1.4]",
        METHOD_TONE[method],
      )}
    >
      {method}
    </span>
  );
}

export function FileGlyph() {
  return (
    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
      <path
        d="M3 1.5h3.5L9 4v6.5H3z"
        stroke="currentColor"
        strokeWidth="1"
        strokeLinejoin="round"
        className="text-muted-slate"
      />
      <path d="M6.4 1.6V4.2H9" stroke="currentColor" strokeWidth="1" strokeLinejoin="round" className="text-muted-slate" />
    </svg>
  );
}

export function TableGlyph() {
  return (
    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
      <rect x="1" y="1.5" width="10" height="9" rx="1.5" stroke="currentColor" strokeWidth="1" className="text-muted-slate" />
      <path d="M1 4.5h10M4.5 4.5v6" stroke="currentColor" strokeWidth="1" className="text-muted-slate" />
    </svg>
  );
}

app/components/blueprint/anatomy/index.t:
"use client";

import type { Anatomy } from "@/lib/blueprint/schema";
import { ExplainedBlock, isExplained } from "@/components/blueprint/blocks";
import { SourceView } from "@/components/blueprint/source-view";
import { SchemaBlock } from "@/components/blueprint/anatomy/schema";
import { RoutesBlock } from "@/components/blueprint/anatomy/routes";
import { ChipsBlock } from "@/components/blueprint/anatomy/chips";
import { PartsBlock } from "@/components/blueprint/anatomy/parts";
import { BarsBlock } from "@/components/blueprint/anatomy/bars";
import { FlowBlock } from "@/components/blueprint/anatomy/flow";
import { Facts } from "@/components/blueprint/anatomy/facts";
import { MapRows } from "@/components/blueprint/anatomy/map-rows";

/**
 * Level 2 renders in the SHAPE of the thing it describes, and the rows are the
 * point. Clicking a row lights it and greys everything else.
 */

export interface RowCtx {
  /** The row clicked last, which stays lit while the others recede. */
  traced: string | null;
  onTrace: (id: string) => void;
  /**
   * The row on the open path, if the level below came from a row. Lights the
   * row you drilled through, the same way a card stays selected.
   */
  open: string | null;
  /** Drill into the level this row owns. Same gesture as opening a card. */
  onOpenRow: (id: string) => void;
  /**
   * Show the lines a step cites (`Step.at`), over the page. Set only on the
   * open level, where there is room for the code; a step with `at` then opens
   * its code instead of tracing.
   */
  onStepCode?: (at: string, heading: string, detail?: string) => void;
}

export function AnatomyView({
  owner,
  blocks,
  ctx,
  headless,
}: {
  owner: string;
  blocks: Anatomy[];
  ctx: RowCtx;
  /** Drawn inside a row that already names the block, so its own header and frame would say it twice. */
  headless?: boolean;
}) {
  return (
    <div className="flex flex-col gap-3">
      {blocks.map((block, i) => (
        <Block key={i} owner={owner} block={block} ctx={ctx} headless={headless} />
      ))}
    </div>
  );
}

function Block({
  owner,
  block,
  ctx,
  headless,
}: {
  owner: string;
  block: Anatomy;
  ctx: RowCtx;
  headless?: boolean;
}) {
  if (block.kind === "schema") {
    return <SchemaBlock owner={owner} block={block} ctx={ctx} headless={headless} />;
  }

  if (block.kind === "routes") {
    return <RoutesBlock owner={owner} block={block} ctx={ctx} />;
  }

  if (block.kind === "source") {
    return <SourceView owner={owner} block={block} ctx={ctx} />;
  }

  if (isExplained(block)) return <ExplainedBlock block={block} />;

  if (block.kind === "chips") {
    return <ChipsBlock owner={owner} block={block} ctx={ctx} />;
  }

  if (block.kind === "map") return <MapRows owner={owner} block={block} ctx={ctx} />;

  if (block.kind === "parts") {
    return <PartsBlock owner={owner} block={block} ctx={ctx} />;
  }

  if (block.kind === "bars") {
    return <BarsBlock owner={owner} block={block} ctx={ctx} />;
  }

  if (block.kind === "flow") {
    return <FlowBlock owner={owner} block={block} ctx={ctx} />;
  }

  return <Facts owner={owner} block={block} ctx={ctx} />;
}

import { cn } from "@/lib/client/utils";
import { ROW_LABEL_MAX_PCT, ROW_VALUE_MIN_PX } from "@/lib/blueprint/view";
import type { RowCtx } from "@/components/blueprint/anatomy";

/**
 * The label is the question; the value is the answer. The answer never gets
 * less room than the question.
 *
 * Measured failure this exists to delete: a `map` row 212px wide where the
 * label `what the code does` took 112px — 53% — and the value got 32px,
 * rendering one word per line over twelve lines. The most important comparison
 * on the card was the least readable thing on screen.
 *
 * The cause was a `shrink-0` label beside a `min-w-0 flex-1` value: the only
 * element in the row allowed to give up space was the one carrying the content.
 * A previous fix moved the state chip INSIDE the value column (see the comment
 * that survives in the `blueprint` block), which was real but addressed the wrong
 * element — the label was still unbounded.
 *
 * Two rules from `lib/blueprint/view.ts`, enforced together:
 *
 *   label ≤ ROW_LABEL_MAX_PCT (40%)   value ≥ ROW_VALUE_MIN_PX (160px)
 *
 * Below a certain row width both cannot hold at once, so rather than squeeze
 * the value under its floor the pair STACKS — label above value, each with the
 * full width. That threshold is a property of the ROW, not of the viewport: a
 * card is a fixed-width column on a canvas that pans, so a viewport breakpoint
 * would tell us nothing about the space this row actually has. Hence a
 * container query.
 *
 * The threshold below is 267px, and it is `ROW_VALUE_MIN_PX / (1 -
 * ROW_LABEL_MAX_PCT/100)` — the narrowest row on which a 40% label still
 * leaves 160px. It is written as a literal in the class strings because
 * Tailwind scans source statically: an interpolated `@min-[${n}px]:` is a
 * class name no build step ever sees, so it would compile to nothing and the
 * row would silently stay stacked at every width. The assertion keeps the
 * literal honest if either constant is ever retuned.
 */
const STACK_BELOW_PX = Math.ceil(ROW_VALUE_MIN_PX / (1 - ROW_LABEL_MAX_PCT / 100));
if (STACK_BELOW_PX !== 267) {
  throw new Error(
    `view.ts row rules changed: the @min-[267px] literals in components/blueprint/anatomy/ must become @min-[${STACK_BELOW_PX}px]`,
  );
}

/**
 * Every pair row is its own query container. The row, not the card, is what
 * the rules are about — a card can be wide while a row inside a rail or an
 * indent is not.
 */
export const PAIR_SCOPE = "@container";

/**
 * Side by side once the row can honour both rules; stacked when it cannot.
 *
 * The percentage cap is a MAX, not a width, so a short label keeps its natural
 * size and does not pad out to 40% leaving the value starved for no reason.
 */
// Each of these is ONE unbroken literal on purpose. Tailwind's scanner reads
// source text, not evaluated JavaScript: splitting a class list across a `+`
// hides every class after the operator, which compiles to nothing and fails
// silently — measured here, where only the one class that stayed inline in JSX
// survived into the stylesheet.
export const PAIR_ROW = "flex w-full min-w-0 flex-col items-stretch gap-0.5 @min-[267px]:flex-row @min-[267px]:items-start @min-[267px]:gap-2";

/** The question side. Capped, never allowed to eat the row. */
export const PAIR_LABEL = "min-w-0 text-left @min-[267px]:max-w-[40%] @min-[267px]:shrink-0";

/** The answer side. Floored, and it is the only side allowed to grow. */
export const PAIR_VALUE = "w-full min-w-0 text-left @min-[267px]:w-auto @min-[267px]:flex-1 @min-[267px]:min-w-[160px]";

/** A schema row: name, type and key in fixed tracks, the note in what is left. */
export const SCHEMA_ROW =
  "grid w-full grid-cols-[minmax(0,var(--name))_minmax(0,var(--type))_2.25rem] gap-x-4 px-3 text-left @min-[300px]:grid-cols-[minmax(0,var(--name))_minmax(0,var(--type))_2.25rem_minmax(0,1fr)]";

/** Shared row chrome: lit fill, dimmed-when-others-are-lit, click to trace. */
export function rowClass(id: string, ctx: RowCtx, extra?: string) {
  const isLit = ctx.traced === id;
  return cn(
    "w-full text-left transition-[background-color,opacity] duration-150",
    isLit && "bg-accent-surface",
    ctx.traced !== null && !isLit && "opacity-55",
    ctx.traced === null && "hover:bg-surface-container",
    extra,
  );
}

app/components/blueprint/anatomy/map-row:
"use client";

import { useState } from "react";
import { cn } from "@/lib/client/utils";
import { StateChip } from "@/components/ui/state";
import { rowId, type Anatomy } from "@/lib/blueprint/schema";
import type { RowCtx } from "@/components/blueprint/anatomy";
import { rowClass } from "@/components/blueprint/anatomy/layout";
import { Caret } from "@/components/blueprint/anatomy/glyphs";

/**
 * A `blueprint` block as a list of names. Each row's `to` stays folded until the
 * reader asks for it, so the block reads as the set of cases first and the
 * detail of one case second, instead of a wall of arrows.
 */
export function MapRows({ owner, block, ctx }: { owner: string; block: Extract<Anatomy, { kind: "map" }>; ctx: RowCtx }) {
  const [shown, setShown] = useState<Set<string>>(() => new Set());
  const toggle = (from: string) =>
    setShown((s) => {
      const next = new Set(s);
      if (!next.delete(from)) next.add(from);
      return next;
    });
  return (
    <div className="overflow-hidden border border-border-gray bg-card">
      {block.caption ? (
        <div className="border-b border-border-gray bg-surface px-3 py-1.5">
          <span className="font-mono text-[9.5px] uppercase tracking-[0.08em] text-faint">
            {block.caption}
          </span>
        </div>
      ) : null}
      {block.rows.map((m) => {
        const id = rowId(owner, m.from);
        const isLit = ctx.traced === id;
        const isOpen = ctx.open === id;
        // A row with a level of its own shows its detail while that level is open.
        const expanded = shown.has(m.from) || isOpen;
        return (
          <div key={m.from} className="border-b border-border-gray last:border-b-0">
            <button
              data-row={id}
              aria-expanded={expanded}
              // The card wrapping these rows is itself clickable, and a real
              // pointer click bubbles: without stopping it here, the card's
              // handler fires on the SAME click and undoes the row's.
              onClick={(e) => {
                e.stopPropagation();
                if (m.under) return ctx.onOpenRow(id);
                toggle(m.from);
                ctx.onTrace(id);
              }}
              className={rowClass(id, ctx, "flex w-full items-start gap-2 px-3 py-1.5 text-left")}
            >
              <span className="min-w-0 flex-1">
                <span
                  className={cn(
                    "inline-block px-1.5 py-0.5 font-mono text-[10px]",
                    isLit || isOpen ? "bg-accent text-on-accent" : "bg-surface-container text-on-surface",
                  )}
                >
                  {m.from}
                </span>
                {m.state !== "derived" ? <StateChip state={m.state} className="ml-1.5 align-[1px]" /> : null}
                {expanded ? (
                  <span
                    className={cn(
                      "mt-1.5 mb-0.5 block border-l-2 pl-2 font-mono text-[9.5px] leading-snug",
                      m.state === "derived" ? "border-border-strong text-muted-slate" : "border-amber-line text-amber-ink",
                    )}
                  >
                    {m.to}
                  </span>
                ) : null}
              </span>
              {/* Turns down when the row unfolds in place; a row that opens a
                  level points right like every other way down. */}
              <span className={cn("mt-[3px] shrink-0 transition-transform duration-200", expanded && !m.under && "rotate-90")}>
                <Caret open={expanded} />
              </span>
            </button>
          </div>
        );
      })}
    </div>
  );
}

app/components/blueprint/anatomy/parts.t:
"use client";

import { cn } from "@/lib/client/utils";
import { StateChip } from "@/components/ui/state";
import { rowId, type Anatomy } from "@/lib/blueprint/schema";
import type { RowCtx } from "@/components/blueprint/anatomy";

export function PartsBlock({
  owner,
  block,
  ctx,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "parts" }>;
  ctx: RowCtx;
}) {
  // The ratio IS the finding. Segments are sized by real weight, so a 149KB
  // block next to a 1KB one looks like what it is — no amount of prose makes
  // that land the way a length does.
  const total = block.rows.reduce((sum, p) => sum + p.weight, 0) || 1;
  return (
    <div className="overflow-hidden border border-border-gray bg-card">
      <div className="flex items-center gap-2 border-b border-border-gray bg-surface px-3 py-1.5">
        <span className="font-mono text-[11px] font-semibold text-ink">
          {block.total}
        </span>
        <span className="ml-auto font-mono text-[10px] text-faint">
          {block.rows.length} parts
        </span>
      </div>
      <div className="px-3 pb-2.5 pt-2.5">
        <div className="flex h-[22px] w-full overflow-hidden">
          {block.rows.map((p, at) => {
            const id = rowId(owner, p.label);
            const isLit = ctx.traced === id;
            return (
              <button
                key={p.label}
                data-row={id}
                onClick={() => ctx.onTrace(id)}
                title={`${p.label} — ${p.display}`}
                // Floored at 6%: a slice worth naming has to be visible, and
                // a 1%-of-the-whole block rendered ~2px wide — present in the
                // DOM, absent to the eye. The exact figure is in the legend;
                // the bar's job is the contrast, not the arithmetic.
                style={{ width: `${Math.max((p.weight / total) * 100, 6)}%` }}
                className={cn(
                  "h-full border-r border-card transition-[background-color,opacity] duration-150 last:border-r-0",
                  ctx.traced !== null && !isLit && "opacity-45",
                  isLit
                    ? "bg-accent"
                    : p.tone === "vary"
                      ? "bg-amber-line"
                      : // Alternating weights within the same family. Every
                        // "hold" slice sharing one mint made a 198px and a
                        // 33px segment read as a single bar with a hairline
                        // seam — measured, not guessed. The ratio only lands
                        // if adjacent slices are separable.
                        at % 2 === 0
                        ? "bg-accent/55"
                        : "bg-accent-line",
                )}
              />
            );
          })}
        </div>
        {/* Legend, not a table: label and size on one line each. */}
        <ul className="mt-2 flex flex-col gap-1">
          {block.rows.map((p, at) => {
            const id = rowId(owner, p.label);
            const isLit = ctx.traced === id;
            return (
              <li key={p.label} className="flex items-center gap-2">
                <span
                  // Same tone rule as the bar segment above, index included.
                  // A swatch is only a key if it is the colour it explains.
                  className={cn(
                    "size-[7px] shrink-0",
                    isLit
                      ? "bg-accent"
                      : p.tone === "vary"
                        ? "bg-amber-line"
                        : at % 2 === 0
                          ? "bg-accent/55"
                          : "bg-accent-line",
                  )}
                />
                <span
                  className={cn(
                    // `min-w-0` so a long label wraps instead of shoving the
                    // figure past the right edge. The figure stays `shrink-0`
                    // because it is short and is the thing being compared.
                    "min-w-0 font-mono text-[10px]",
                    isLit ? "font-semibold text-accent" : "text-on-surface",
                  )}
                >
                  {p.label}
                </span>
                <span className="ml-auto shrink-0 font-mono text-[10px] text-muted-slate">
                  {p.display}
                </span>
                <StateChip state={p.state} />
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/client/utils";
import { StateChip } from "@/components/ui/state";
import { rowId, type Anatomy } from "@/lib/blueprint/schema";
import type { RowCtx } from "@/components/blueprint/anatomy";
import { PAIR_LABEL, PAIR_ROW, PAIR_SCOPE, PAIR_VALUE, rowClass } from "@/components/blueprint/anatomy/layout";
import { Method } from "@/components/blueprint/anatomy/glyphs";

export function RoutesBlock({
  owner,
  block,
  ctx,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "routes" }>;
  ctx: RowCtx;
}) {
  return (
    <div className="overflow-hidden border border-border-gray bg-card">
      {block.rows.map((r) => {
        const id = rowId(owner, `${r.method} ${r.path}`);
        const isLit = ctx.traced === id;
        return (
          <button
            key={r.method + r.path}
            data-row={id}
            onClick={() => ctx.onTrace(id)}
            className={rowClass(
              id,
              ctx,
              cn(PAIR_SCOPE, "block border-b border-border-gray px-3 py-1.5 last:border-b-0"),
            )}
          >
            {/* The method is the label; the path is the answer, and it was
                `truncate` — so the one string a reader needs in full was the
                first thing cut. It wraps now, and the auth note drops to its
                own line before the path has to give up any width. */}
            <span className={PAIR_ROW}>
              <span className={cn(PAIR_LABEL, "flex items-center gap-2")}>
                <Method method={r.method} />
                <span
                  className={cn(
                    "min-w-0 font-mono text-[10.5px] break-all",
                    isLit ? "font-semibold text-accent" : "text-on-surface",
                  )}
                >
                  {r.path}
                </span>
              </span>
              <span className={cn(PAIR_VALUE, "flex items-start gap-2")}>
                <span className="min-w-0 flex-1 font-mono text-[9.5px] leading-snug text-faint @min-[267px]:text-right">
                  {r.auth}
                </span>
                <StateChip state={r.state} />
              </span>
            </span>
            {r.note ? (
              <span
                className={cn(
                  "mt-0.5 block pl-[46px] text-[10px] leading-snug",
                  r.state === "derived" ? "text-faint" : "text-amber-ink",
                )}
              >
                {r.note}
              </span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { cn } from "@/lib/client/utils";
import { StateChip } from "@/components/ui/state";
import { rowId, type Anatomy } from "@/lib/blueprint/schema";
import type { RowCtx } from "@/components/blueprint/anatomy";
import { SCHEMA_ROW, rowClass } from "@/components/blueprint/anatomy/layout";
import { KeyTag, TableGlyph } from "@/components/blueprint/anatomy/glyphs";

export function SchemaBlock({
  owner,
  block,
  ctx,
  headless,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "schema" }>;
  ctx: RowCtx;
  headless?: boolean;
}) {
  return (
    <div className={headless ? "bg-card" : "overflow-hidden border border-border-gray bg-card"}>
      <div className={cn("flex items-center gap-2 border-b border-border-gray bg-surface px-3 py-1.5", headless && "hidden")}>
        <TableGlyph />
        <span className="font-mono text-[11px] font-semibold text-ink">
          {block.table}
        </span>
        <span className="ml-auto font-mono text-[10px] text-faint">
          {/* A schema named like a file (`blueprint.json`) is a document's fields, not a table's columns. */}
          {block.rows.length} {/\.\w+$/.test(block.table) ? "fields" : "columns"}
        </span>
      </div>
      {/* Every row shares one column template, sized in `ch` from the
          longest name and type (both are monospace), so the columns line up
          down the table. Under 300px the note takes a line of its own. */}
      <div
        className="@container"
        style={{
          ["--name" as string]: `${Math.max(6, ...block.rows.map((c) => c.name.length + (c.nullable ? 1 : 0)))}ch`,
          ["--type" as string]: `${Math.max(4, ...block.rows.map((c) => c.type.length))}ch`,
        }}
      >
        <div className={cn(SCHEMA_ROW, "border-b border-border-gray py-1 font-mono text-[9px] uppercase tracking-wide text-faint")}>
          <span>{/\.\w+$/.test(block.table) ? "field" : "column"}</span>
          <span>type</span>
          <span>key</span>
          <span className="hidden @min-[300px]:block">notes</span>
        </div>
        {block.rows.map((c) => {
          const id = rowId(owner, c.name);
          const isLit = ctx.traced === id;
          return (
            <button
              key={c.name}
              data-row={id}
              onClick={() => ctx.onTrace(id)}
              className={rowClass(id, ctx, cn(SCHEMA_ROW, "items-baseline gap-y-0.5 border-b border-border-gray py-1.5 last:border-b-0"))}
            >
              <span
                className={cn(
                  "min-w-0 break-words font-mono text-[10.5px]",
                  isLit ? "font-semibold text-accent" : "text-on-surface",
                )}
              >
                {c.name}
                {c.nullable ? <span className="text-faint" title="can be empty">?</span> : null}
              </span>
              <span className="min-w-0 break-words font-mono text-[10.5px] text-muted-slate">
                {c.type}
              </span>
              <span className="self-center">{c.key ? <KeyTag k={c.key} lit={isLit} /> : null}</span>
              <span className="col-span-full flex items-start gap-2 @min-[300px]:col-span-1">
                {c.note ? (
                  <span
                    className={cn(
                      "min-w-0 flex-1 text-[10px] leading-snug",
                      c.state === "derived" ? "text-faint" : "text-amber-ink",
                    )}
                  >
                    {c.note}
                  </span>
                ) : (
                  <span className="min-w-0 flex-1" />
                )}
                <StateChip state={c.state} />
              </span>
            </button>
          );
        })}
      </div>
      {block.rel?.length ? (
        <div className="border-t border-border-gray bg-surface-container-low px-3 py-2">
          {block.rel.map((r) => (
            <p
              key={r}
              className="text-[10px] leading-relaxed text-on-surface-variant"
            >
              {r}
            </p>
          ))}
        </div>
      ) : null}
    </div>
  );
}

app/components/blueprint/audit.tsx:
"use client";

import { useEffect, useMemo, useState } from "react";
import { goTo } from "@/components/chrome/crumbs";
import { DIALOG, Overlay } from "@/components/ui/dialog";
import { openDiff } from "@/components/review/diff";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { PanelClose, PanelHead } from "@/components/ui/panel";
import { Ident, Prose, StateChip } from "@/components/ui/state";
import type { Node } from "@/lib/blueprint/schema";
import { cn } from "@/lib/client/utils";

const OPEN = "blueprint:audit";
/** Show how sure the blueprint on screen is (`id` is its name). */
export const openAudit = (id: string) => window.dispatchEvent(new CustomEvent<string>(OPEN, { detail: id }));

/**
 * How sure the blueprint on screen is, from the blueprint itself: what verification
 * checked and corrected, what is not certain, whether the code moved on.
 * The run's own audit (scripts/generate/audit.ts) is folded at the bottom
 * for debugging the generator. It is Markdown, but only ever the few shapes
 * audit.ts writes — headings, lists, a table, a folded step list, bold,
 * italics, code — so those are drawn here rather than through a Markdown
 * library.
 */
export function AuditDialog() {
  const { TOP, RUN, blueprints } = useBlueprint();
  const [id, setId] = useState<string | null>(null);
  // undefined while it loads; null when the blueprint has no audit.
  const [text, setText] = useState<string | null | undefined>(undefined);
  // The log is fetched only once someone unfolds it.
  const [wantLog, setWantLog] = useState(false);
  const [behind, setBehind] = useState<string[]>([]);
  const local = blueprints.some((m) => m.id === id && m.local);

  useEffect(() => {
    const on = (e: Event) => {
      setId((e as CustomEvent<string>).detail);
      setText(undefined);
      setWantLog(false);
      setBehind([]);
    };
    window.addEventListener(OPEN, on);
    return () => window.removeEventListener(OPEN, on);
  }, []);

  useEffect(() => {
    if (!id || !wantLog) return;
    let live = true;
    fetch(`/api/projects?audit=${encodeURIComponent(id)}`)
      .then((r) => (r.ok ? r.json() : { markdown: null }))
      .then((d: { markdown: string | null }) => live && setText(d.markdown))
      .catch(() => live && setText(null));
    return () => {
      live = false;
    };
  }, [id, wantLog]);

  useEffect(() => {
    if (!id || !local) return;
    let live = true;
    fetch(`/api/files?blueprint=${encodeURIComponent(id)}&behind=1`)
      .then((r) => (r.ok ? r.json() : null))
      .then((r: { behind: string[] } | null) => live && setBehind(r?.behind ?? []))
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [id, local]);

  const sure = useMemo(() => {
    let levels = 0;
    let checked = 0;
    let corrected = 0;
    const look: { path: string[]; node: Node; trail: string; why: string }[] = [];
    const walk = (n: Node, p: string[], trail: string[]) => {
      levels++;
      if (n.verified) checked++;
      corrected += n.verified?.corrected ?? 0;
      const where = trail.join(" › ") || RUN.repo;
      if (n.state !== "derived") look.push({ path: p, node: n, trail: where, why: n.unsure ?? "" });
      else if (n.verified?.corrected)
        look.push({ path: p, node: n, trail: where, why: `${n.verified.corrected} ${n.verified.corrected === 1 ? "claim was" : "claims were"} wrong and corrected in review; the rest of this level held up.` });
      for (const c of n.children ?? []) walk(c, [...p, c.id], p.length ? [...trail, n.title] : []);
    };
    walk(TOP, [], []);
    return { levels, checked, corrected, unsure: look.filter((x) => x.node.state !== "derived").length, look };
  }, [TOP, RUN.repo]);

  if (!id) return null;
  const close = () => setId(null);
  const parsed = text ? parse(text) : [];
  // The log's own title repeats the dialog's.
  const blocks = parsed[0]?.kind === "h1" ? parsed.slice(1) : parsed;

  return (
    <Overlay onClose={close}>
      <div role="dialog" aria-label="How sure is this blueprint" className={cn(DIALOG, "max-w-[720px]")}>
        <PanelHead
          title="How sure is this blueprint"
          note="What was checked against the code, and what to double-check."
          right={<PanelClose onClick={close} />}
        />
        <div className="min-h-0 flex-1 overflow-auto px-6 py-5 text-[13.5px] leading-relaxed text-on-surface-variant">
          <div className="grid grid-cols-3 gap-3">
            <Stat
              value={sure.checked ? `${sure.checked}/${sure.levels}` : "—"}
              label="levels checked against the code"
              note={sure.checked ? "A second model read every claim against the lines it cites." : "This blueprint was made before checks were recorded."}
            />
            <Stat value={String(sure.corrected)} label="claims corrected" note="Found wrong in review and rewritten before you saw them." />
            <Stat value={String(sure.unsure)} label="not certain" note="Levels the blueprint could not fully show from the code." warn={sure.unsure > 0} />
          </div>

          {behind.length ? (
            <p className="mt-4 flex flex-wrap items-center gap-x-3 gap-y-1 border border-amber-line bg-amber-surface/60 px-3 py-2 text-[13px] text-amber-ink">
              <span>
                Built from <Ident>{RUN.commit?.slice(0, 7) ?? "an earlier commit"}</Ident> · {behind.length} {behind.length === 1 ? "file has" : "files have"} changed since
              </span>
              <button type="button" onClick={() => (close(), openDiff())} className="cursor-pointer text-accent underline">
                See which levels
              </button>
            </p>
          ) : null}

          <h3 className="mb-2 mt-7 text-[15px] font-semibold text-ink">Worth a second look</h3>
          {sure.look.length ? (
            <ul className="flex flex-col divide-y divide-border-gray border border-border-gray">
              {sure.look.map((x) => (
                <li key={x.path.join("/")}>
                  <button
                    type="button"
                    onClick={() => (close(), goTo(x.path))}
                    className="flex w-full cursor-pointer flex-col gap-0.5 px-3 py-2.5 text-left hover:bg-surface-container focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent"
                  >
                    <span className="flex items-center gap-2">
                      <span className="font-medium text-ink">{x.node.title}</span>
                      <StateChip state={x.node.state} alarm={x.node.alarm} />
                      <span className="ml-auto truncate text-[12px] text-faint">{x.trail}</span>
                    </span>
                    {x.why ? (
                      <span className="text-[12.5px] leading-snug">
                        <Prose text={x.why} />
                      </span>
                    ) : null}
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-muted-slate">Nothing: every level was shown from the code, and no claim needed correcting.</p>
          )}

          <details className="mt-7" onToggle={(e) => (e.currentTarget.open ? setWantLog(true) : null)}>
            <summary className="cursor-pointer text-[12.5px] text-muted-slate hover:text-ink">Generation log, for debugging the generator</summary>
            <div className="mt-3">
              {text === undefined ? (
                <p className="text-muted-slate">Loading…</p>
              ) : text === null ? (
                <p className="text-muted-slate">This blueprint has no log: it was made before runs kept one.</p>
              ) : (
                blocks.map((b, i) => <Block key={i} b={b} />)
              )}
            </div>
          </details>
        </div>
      </div>
    </Overlay>
  );
}

function Stat({ value, label, note, warn }: { value: string; label: string; note: string; warn?: boolean }) {
  return (
    <div className=" border border-border-gray px-3 py-2.5" title={note}>
      <p className={cn("tnum text-[22px] font-semibold leading-none", warn ? "text-amber-ink" : "text-ink")}>{value}</p>
      <p className="mt-1.5 text-[12px] leading-snug text-muted-slate">{label}</p>
    </div>
  );
}

type Item = { depth: number; marker: string; text: string };
type Parsed =
  | { kind: "h1" | "h2" | "h3" | "p"; text: string }
  | { kind: "list"; items: Item[] }
  | { kind: "table"; head: string[]; rows: string[][] }
  | { kind: "details"; summary: string; body: Parsed[] };

const cells = (line: string) =>
  line
    .trim()
    .replace(/^\||\|$/g, "")
    .split(/(?<!\\)\|/)
    .map((c) => c.trim().replace(/\\\|/g, "|"));

/** audit.md as blocks. Anything it does not recognise is kept as a paragraph, never dropped. */
function parse(md: string): Parsed[] {
  const lines = md.split("\n");
  const out: Parsed[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const h = /^(#{1,3}) (.*)$/.exec(line);
    if (!line.trim()) continue;
    if (h) {
      out.push({ kind: (["h1", "h2", "h3"] as const)[h[1].length - 1], text: h[2] });
    } else if (line.startsWith("<details>")) {
      const summary = /<summary>(.*)<\/summary>/.exec(line)?.[1] ?? "Details";
      const body: string[] = [];
      for (i++; i < lines.length && !lines[i].startsWith("</details>"); i++) body.push(lines[i]);
      out.push({ kind: "details", summary, body: parse(body.join("\n")) });
    } else if (line.startsWith("|")) {
      const rows: string[][] = [];
      for (; i < lines.length && lines[i].startsWith("|"); i++) if (!/^\|[-| ]+\|$/.test(lines[i].trim())) rows.push(cells(lines[i]));
      i--;
      out.push({ kind: "table", head: rows[0] ?? [], rows: rows.slice(1) });
    } else if (/^ *(- |\d+\. )/.test(line)) {
      const items: Item[] = [];
      for (; i < lines.length; i++) {
        const m = /^( *)(- |\d+\. )(.*)$/.exec(lines[i]);
        if (!m) break;
        items.push({ depth: Math.floor(m[1].length / 2), marker: m[2].trim(), text: m[3] });
      }
      i--;
      out.push({ kind: "list", items });
    } else {
      // A paragraph runs to the next blank line or block.
      const para = [line];
      while (i + 1 < lines.length && lines[i + 1].trim() && !/^(#|\||<|- |\d+\. | +- )/.test(lines[i + 1])) para.push(lines[++i]);
      out.push({ kind: "p", text: para.join(" ") });
    }
  }
  return out;
}

function Block({ b }: { b: Parsed }) {
  switch (b.kind) {
    case "h1":
    case "h2":
      return <h3 className="mb-2 mt-7 text-[15px] font-semibold text-ink first:mt-0">{inline(b.text)}</h3>;
    case "h3":
      return <h4 className="mb-1.5 mt-5 text-[13.5px] font-semibold text-ink">{inline(b.text)}</h4>;
    case "p":
      return <p className="mb-2.5">{inline(b.text)}</p>;
    case "list":
      return (
        <ul className="mb-3 flex flex-col gap-1">
          {b.items.map((it, i) => (
            <li key={i} className="flex gap-2" style={{ paddingLeft: it.depth * 18 }}>
              <span className="shrink-0 select-none font-mono text-[12px] text-faint">{it.marker === "-" ? "·" : it.marker}</span>
              <span className="min-w-0">{inline(it.text)}</span>
            </li>
          ))}
        </ul>
      );
    case "table":
      return (
        <div className="mb-3 overflow-x-auto border border-border-gray">
          <table className="w-full border-collapse text-left text-[12.5px]">
            <thead className="bg-surface-container-low text-ink">
              <tr>
                {b.head.map((c, i) => (
                  <th key={i} className="px-3 py-2 font-semibold">
                    {inline(c)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {b.rows.map((r, i) => (
                <tr key={i} className="border-t border-border-gray align-top">
                  {r.map((c, j) => (
                    <td key={j} className={cn("px-3 py-2", j === 0 && "whitespace-nowrap font-medium text-ink")}>
                      {inline(c)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    case "details":
      return (
        <details className="mb-3 border border-border-gray bg-surface px-3 py-2 [&_ul]:mb-0">
          <summary className="cursor-pointer text-[12.5px] font-medium text-ink">{inline(b.summary)}</summary>
          <div className="mt-2 font-mono text-[11.5px]">
            {b.body.map((x, i) => (
              <Block key={i} b={x} />
            ))}
          </div>
        </details>
      );
  }
}

/** **bold**, _italic_ and `code`, the inline marks audit.md uses. */
function inline(text: string): React.ReactNode[] {
  return text.split(/(`[^`]+`|\*\*[^*]+\*\*|(?<![\w])_[^_]+_(?![\w]))/).map((part, i) =>
    part.startsWith("`") && part.endsWith("`") && part.length > 1 ? (
      <Ident key={i}>{part.slice(1, -1)}</Ident>
    ) : part.startsWith("**") && part.endsWith("**") && part.length > 3 ? (
      <strong key={i} className="font-semibold text-ink">
        {part.slice(2, -2)}
      </strong>
    ) : /^_.+_$/.test(part) ? (
      <em key={i}>{part.slice(1, -1)}</em>
    ) : (
      part
    ),
  );
}

app/components/blueprint/blocks.tsx:
"use client";

import { useLayoutEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/client/utils";
import { Eyebrow, OriginMark, Prose } from "@/components/ui/state";
import type { Anatomy, CodeRef, Issue } from "@/lib/blueprint/schema";
import type { Slice as RepoSlice } from "@/lib/server/repo";
import { useChangedCode, useBlueprint } from "@/components/blueprint/blueprint-context";
import { useMayBeStale } from "@/components/chrome/crumbs";
import { readSource } from "@/lib/blueprint/source";
import { openDoc } from "@/components/blueprint/docs";
import { SHARED_TAG, sharedTagRect } from "@/lib/blueprint/diagram";
import { gridLayout } from "@/lib/blueprint/diagram-elk";
import { useDiagramLayout } from "@/components/blueprint/use-diagram-layout";
import { TINT, WORD as WORD_OF, useDiff } from "@/components/review/diff";
import { DiagramChanges, changesUnder } from "@/components/review/diagram-diff";

/**
 * The blocks a reader learns from without opening code (round 3, D34): the
 * picture, the real values, who talks to whom, what is on screen, what a stored
 * value looks like. Typeset at reading size for the open level — unlike the
 * older anatomy blocks, which were built for a 340px card and are zoomed up.
 */

export type Explained = Extract<
  Anatomy,
  { kind: "diagram" | "table" | "sequence" | "screen" | "example" | "note" }
>;

export function isExplained(b: Anatomy): b is Explained {
  return ["diagram", "table", "sequence", "screen", "example", "note"].includes(b.kind);
}

export function ExplainedBlock({
  block,
  onOpen,
  hrefFor,
  onCode,
  onRef,
}: {
  block: Explained;
  /** Opens the part a diagram box names (D40). Absent where a block is drawn
      inside a card, which has no room to be navigated from. */
  onOpen?: (id: string) => void;
  /** That part's own URL, so a box is a real link: focusable, and openable
      in a new tab like any other. */
  hrefFor?: (id: string) => string;
  /** Shows the lines a sequence message cites (`Message.at`). */
  onCode?: (at: string, heading: string, detail?: string) => void;
  /** Opens what explains the code a scenery box stands for (`DiagramBox.ref`). */
  onRef?: (ref: string) => void;
}) {
  switch (block.kind) {
    case "diagram":
      return <Diagram block={block} onOpen={onOpen} hrefFor={hrefFor} onRef={onRef} onCode={onCode} />;
    case "table":
      return <Table block={block} />;
    case "sequence":
      return <Sequence block={block} onCode={onCode} />;
    case "screen":
      return <Screen block={block} onCode={onCode} />;
    case "example":
      return <Example block={block} />;
    case "note":
      return <Note block={block} />;
  }
}

function Caption({ children }: { children?: string }) {
  return children ? (
    <p className="mb-2.5 text-[13px] font-medium text-on-surface-variant">{children}</p>
  ) : null;
}

/* ── diagram ─────────────────────────────────────────────────── */

const TONE = {
  plain: { stroke: "var(--color-border-strong)", fill: "var(--color-card)", ink: "var(--color-ink)", line: "var(--color-wire)" },
  good: { stroke: "var(--color-accent)", fill: "var(--color-accent-surface)", ink: "var(--color-ink)", line: "var(--color-accent)" },
  warn: { stroke: "var(--color-amber-ink)", fill: "var(--color-amber-surface)", ink: "var(--color-amber-ink)", line: "var(--color-amber-ink)" },
} as const;

/** How many section hues exist. No diagram opens more parts than this. */
const SECTION_HUES = 7;

/**
 * The colour of the Nth part a level declares. Exported so the list below the
 * picture can carry the same dot, which is the whole point: the box and the
 * index entry are the same thing seen twice.
 */
export function sectionTone(i: number) {
  const k = (i % SECTION_HUES) + 1;
  return { ink: `var(--color-sec-${k}-ink)`, surface: `var(--color-sec-${k}-surface)` };
}

/**
 * Which part each box opens, as an index into the level's parts — so a box
 * can be coloured by the SECTION it leads to rather than by the fact that it
 * leads anywhere at all.
 *
 * That fact is already carried by the corner badge (D43), so tinting every
 * live box one shared colour said a second time what the arrow said once.
 * Colour is better spent on association: a part drawn as three boxes makes
 * those three one colour, and 64 of 254 diagrams have such a part.
 */
export function sectionOrder(
  block: Extract<Anatomy, { kind: "diagram" }>,
  owns: (id: string) => boolean,
): string[] {
  const order: string[] = [];
  for (const b of block.boxes) {
    if (b.opens && owns(b.opens) && !order.includes(b.opens)) order.push(b.opens);
  }
  return order;
}

/**
 * How far past its natural size a picture may be blown up to fill the level.
 * Past roughly this the labels read as a poster rather than a diagram, and a
 * six-box state machine starts looking like a slide.
 */
const DIAGRAM_MAX_SCALE = 1.35;

/**
 * Boxes on a grid, arrows routed between them. Drawn at real pixels and never
 * scaled down: a figure whose labels shrink below reading size is decoration
 * (the measured failure in `Figure`), so a wide one scrolls instead.
 */
function Diagram({
  block,
  onOpen,
  hrefFor,
  onRef,
  onCode,
}: {
  block: Extract<Anatomy, { kind: "diagram" }>;
  onOpen?: (id: string) => void;
  hrefFor?: (id: string) => string;
  onRef?: (ref: string) => void;
  /** Shows the line an arrow cites (`DiagramArrow.at`), from its label. */
  onCode?: (at: string, heading: string, detail?: string) => void;
}) {
  const elk = useDiagramLayout(block);
  const fallback = useMemo(() => (elk ? null : gridLayout(block)), [elk, block]);
  // Until the worker answers, the grid layout holds the space unseen, so the
  // page below does not jump twice; it shows only where ELK failed.
  const waiting = elk === undefined;
  const { W, H, boxes, arrows, rules, frames } = elk ?? fallback!;
  // Only a picture that actually leads somewhere dims its scenery: on a
  // diagram where nothing opens, every box is equally "inert" and dimming
  // them all would just make the picture grey.
  const navigable = Boolean(onOpen) && block.boxes.some((b) => b.opens);
  // A box counts as leading into a section only where the level actually owns
  // that part — the same test `onOpen` makes before it navigates.
  const order = sectionOrder(block, (id) => Boolean(hrefFor?.(id)));
  const sectionOf = (id: string | undefined) => (id ? order.indexOf(id) : -1);
  // In diff mode a box says what happened to the section it opens: amber
  // where its code changed, red where it is gone, the rest receding.
  // A section whose own lines held but something beneath it changed reads
  // as changed too: on a review, the boxes on every level are the way down
  // to the change, not only the one that holds it.
  const diff = useDiff()?.diff;
  const changedCode = useChangedCode();
  const sections = diff?.sections;
  const verdictOf = (id: string | undefined) => {
    const s = id ? sections?.find((x) => x.id === id) : undefined;
    return s && s.verdict !== "untouched" ? s.verdict : s?.inside ? ("changed" as const) : undefined;
  };
  const moved = block.boxes.some((b) => verdictOf(b.opens));
  // An arrow whose cited line changed: the path itself was edited.
  const hot = new Set(block.arrows.filter((a) => a.at && diff?.arrows?.includes(a.at)).map((a) => `${a.from}→${a.to}`));
  // A part that calls into a changed one, by an arrow drawn on this picture:
  // its own code held, but what it relies on did not.
  const boxVerdict = (id: string) => verdictOf(block.boxes.find((b) => b.id === id)?.opens);
  const affected = new Set(block.arrows.filter((a) => boxVerdict(a.to) && !boxVerdict(a.from)).map((a) => a.from));
  // Each changed box's size, and the lines behind it, as a pull request lists
  // a file (components/review/diagram-diff.tsx).
  const changes = useMemo(
    () =>
      diff
        ? block.boxes.flatMap((b) => {
            const ch = b.opens ? changesUnder(diff, b.opens) : null;
            return ch ? [{ box: b.id, label: b.label, opens: b.opens!, ch }] : [];
          })
        : [],
    [diff, block.boxes],
  );
  const [lit, setLit] = useState<string | null>(null);
  // The box under the pointer or the keyboard: its lines glow and the rest of
  // the picture steps back, so who it talks to reads at a glance.
  const [held, setHeld] = useState<string | null>(null);
  const touches = (a: { from: string; to: string }) => held !== null && (a.from === held || a.to === held);
  const kin = new Set(held ? [held, ...arrows.filter(touches).flatMap((a) => [a.from, a.to])] : []);
  const fade = "transition-opacity duration-150 motion-reduce:transition-none";

  return (
    <figure className="min-w-0">
      {/* The caption sits ABOVE the picture: it says what you are about to
          look at, which is only useful before you look. Underneath it was a
          footnote to a diagram the reader had already tried to decode. */}
      <figcaption className="mb-3 max-w-[1000px]">
        <span className="text-[14px] font-medium text-on-surface">{block.caption}</span>
        {navigable ? (
          <span className="ml-2.5 whitespace-nowrap text-[12px] text-faint">
            colours match the parts below
          </span>
        ) : null}
      </figcaption>
      {/* No frame: the picture is the level, not an illustration pasted onto
          it (D41). A border here drew a box around the one thing that should
          read as the page itself. */}
      <div className="overflow-x-auto">
        {/* Grows into the width the level has, up to DIAGRAM_MAX_SCALE — the
            picture is the main thing on the page (D40) and was rendering at
            its natural size inside a column half again as wide, which is the
            smallness zoom (D45) was invented to work around. Still never
            below 70%, where the labels stop being readable. */}
        <svg
          viewBox={`0 0 ${W} ${H}`}
          role="img"
          aria-label={block.caption}
          className={navigable ? "dg-nav block h-auto" : "block h-auto"}
          // Visible: a change's tag rides the top edge of a box in the first row.
          // --dg-zoom is the reader's pinch (components/chrome/zoom.tsx): it
          // resizes the picture alone, so the prose around it keeps its size.
          style={{
            width: `calc(clamp(${W * 0.7}px, 100%, ${W * DIAGRAM_MAX_SCALE}px) * var(--dg-zoom, 1))`,
            overflow: "visible",
            opacity: waiting ? 0 : 1,
            transition: "opacity 160ms ease-out",
          }}
        >
          <defs>
            {(["plain", "good", "warn"] as const).map((t) => (
              <marker
                key={t}
                id={`dg-${t}`}
                viewBox="0 0 8 8"
                refX="7"
                refY="4"
                markerWidth="7"
                markerHeight="7"
                orient="auto-start-reverse"
              >
                <path d="M1 1.2L7 4 1 6.8z" fill={TONE[t].line} />
              </marker>
            ))}
          </defs>
          {/* Boxes no arrow touches sit apart: a faint frame in a free corner, or a rule between them and the rest. */}
          {frames.map((f, i) => (
            <rect key={`f${i}`} x={f.x} y={f.y} width={f.w} height={f.h} rx="6" fill="var(--color-card)" />
          ))}
          {rules.map((r, i) => (
            <line key={`r${i}`} x1={r.x1} y1={r.y1} x2={r.x2} y2={r.y2} stroke="var(--color-border-gray)" />
          ))}
          {arrows.map(({ d, tone, label, from, to, start, end }, i) => {
            const ways = new Set((label?.lines ?? [{ from, to }]).map((l) => `${l.from}→${l.to}`));
            const isHot = [...ways].some((k) => hot.has(k));
            // Lighter, not dotted, when the code links these two only in a way
            // the fact graph cannot follow (DiagramArrow.inferred): on a level
            // where every link crosses apps, dots on every line were noise.
            const pair = block.arrows.filter((a) => ways.has(`${a.from}→${a.to}`));
            const inferred = pair.length > 0 && pair.every((a) => a.inferred);
            const glow = touches({ from, to });
            const line = isHot ? TINT.changed.line : TONE[tone].line;
            return (
              <g key={i} className={fade} opacity={held && !glow ? 0.15 : 1}>
                {glow ? <path d={d} fill="none" stroke={line} strokeWidth={7} strokeOpacity={0.22} strokeLinejoin="round" strokeLinecap="round" /> : null}
                <path
                  d={d}
                  fill="none"
                  stroke={line}
                  strokeWidth={isHot ? 2.5 : 1.5}
                  strokeOpacity={inferred && !isHot && !glow ? 0.5 : 1}
                  strokeDasharray={tone === "warn" ? "5 4" : undefined}
                  strokeLinejoin="round"
                  markerStart={start ? `url(#dg-${tone})` : undefined}
                  markerEnd={end ? `url(#dg-${tone})` : undefined}
                >
                  {inferred ? <title>Read from the code, not a call the code graph confirms</title> : null}
                </path>
              </g>
            );
          })}
          {/* Labels go over every line, so no other line runs through one. */}
          {arrows.map(({ label, from, to }, i) => {
            if (!label) return null;
            const name = (id: string) => block.boxes.find((x) => x.id === id)?.label ?? id;
            // Arrows between the same two boxes are drawn as one, and a pair
            // that calls both ways too; each line of the label opens the line
            // of code its own direction cites.
            const atOf = (f: string, t: string) =>
              block.arrows.find((a) => a.from === f && a.to === t && a.at)?.at ??
              block.arrows.find((a) => a.from === t && a.to === f && a.at)?.at;
            return (
              <g key={`l${i}`} className={fade} opacity={held && !touches({ from, to }) ? 0.2 : 1}>
                <rect x={label.x} y={label.y} width={label.w} height={label.h} rx={4} fill="var(--color-paper)" />
                {label.lines.map((l, k) => {
                  const at = atOf(l.from, l.to);
                  const show = at && onCode ? () => onCode(at, `${name(l.from)} → ${name(l.to)}`, l.text) : undefined;
                  return (
                    <text
                      key={k}
                      x={label.x + label.w / 2}
                      y={label.y + 14 + k * 16}
                      textAnchor="middle"
                      fontSize="12"
                      fill="var(--color-muted-slate)"
                      onClick={show}
                      className={show ? "cursor-pointer hover:fill-accent" : undefined}
                    >
                      {at ? <title>{at}</title> : null}
                      {l.text}
                    </text>
                  );
                })}
              </g>
            );
          })}
          {boxes.map(({ x, y, w, h, b }) => {
            // Live where the author named the part this box belongs to, or the code another section explains.
            const go = b.opens && onOpen ? () => onOpen(b.opens!) : b.ref && onRef ? () => onRef(b.ref!) : undefined;
            const authored = b.tone && b.tone !== "plain";
            // An authored tone still wins: `good` and `warn` are claims about
            // the code, and a section hue is only an index.
            const sec = authored ? -1 : sectionOf(b.opens);
            const t = TONE[b.tone ?? "plain"];
            const v = verdictOf(b.opens);
            const near = !v && affected.has(b.id);
            const ch = changes.find((c) => c.box === b.id)?.ch;
            const tag = ch ? (ch.added || ch.removed ? `+${ch.added} −${ch.removed}` : WORD_OF[ch.verdict]) : "";
            const tagW = tag.length * 6.6 + 14;
            const fill = v ? TINT[v].surface : sec >= 0 ? sectionTone(sec).surface : t.fill;
            const stroke = v ? TINT[v].line : near ? TINT.changed.line : sec >= 0 ? sectionTone(sec).ink : t.stroke;
            const ink = v ? TINT[v].ink : sec >= 0 ? sectionTone(sec).ink : t.ink;
            const sharedTag = b.shared ? sharedTagRect({ x, y, w }) : null;
            return (
              <Box
                key={b.id}
                live={Boolean(go)}
                opens={b.opens}
                href={b.opens ? hrefFor?.(b.opens) : undefined}
                onActivate={go}
                onHold={(on) => setHeld(on ? b.id : null)}
                label={b.label}
              >
                <g className={fade} opacity={held && !kin.has(b.id) ? 0.4 : 1}>
                <rect
                  x={x}
                  y={y}
                  width={w}
                  height={h}
                  rx="3"
                  fill={fill}
                  stroke={stroke}
                  // A hairline, like every other container on the page: the
                  // tint already says which section it is, and a heavy edge
                  // made the picture louder than the tables beside it.
                  strokeWidth={lit === b.id ? 3.5 : v ? 2 : 1}
                  strokeOpacity={v ? 1 : sec >= 0 ? 0.55 : 1}
                  strokeDasharray={b.tone === "warn" || v === "removed" ? "5 4" : near ? "3 3" : undefined}
                  opacity={moved && !v && !near ? 0.45 : 1}
                />
                <text
                  x={x + w / 2}
                  y={b.sub ? y + 26 : y + h / 2 + 6}
                  textAnchor="middle"
                  fontFamily="var(--font-display), Georgia, serif"
                  fontSize="18"
                  letterSpacing="-0.01em"
                  fill={ink}
                  opacity={moved && !v && !near ? 0.5 : 1}
                  textDecoration={v === "removed" ? "line-through" : undefined}
                >
                  {b.label}
                </text>
                {/* Code under this part changed and the blueprint has not followed yet (lib/server/live.ts): a dot on the corner, the box itself untouched. */}
                {!diff && b.opens && changedCode.get(b.opens) ? (
                  <circle cx={x + w - 9} cy={y + 9} r={3.5} fill="var(--color-amber-ink)">
                    <title>{`Code changed: ${changedCode.get(b.opens)!.join(", ")}. The blueprint follows once they are committed.`}</title>
                  </circle>
                ) : null}
                {v ? (
                  <text x={x + w - 8} y={y + 15} textAnchor="end" fontSize="12" fontWeight="700" fill={TINT[v].ink}>
                    {TINT[v].mark}
                  </text>
                ) : null}
                {/* The change's size, on the box's top edge where a label never sits. */}
                {tag && v ? (
                  <g>
                    <rect x={x + 8} y={y - 9} width={tagW} height={18} rx="9" fill={TINT[v].surface} stroke={TINT[v].line} />
                    {ch!.added || ch!.removed ? (
                      <text x={x + 15} y={y + 4} fontSize="11" fontWeight="600" fontFamily="var(--font-mono)">
                        <tspan fill={TINT.added.ink}>+{ch!.added}</tspan>
                        <tspan fill={TINT.removed.ink}> −{ch!.removed}</tspan>
                      </text>
                    ) : (
                      <text x={x + 15} y={y + 4} fontSize="11" fontWeight="600" fill={TINT[v].ink}>
                        {tag}
                      </text>
                    )}
                  </g>
                ) : null}
                {b.sub ? (
                  <text x={x + w / 2} y={y + 43} textAnchor="middle" fontSize="12" fill="var(--color-faint)">
                    {b.sub}
                  </text>
                ) : null}
                {/* Most boxes here call this one: one tag on its bottom edge instead of an arrow from each (scripts/generate/thin.ts). */}
                {sharedTag ? (
                  <g opacity={moved && !v && !near ? 0.5 : 1}>
                    <title>Most of the other parts here call this one, so those arrows are left out.</title>
                    <rect x={sharedTag.x} y={sharedTag.y} width={sharedTag.w} height={sharedTag.h} rx={sharedTag.h / 2} fill={fill} stroke={stroke} strokeOpacity={sec >= 0 ? 0.55 : 1} />
                    <text x={sharedTag.x + sharedTag.w / 2} y={sharedTag.y + 12} textAnchor="middle" fontSize="11" fontWeight="600" fill={ink}>
                      {SHARED_TAG}
                    </text>
                  </g>
                ) : null}
                </g>
              </Box>
            );
          })}
        </svg>
      </div>
      <DiagramChanges items={changes} onHover={setLit} onOpen={onOpen} />
    </figure>
  );
}

/**
 * One diagram box. A box that opens a part is an <a> so that focus, Enter and
 * a screen reader all work: Chrome refuses focus to an SVG <g>, tabIndex or
 * not, which would have left the picture mouse-only. An inert box is a plain
 * <g> and announces nothing extra.
 */
function Box({
  live,
  opens,
  href,
  onActivate,
  onHold,
  label,
  children,
}: {
  live: boolean;
  /** The part it opens, so a rewrite of that part can light the box (components/blueprint/flash.tsx). */
  opens?: string;
  /** A real destination, so the link focuses and Enter fires natively. */
  href?: string;
  onActivate?: () => void;
  /** The pointer or the keyboard is on this box, or has left it. */
  onHold?: (on: boolean) => void;
  label: string;
  children: React.ReactNode;
}) {
  const hold = {
    onMouseEnter: () => onHold?.(true),
    onMouseLeave: () => onHold?.(false),
    onFocus: () => onHold?.(true),
    onBlur: () => onHold?.(false),
  };
  if (!live)
    return (
      <g data-pick={label} data-opens={opens} {...hold}>
        {children}
      </g>
    );
  return (
    <a
      {...hold}
      data-pick={label}
      data-opens={opens}
      className="dg-live"
      href={href}
      // A box pointing at another section has no URL of its own; it still takes focus.
      tabIndex={href ? undefined : 0}
      aria-label={`${label} — open this part`}
      onClick={(e) => {
        // Left-click navigates in place; cmd/ctrl-click and the context menu
        // keep the browser's own behaviour, because the href is real.
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
        e.preventDefault();
        onActivate?.();
      }}
      onKeyDown={(e) => {
        // Enter on an <a> fires a click only when it has an href.
        if (e.key === " " || (e.key === "Enter" && !href)) {
          e.preventDefault();
          onActivate?.();
        }
      }}
    >
      {children}
    </a>
  );
}

/* ── table ───────────────────────────────────────────────────── */

const TABLE_ROWS_FOLDED = 12;

function Table({ block }: { block: Extract<Anatomy, { kind: "table" }> }) {
  const [all, setAll] = useState(false);
  const rows = all ? block.rows : block.rows.slice(0, TABLE_ROWS_FOLDED);
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div className="overflow-x-auto border border-border-gray bg-card">
        <table className="w-full border-collapse text-left text-[13.5px]">
          <thead>
            <tr className="border-b border-border-gray bg-surface">
              {block.columns.map((c) => (
                <th key={c} className="px-4 py-2 font-mono text-[10.5px] font-medium uppercase tracking-[0.07em] text-faint">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr
                key={i}
                data-pick={r[0]}
                data-pick-text={block.columns.map((c, j) => `${c}: ${r[j] ?? ""}`).join("\n")}
                className="border-b border-border-gray last:border-0"
              >
                {r.map((cell, j) => (
                  <td
                    key={j}
                    className={cn(
                      "px-4 py-2 align-top leading-snug",
                      j === 0 ? "font-medium text-ink" : "text-on-surface-variant",
                    )}
                  >
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {block.rows.length > TABLE_ROWS_FOLDED ? (
        <button
          onClick={() => setAll((v) => !v)}
          className="mt-2 text-[12.5px] font-medium text-accent hover:underline"
        >
          {all ? "Show fewer" : `Show all ${block.rows.length}`}
        </button>
      ) : null}
    </div>
  );
}

/* ── sequence ────────────────────────────────────────────────── */

/**
 * Who talks to whom, top to bottom. One column per actor with a faint line
 * down from it; each message is an arrow between two of those lines, numbered,
 * with its words on top. A message to itself is a note on that actor's line.
 */
/**
 * A colour per actor, by position in `actors`. Assigned rather than authored:
 * which participant is which is already in the data, and an author choosing
 * hues per sequence would drift between levels of the same blueprint.
 */
function actorTone(i: number) {
  const k = (i % 4) + 1;
  return { ink: `var(--color-actor-${k})`, surface: `var(--color-actor-${k}-surface)` };
}

function Sequence({
  block,
  onCode,
}: {
  block: Extract<Anatomy, { kind: "sequence" }>;
  onCode?: (at: string, heading: string, detail?: string) => void;
}) {
  const n = block.actors.length;
  const centre = (a: string) => ((block.actors.indexOf(a) + 0.5) / n) * 100;
  const toneOfActor = (a: string) => actorTone(block.actors.indexOf(a));
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div className="overflow-x-auto border border-border-gray bg-card/80 px-4 pb-4 pt-3">
        <div className="relative" style={{ minWidth: n * 150 }}>
          {/* lifelines */}
          {block.actors.map((a) => (
            <span
              key={a}
              aria-hidden
              className="absolute bottom-0 top-9 border-l border-dashed opacity-45"
              style={{ left: `${centre(a)}%`, borderColor: toneOfActor(a).ink }}
            />
          ))}
          <div className="relative flex">
            {block.actors.map((a) => {
              const t = toneOfActor(a);
              return (
                <div key={a} className="flex flex-1 justify-center">
                  <span
                    className=" border px-3 py-1.5 text-[13px] font-semibold"
                    style={{ borderColor: t.ink, background: t.surface, color: t.ink }}
                  >
                    {a}
                  </span>
                </div>
              );
            })}
          </div>
          <ol className="relative mt-3">
            {block.rows.map((m, i) => {
              const a = centre(m.from);
              const b = centre(m.to);
              const self = m.from === m.to;
              const left = Math.min(a, b);
              const width = Math.abs(b - a);
              const warn = m.state !== "derived";
              const code = m.at && onCode ? () => onCode(m.at!, `${i + 1} · ${m.from} → ${m.to}`, `${m.label}${m.note ? ` — ${m.note}` : ""}`) : undefined;
              return (
                <li
                  key={i}
                  data-pick={m.label}
                  data-pick-text={`${m.from} → ${m.to}: ${m.label}${m.note ? ` (${m.note})` : ""}`}
                  onClick={code}
                  onKeyDown={code ? (e) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), code()) : undefined}
                  role={code ? "button" : undefined}
                  data-code-step={code ? "" : undefined}
                  tabIndex={code ? 0 : undefined}
                  title={code ? "Show the code for this message" : undefined}
                  className={cn("relative h-[76px]", code && "cursor-pointer transition-colors hover:bg-surface-container-low")}
                >
                  <span className="absolute bottom-[14px] left-0 font-mono text-[10.5px] text-faint">
                    {i + 1}
                    {code ? <span className="ml-1.5">{"</>"}</span> : null}
                  </span>
                  {self ? (
                    <div
                      className="absolute top-[8px] -translate-x-1/2 border border-border-gray bg-surface-container-low px-2.5 py-1.5 text-center text-[12.5px] text-on-surface"
                      style={{ left: `${a}%`, maxWidth: `${100 / n}%` }}
                    >
                      {m.label}
                      {m.note ? <span className="block text-[11.5px] text-faint">{m.note}</span> : null}
                    </div>
                  ) : (
                    <div className="absolute bottom-[18px]" style={{ left: `${left}%`, width: `${width}%` }}>
                      <p className="line-clamp-2 px-3 text-center text-[12.5px] leading-tight text-on-surface" title={m.label}>
                        {m.label}
                      </p>
                      {/* The line is the SENDER's colour, so a reply reads as
                          coming back without reading its label. A message the
                          blueprint is unsure of keeps amber and its dashes: doubt
                          outranks identity. */}
                      <div
                        className={cn("relative mt-1.5 h-0 border-t-[1.5px]", warn && "border-dashed")}
                        style={{ borderTopColor: warn ? "var(--color-amber-ink)" : toneOfActor(m.from).ink }}
                      >
                        <span
                          aria-hidden
                          className={cn(
                            "absolute -top-[6px] size-0 border-y-[5px] border-y-transparent",
                            a < b ? "right-0 border-l-[8px]" : "left-0 border-r-[8px]",
                          )}
                          style={{
                            [a < b ? "borderLeftColor" : "borderRightColor"]:
                              warn ? "var(--color-amber-ink)" : toneOfActor(m.from).ink,
                          }}
                        />
                      </div>
                      {m.note ? (
                        <p className="truncate px-3 pt-1 text-center text-[11.5px] text-faint" title={m.note}>
                          {m.note}
                        </p>
                      ) : null}
                    </div>
                  )}
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </div>
  );
}

/* ── screen ──────────────────────────────────────────────────── */

/**
 * What the user sees, top to bottom, in the frame of what it runs on — a
 * phone, or a browser window for a web page — with what each thing does
 * written beside it rather than on top of it, a line running from the thing
 * to its note. A narrow page puts the notes under the screen, and falls back to
 * numbers.
 */
function Screen({ block, onCode }: { block: Extract<Anatomy, { kind: "screen" }>; onCode?: (at: string, heading: string, detail?: string) => void }) {
  // The screen's states, one set of tabs where the first state-bound item sits:
  // picking one shows every item of that state wherever it is, since a
  // generated screen interleaves them (status line for text, size for images).
  const runs = useMemo(() => {
    const first = block.items.findIndex((it) => it.when);
    return new Map(block.items.flatMap((it, i) => (it.when ? [[i, first] as const] : [])));
  }, [block.items]);
  const [picked, setPicked] = useState<Record<number, string>>({});
  const stateOf = (run: number) => picked[run] ?? block.items[run].when!;
  const shown = block.items.map((it, i) => ({ ...it, i })).filter((it) => !runs.has(it.i) || it.when === stateOf(runs.get(it.i)!));
  const noted = shown.filter((it) => it.note);
  const num = new Map(noted.map((it, k) => [it.i, k + 1]));
  const [box, paths] = useCallouts(noted.length > 0, JSON.stringify(picked));
  // Numbers until the lines are measured, and wherever they cannot be drawn.
  const n = (i: number) => (paths ? undefined : num.get(i));
  const codeOf = (it: (typeof shown)[number]) => (it.at && onCode ? () => onCode(it.at!, it.label, it.note) : undefined);
  const clickable = (code?: () => void) =>
    code
      ? {
          onClick: code,
          onKeyDown: (e: React.KeyboardEvent) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), code()),
          role: "button",
          tabIndex: 0,
          title: "Show the code that draws this",
          "data-code-step": "",
        }
      : {};
  const items = shown.map((it) => {
    const run = runs.get(it.i);
    const tabs =
      run !== undefined && it.i === shown.find((x) => runs.get(x.i) === run)?.i ? (
        <div key={`tabs-${it.i}`} className="-mb-1 flex flex-wrap gap-1">
          {[...new Set(block.items.filter((_, j) => runs.get(j) === run).map((x) => x.when!))].map((w) => (
            <button
              key={w}
              type="button"
              onClick={() => setPicked((p) => ({ ...p, [run!]: w }))}
              className={cn(
                "border px-1.5 py-[1px] font-mono text-[10px]",
                w === stateOf(run!) ? "border-border-strong bg-surface-container text-ink" : "border-border-gray text-faint hover:text-on-surface-variant",
              )}
            >
              {w}
            </button>
          ))}
        </div>
      ) : null;
    const code = codeOf(it);
    return [
      tabs,
      <div key={it.i} data-pick={it.label} data-thing={num.get(it.i)} {...clickable(code)} className={cn(code && "cursor-pointer transition-opacity hover:opacity-80")}>
        <ScreenThing type={it.type} label={it.label} n={n(it.i)} />
      </div>,
    ];
  });
  return (
    <div className="min-w-0">
      <Caption>{block.caption}</Caption>
      <div ref={box} className="relative flex flex-wrap items-start gap-6">
        {block.device !== "phone" ? (
          // A web page: a browser window, its address bar showing the route.
          <div className="w-[440px] max-w-full shrink-0 overflow-hidden border-[1.5px] border-border-strong bg-card shadow-panel">
            <div className="flex items-center gap-3 border-b border-border-gray bg-surface-container px-3 py-2">
              <div className="flex shrink-0 gap-1.5">
                {[0, 1, 2].map((i) => (
                  <span key={i} className="size-[9px] rounded-full bg-border-strong" />
                ))}
              </div>
              {/* Empty without a route: the title is just below, and an older blueprint has none. */}
              <p className="h-[22px] min-w-0 flex-1 truncate bg-card px-2.5 py-1 font-mono text-[11px] leading-[14px] text-muted-slate">
                {block.route}
              </p>
            </div>
            <div className="flex flex-col gap-2 px-5 pb-5 pt-4">
              <p className="mb-1 text-[13px] font-semibold text-ink">{block.title}</p>
              {items}
            </div>
          </div>
        ) : (
          <div className="w-[280px] shrink-0 rounded-[30px] border-[1.5px] border-border-strong bg-card p-3 shadow-panel">
            <div className="mx-auto mb-3 h-[5px] w-16 rounded-full bg-surface-container" />
            <p className="mb-3 px-2 text-center text-[13px] font-semibold text-ink">{block.title}</p>
            <div className="flex flex-col gap-2 px-2 pb-3">{items}</div>
          </div>
        )}
        {noted.length ? (
          // Reading size, not caption size (D44). This list sits beside a
          // ~700px screen with room to spare, so it was set small and tight
          // against a column of empty space. It is the explanation of the
          // screen — the main text of the block — and is typeset as such.
          <ol className="flex min-w-[280px] max-w-[760px] flex-1 flex-col gap-4 pt-10">
            {noted.map((it, k) => {
              const code = codeOf(it);
              return (
                <li
                  key={it.i}
                  data-pick={it.label}
                  data-note={k + 1}
                  {...clickable(code)}
                  className={cn("flex gap-3 text-[15.5px] leading-relaxed", code && "-mx-2 cursor-pointer px-2 transition-colors hover:bg-surface-container-low")}
                >
                  {paths ? null : <Badge n={k + 1} />}
                  <span>
                    <span className="font-semibold text-ink">{it.label}</span>
                    {it.when ? <span className="ml-1.5 font-mono text-[11px] text-faint">{it.when}</span> : null}
                    <span className="text-on-surface-variant">
                      {" — "}
                      <Prose text={it.note ?? ""} />
                    </span>
                    {code ? <span className="ml-1.5 font-mono text-[10.5px] text-faint">{"</>"}</span> : null}
                  </span>
                </li>
              );
            })}
          </ol>
        ) : null}
        {paths ? (
          <svg aria-hidden className="pointer-events-none absolute inset-0 size-full overflow-visible text-faint">
            {paths.map((l) => (
              <g key={l.n}>
                <path d={l.d} fill="none" stroke="currentColor" strokeWidth={1.25} />
                <circle cx={l.from.x} cy={l.from.y} r={3} fill="currentColor" />
                <circle cx={l.to.x} cy={l.to.y} r={3} fill="currentColor" />
              </g>
            ))}
          </svg>
        ) : null}
      </div>
    </div>
  );
}

type Pt = { x: number; y: number };

/** Where `el` sits inside `box`, in the layout's own pixels — the same space an SVG inside `box` draws in, whatever zoom or scale is applied above. */
function offsetIn(el: HTMLElement, box: HTMLElement) {
  let x = 0, y = 0;
  for (let at: HTMLElement | null = el; at && at !== box; at = at.offsetParent as HTMLElement | null) {
    x += at.offsetLeft;
    y += at.offsetTop;
  }
  return { x, y, w: el.offsetWidth, h: el.offsetHeight };
}

/**
 * Lines from each noted thing on a drawn screen (`data-thing`) to its note
 * (`data-note`), measured after layout and again on every resize. The paths
 * are null when there is nothing to join or the notes have wrapped under the
 * screen, which is the cue to number them instead.
 */
function useCallouts(on: boolean, layout?: string) {
  const box = useRef<HTMLDivElement>(null);
  const [paths, setPaths] = useState<{ n: string; d: string; from: Pt; to: Pt }[] | null>(null);
  useLayoutEffect(() => {
    const el = box.current;
    if (!on || !el) return;
    const measure = () => {
      const out: { n: string; d: string; from: Pt; to: Pt }[] = [];
      for (const note of el.querySelectorAll<HTMLElement>("[data-note]")) {
        const item = el.querySelector<HTMLElement>(`[data-thing="${note.dataset.note}"]`);
        if (!item) continue;
        // A heading or a line of text spans the screen's width but its words
        // do not: the line leaves from the end of the words, not empty space.
        const thing = item.querySelector<HTMLElement>("[data-anchor]") ?? item;
        const a = offsetIn(thing, el), b = offsetIn(note, el);
        // Wrapped: the note is not to the right of the screen, so a line would cut across it.
        const row = offsetIn(item, el);
        if (b.x < row.x + row.w) { setPaths(null); return; }
        const from = { x: a.x + a.w + 6, y: a.y + a.h / 2 };
        // The first line of the note, not the middle of a note that wraps.
        const to = { x: b.x - 8, y: b.y + 13 };
        const bend = (to.x - from.x) / 2;
        out.push({ n: note.dataset.note!, from, to, d: `M${from.x},${from.y} C${from.x + bend},${from.y} ${to.x - bend},${to.y} ${to.x},${to.y}` });
      }
      setPaths(out.length ? out : null);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [on, layout]);
  return [box, on ? paths : null] as const;
}

function Badge({ n }: { n: number }) {
  return (
    <span className="mt-[3px] flex size-[21px] shrink-0 items-center justify-center rounded-full bg-accent font-mono text-[11px] font-semibold text-on-accent">
      {n}
    </span>
  );
}

function ScreenThing({ type, label, n }: { type: string; label: string; n?: number }) {
  const badge = n ? (
    <span className="absolute -right-1.5 -top-1.5">
      <Badge n={n} />
    </span>
  ) : null;
  const base = "relative text-[12.5px]";
  switch (type) {
    case "heading":
      return <p className={cn(base, "text-[15px] font-semibold text-ink")}><span data-anchor>{label}</span>{badge}</p>;
    case "text":
      return <p className={cn(base, "text-muted-slate")}><span data-anchor>{label}</span>{badge}</p>;
    case "field":
      return (
        <div className={cn(base, " border border-border-strong px-2.5 py-2 text-faint")}>
          {label}
          {badge}
        </div>
      );
    case "choice":
      return (
        <div className={cn(base, " border border-accent-line bg-accent-surface px-3 py-1.5 text-accent")}>
          {label}
          {badge}
        </div>
      );
    case "button":
      return (
        <div className={cn(base, " bg-accent px-3 py-2 text-center font-medium text-on-accent")}>
          {label}
          {badge}
        </div>
      );
    case "image":
      return (
        <div className={cn(base, "flex h-20 items-center justify-center bg-surface-container text-faint")}>
          {label}
          {badge}
        </div>
      );
    default:
      return (
        <div className={cn(base, "flex flex-col gap-1 border border-border-gray p-2 text-on-surface-variant")}>
          {label}
          <span className="h-2 w-4/5 bg-surface-container" />
          <span className="h-2 w-3/5 bg-surface-container" />
          {badge}
        </div>
      );
  }
}

/* ── example ─────────────────────────────────────────────────── */

/** `bare` drops the label and caption, for a row that already shows them. */
export function Example({ block, bare }: { block: Extract<Anatomy, { kind: "example" }>; bare?: boolean }) {
  return (
    <div className="min-w-0">
      <div className={cn("mb-2.5 flex items-center gap-2", bare && "hidden")}>
        <span className=" border border-border-strong px-2 py-[2px] font-mono text-[10px] uppercase tracking-[0.07em] text-faint">
          example
        </span>
        <span className="text-[13px] font-medium text-on-surface-variant">{block.caption}</span>
      </div>
      <pre className="overflow-x-auto border border-border-gray bg-surface px-4 py-3 font-mono text-[12.5px] leading-relaxed text-on-surface">
        {block.value}
      </pre>
      {block.notes?.length ? (
        <dl className="mt-2.5 flex flex-col gap-1.5">
          {block.notes.map((p) => (
            <div key={p.label} data-pick={p.label} className="flex gap-3 text-[13px] leading-snug">
              <dt className="w-[160px] shrink-0 font-mono text-[12px] text-ink">{p.label}</dt>
              <dd className="text-on-surface-variant">
                <Prose text={p.value} />
              </dd>
            </div>
          ))}
        </dl>
      ) : null}
    </div>
  );
}

/* ── note ────────────────────────────────────────────────────── */

/**
 * The reader's own words on the level. Set at the same reading size as the
 * blocks around it so it belongs, but given a left edge and a tinted ground
 * rather than a white card: a block that looks like the generator's own work
 * would quietly claim the code's authority for a sentence a person wrote.
 */
function Note({ block }: { block: Extract<Anatomy, { kind: "note" }> }) {
  const stale = useMayBeStale(block.origin);
  return (
    <div className="min-w-0 border-l-2 border-border-strong bg-surface-container-low/60 py-2 pl-4">
      <Caption>{block.title}</Caption>
      <p className="text-[13.5px] leading-relaxed text-on-surface">
        <Prose text={block.body} />
      </p>
      <OriginMark origin={block.origin} stale={stale} className="mt-2.5 block" />
    </div>
  );
}

/* ── watch out ───────────────────────────────────────────────── */

export function WatchOut({ issues, action, onCode }: { issues: Issue[]; action?: React.ReactNode; onCode?: (at: string, heading: string, detail?: string) => void }) {
  return (
    <section data-pick="Watch out">
      <div className="flex items-center justify-between gap-3">
        <Eyebrow className="text-clay-ink">Watch out</Eyebrow>
        {action}
      </div>
      <ul className="mt-3 flex flex-col gap-2.5">
        {issues.map((it) => (
          <li
            key={it.title}
            data-pick={it.title}
            className=" border border-clay-line bg-clay-surface/60 px-4 py-3"
          >
            <p className="text-[14px] font-semibold text-clay-ink">{it.title}</p>
            <p className="mt-1 text-[13.5px] leading-relaxed text-on-surface">
              <Prose text={it.detail} />
            </p>
            {it.where && onCode ? (
              <button onClick={() => onCode(it.where!, it.title, it.detail)} className="mt-1.5 font-mono text-[11px] text-muted-slate underline-offset-2 hover:text-accent hover:underline">
                {it.where}
              </button>
            ) : it.where ? (
              <p className="mt-1.5 font-mono text-[11px] text-muted-slate">{it.where}</p>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}

/* ── the code, last ──────────────────────────────────────────── */

/* ── docs ────────────────────────────────────────────────────── */

/**
 * What the repository's own docs say about this level (`Node.docs`): the
 * design notes and decisions behind the code, each a passage that opens in
 * place. Read as the doc is now, like the code; shown as text, not code,
 * since it is written to be read.
 */
export function DocsList({ refs }: { refs: CodeRef[] }) {
  return (
    <section data-pick="From the docs" data-pick-text={refs.map((r) => `${r.file}:${r.start}-${r.end} — ${r.label}`).join("\n")}>
      <Eyebrow>From the docs</Eyebrow>
      <ul className="mt-3 flex flex-col gap-2">
        {refs.map((r) => (
          <DocPassage key={`${r.file}:${r.start}`} doc={r} />
        ))}
      </ul>
    </section>
  );
}

function DocPassage({ doc }: { doc: CodeRef }) {
  const [slice, setSlice] = useState<RepoSlice | null | "failed">(null);
  const [shown, setShown] = useState(false);
  const { name: blueprint } = useBlueprint();

  const toggle = async () => {
    setShown((v) => !v);
    if (slice) return;
    try {
      const r = await readSource({ blueprint, file: doc.file, start: doc.start, end: doc.end });
      setSlice("slice" in r ? r.slice : "failed");
    } catch {
      setSlice("failed");
    }
  };

  return (
    <li data-pick={doc.label} data-pick-code={`${doc.file}:${doc.start}-${doc.end}`} className=" border border-border-gray bg-card">
      <button onClick={toggle} aria-expanded={shown} className="flex w-full items-baseline gap-3 px-4 py-2.5 text-left">
        <span className="text-[13.5px] text-ink">{doc.label}</span>
        <span className="ml-auto shrink-0 font-mono text-[11px] text-faint">
          {doc.file}:{doc.start}–{doc.end}
        </span>
        <span aria-hidden className="text-[11px] text-faint">{shown ? "▾" : "▸"}</span>
      </button>
      {shown ? (
        <div className="border-t border-border-gray px-4 py-3">
          {slice === "failed" ? (
            <p className="text-[12.5px] text-clay-ink">Could not read this doc from the repository.</p>
          ) : slice ? (
            <>
              <p className="whitespace-pre-wrap text-[13.5px] leading-relaxed text-on-surface-variant">
                <Prose text={slice.code.trim()} />
              </p>
              <button
                type="button"
                onClick={() => openDoc(doc.file, { line: doc.start })}
                className="mt-2 cursor-pointer text-[12.5px] text-accent hover:underline"
              >
                Open the whole doc
              </button>
            </>
          ) : (
            <p className="text-[12.5px] text-faint">Reading…</p>
          )}
        </div>
      ) : null}
    </li>
  );
}

