"use client";

import { useRouter } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { openFeedback } from "@/components/chrome/feedback";
import { goTo, useLocation } from "@/components/chrome/crumbs";
import { openFileInTab } from "@/components/blueprint/code";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { Kbd, dictateKeys, keys } from "@/components/ui/button";
import { StateChip } from "@/components/ui/state";
import { newProject, openFolder, openProjects } from "@/components/projects/projects";
import { openAudit } from "@/components/blueprint/audit";
import { openHistory } from "@/components/review/additions";
import { openDiff } from "@/components/review/diff";
import { openTimeline } from "@/components/review/timeline";
import { openFiles, useCitations, useFiles, useTrail } from "@/components/blueprint/files";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import { DocIcon, openDoc, useDocList } from "@/components/blueprint/docs";
import { openSettings, readSettings, saveSettings } from "@/lib/client/settings";
import type { Theme } from "@/lib/client/theme";
import { startDictation } from "@/lib/agent/dictate";
import type { Node } from "@/lib/blueprint/schema";
import { cn } from "@/lib/client/utils";
import { useDesktop, useMac } from "@/lib/client/platform";

/**
 * The palette: one box that goes anywhere. Type part of a level's name and
 * Enter opens it however deep it is, and a doc of the project's opens the
 * same way; start with `>` for the app's actions; Cmd+K finds a file or
 * symbol instead and opens it in the editor;
 * the blueprint name in the title bar opens it on the blueprints, and the status bar's
 * counts open it on the levels that are not certain or the problems found.
 *
 * It is what a sidebar tree would have been for — reaching a level without
 * walking down to it — without spending a column on it (D35, D62).
 */

const OPEN = "blueprint:palette";
export type PaletteMode = "all" | "code" | "actions" | "blueprints" | "unsure" | "problems" | "docs";
export const openPalette = (mode: PaletteMode = "all") =>
  window.dispatchEvent(new CustomEvent<PaletteMode>(OPEN, { detail: mode }));

interface Item {
  key: string;
  label: string;
  /** Where it is or what it does, after the label. */
  hint?: string;
  /** A second line: why a level is not certain, or what goes wrong. */
  detail?: string;
  kind: "level" | "action" | "blueprint" | "unsure" | "problem" | "doc" | "file" | "folder" | "symbol";
  node?: Node;
  /** Words it is about, matched last and weakest: a level's sub, detail and plain-words layer. */
  body?: string;
  kbd?: string;
  run: () => void;
}

/**
 * How well `q` matches `text`: every character of the query in order, scored
 * higher for a run of adjacent characters and for starting a word. Null when
 * it does not match at all.
 */
function score(q: string, text: string): number | null {
  if (!q) return 0;
  const t = text.toLowerCase();
  const at = t.indexOf(q);
  if (at !== -1) return 100 - at + (at === 0 || t[at - 1] === " " ? 50 : 0);
  let s = 0;
  let i = 0;
  let prev = -2;
  for (const ch of q) {
    const j = t.indexOf(ch, i);
    if (j === -1) return null;
    s += j === prev + 1 ? 3 : j === 0 || t[j - 1] === " " ? 2 : 0;
    prev = j;
    i = j + 1;
  }
  return s;
}

export function Palette() {
  const blueprint = useBlueprint();
  const router = useRouter();
  const { path } = useLocation();
  const [mode, setMode] = useState<PaletteMode | null>(null);
  const [query, setQuery] = useState("");
  const [sel, setSel] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const list = useRef<HTMLUListElement>(null);
  const mac = useMac();
  const desktop = useDesktop();

  useEffect(() => {
    const show = (m: PaletteMode) => {
      setMode(m);
      setQuery(m === "actions" ? ">" : "");
      setSel(0);
    };
    const onOpen = (e: Event) => show((e as CustomEvent<PaletteMode>).detail);
    const onKey = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
      // On a Mac the palette is Cmd+K; Ctrl+K in a terminal is the program's kill-line.
      if (e.code === "KeyK" && !e.metaKey && /Mac/.test(navigator.platform) && (e.target as Element | null)?.closest?.(".xterm")) return;
      if (e.code === "KeyK") {
        e.preventDefault();
        show("code");
      } else if (e.code === "KeyP" && !e.shiftKey) {
        e.preventDefault();
        show("all");
      } else if (e.code === "KeyP" && e.shiftKey) {
        e.preventDefault();
        show("actions");
      }
    };
    window.addEventListener(OPEN, onOpen);
    // Capture, so a focused terminal does not swallow the shortcut.
    window.addEventListener("keydown", onKey, true);
    return () => {
      window.removeEventListener(OPEN, onOpen);
      window.removeEventListener("keydown", onKey, true);
    };
  }, []);

  useEffect(() => {
    if (mode) input.current?.focus();
  }, [mode]);

  const levels = useMemo<Item[]>(() => {
    const out: Item[] = [];
    const walk = (nodes: Node[], at: string[], trail: string[]) => {
      for (const n of nodes) {
        const p = [...at, n.id];
        out.push({
          key: `level:${p.join("/")}`,
          label: n.title,
          hint: trail.join(" › ") || blueprint.RUN.repo,
          kind: "level",
          node: n,
          body: [n.sub, n.detail, n.explain?.body].filter(Boolean).join(" ").toLowerCase(),
          run: () => goTo(p),
        });
        walk(n.children ?? [], p, [...trail, n.title]);
      }
    };
    out.push({ key: "level:", label: blueprint.RUN.repo, hint: "The top of the blueprint", kind: "level", kbd: "0", run: () => goTo([]) });
    walk(blueprint.L0, [], []);
    return out;
  }, [blueprint]);

  // The checkout's own names — paths and top-level symbols — each opening in
  // the editor over the deepest level that explains it, so closing the file
  // lands where it sits on a blueprint cut by features.
  const files = useFiles();
  const cited = useCitations();
  const trailOf = useTrail();
  const code = useMemo(() => {
    const out: Item[] = [];
    const deepest = (file: string, s = 1, e = Infinity) =>
      (cited.get(file) ?? []).filter((c) => c.start <= e && c.end >= s).sort((a, b) => b.path.length - a.path.length)[0]?.path;
    for (const [file, f] of Object.entries(files?.index?.files ?? {})) {
      const at = deepest(file);
      out.push({
        key: `file:${file}`,
        label: file,
        hint: at ? trailOf(at) : f.status === "excluded" ? "left out of the blueprint · opens the file" : "not on any level · opens the file",
        kind: "file",
        run: () => openFileInTab(blueprint.name, at ?? path, file),
      });
      for (const sym of f.symbols) {
        const by = deepest(file, sym.start, sym.end);
        out.push({
          key: `sym:${file}:${sym.name}:${sym.start}`,
          label: sym.name,
          hint: `${file} → ${by ? trailOf(by) : at ? `not explained; nearest ${trailOf(at)}` : "not explained"}`,
          kind: "symbol",
          run: () => openFileInTab(blueprint.name, by ?? at ?? path, file, sym.start),
        });
      }
    }
    // Files the blueprint has not seen: new since it was made, or ignored by git
    // and kept by hand, like the .env an API key goes in.
    for (const file of files?.added ?? [])
      out.push({ key: `file:${file}`, label: file, hint: "new since the blueprint was made · opens the file", kind: "file", run: () => openFileInTab(blueprint.name, path, file) });
    for (const file of files?.local ?? [])
      out.push({ key: `file:${file}`, label: file, hint: "not in git · opens the file", kind: "file", run: () => openFileInTab(blueprint.name, path, file) });
    // The rest of the checkout: everything, while a blueprint is still being made
    // and has no index; after, files the blueprint would not explain, like a README.
    const seen = new Set(out.map((it) => it.key));
    for (const file of files?.present ?? []) {
      if (seen.has(`file:${file}`)) continue;
      out.push({
        key: `file:${file}`,
        label: file,
        hint: files?.index ? "not on the blueprint · opens the file" : "the blueprint is still being made · opens the file",
        kind: "file",
        run: () => openFileInTab(blueprint.name, path, file),
      });
    }
    // Folders, each opening as a listing of what is directly inside it, so the
    // palette browses like a file explorer as well as searching.
    const browse = (dir: string) => () => {
      setMode("code");
      setQuery(dir && `${dir}/`);
      setSel(0);
    };
    const inside = new Map<string, number>();
    const tree = new Map<string, Item[]>([["", []]]);
    const childOf = (dir: string) => tree.get(dir) ?? tree.set(dir, []).get(dir)!;
    for (const it of out) {
      if (it.kind !== "file") continue;
      const parts = it.label.split("/");
      for (let i = 1; i < parts.length; i++) {
        const dir = parts.slice(0, i).join("/");
        inside.set(dir, (inside.get(dir) ?? 0) + 1);
      }
      childOf(parts.slice(0, -1).join("/")).push({ ...it, label: parts[parts.length - 1] });
    }
    for (const [dir, n] of inside) {
      const folder: Item = { key: `dir:${dir}`, label: `${dir}/`, hint: `${n} file${n === 1 ? "" : "s"}`, kind: "folder", run: browse(dir) };
      out.push(folder);
      const parent = dir.split("/").slice(0, -1).join("/");
      childOf(parent).push({ ...folder, label: `${dir.split("/").pop()}/` });
    }
    // Folders first, then files, each by name; and a way up out of any folder.
    for (const [dir, items] of tree) {
      items.sort((a, b) => (a.kind === b.kind ? a.label.localeCompare(b.label) : a.kind === "folder" ? -1 : 1));
      if (dir) items.unshift({ key: "dir:..", label: "../", hint: dir.split("/").slice(0, -1).join("/") || "the top", kind: "folder", run: browse(dir.split("/").slice(0, -1).join("/")) });
    }
    return { all: out, tree };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- trailOf reads the same blueprint as cited
  }, [files, cited, path, blueprint.name]);

  const docList = useDocList();
  const docs = useMemo<Item[]>(
    () =>
      (docList ?? []).map((d) => ({
        key: `doc:${d.path}`,
        // The file is what people call a doc; its heading says what is in it.
        label: d.path,
        hint: d.title || undefined,
        kind: "doc" as const,
        run: () => openDoc(d.path),
      })),
    [docList],
  );

  const actions = useMemo<Item[]>(() => {
    const theme = (t: Theme) => () => saveSettings({ ...readSettings(), theme: t });
    return [
      { key: "a:back", label: "Go back a level", kind: "action", kbd: "Esc", run: () => path.length && goTo(path.slice(0, -1)) },
      { key: "a:workspace", label: "Toggle Claude Code & terminal", kind: "action", kbd: keys(mac, "`"), run: toggleWorkspace },
      { key: "a:diff", label: "What changed in the code", hint: "Diff two commits over the blueprint", kind: "action", run: openDiff },
      { key: "a:files", label: "Every file", hint: "Where each part of the code is explained", kind: "action", run: () => openFiles() },
      { key: "a:timeline", label: "How the code got here", hint: "Its commits over time, on the blueprint's sections", kind: "action", run: openTimeline },
      { key: "a:audit", label: "How sure is this blueprint", hint: "What was checked, and what to double-check", kind: "action", run: () => openAudit(blueprint.name) },
      { key: "a:history", label: "What you added to this blueprint", kind: "action", run: openHistory },
      { key: "a:docs", label: "Read the docs…", hint: "The project's Markdown: design notes, decisions", kind: "action", run: () => setTimeout(() => openPalette("docs")) },
      { key: "a:open", label: "Open Folder…", hint: "Make a blueprint of a folder on this machine", kind: "action", run: () => void openFolder() },
      { key: "a:new", label: "New Project…", hint: "Start an empty folder", kind: "action", run: newProject },
      { key: "a:projects", label: "Projects", hint: "Your blueprints: open, regenerate, remove", kind: "action", run: () => openProjects() },
      { key: "a:blueprints", label: "Switch blueprint…", kind: "action", run: () => setTimeout(() => openPalette("blueprints")) },
      { key: "a:settings", label: "Settings", kind: "action", run: openSettings },
      { key: "a:feedback", label: "Report a bug or send feedback", hint: "Goes to the people who make Blueprint", kind: "action", run: openFeedback },
      // After the palette has closed, so the words go to Claude's prompt rather than the palette's field.
      ...(desktop
        ? [{ key: "a:dictate", label: "Dictate on this machine", hint: "Speak, then done; or hold the keys", kind: "action" as const, kbd: `Hold ${dictateKeys(mac)}`, run: () => setTimeout(startDictation) }]
        : []),
      { key: "a:light", label: "Theme: light", kind: "action", run: theme("light") },
      { key: "a:dark", label: "Theme: dark", kind: "action", run: theme("dark") },
    ];
  }, [blueprint.name, path, mac, desktop]);

  const blueprints = useMemo<Item[]>(
    () =>
      blueprint.blueprints.map((m) => ({
        key: `blueprint:${m.id}`,
        label: m.label,
        hint: m.id === blueprint.name ? "open now" : undefined,
        kind: "blueprint" as const,
        run: () => router.push(`?blueprint=${encodeURIComponent(m.id)}`),
      })),
    [blueprint.blueprints, blueprint.name, router],
  );

  // What the status bar counts, each a way to the level it is on. Walked in
  // blueprint order, so the list reads top to bottom the way the blueprint does.
  const findings = useMemo(() => {
    const unsure: Item[] = [];
    const problems: Item[] = [];
    const walk = (n: Node, p: string[], trail: string[]) => {
      const where = trail.join(" › ") || blueprint.RUN.repo;
      const run = () => goTo(p);
      if (n.state !== "derived") {
        unsure.push({ key: `u:${p.join("/")}`, label: n.title, hint: where, detail: n.unsure, kind: "unsure", node: n, run });
      }
      n.issues?.forEach((is, i) =>
        problems.push({
          key: `p:${p.join("/")}:${i}`,
          label: is.title,
          hint: `in ${n.title}`,
          detail: is.detail,
          kind: "problem",
          run,
        }),
      );
      for (const c of n.children ?? []) walk(c, [...p, c.id], p.length ? [...trail, n.title] : []);
    };
    // The repository itself is a level too (D60), and can carry both.
    walk(blueprint.TOP, [], []);
    return { unsure, problems };
  }, [blueprint]);

  const shown = useMemo(() => {
    const actionsOnly = query.startsWith(">");
    const q = (actionsOnly ? query.slice(1) : query).trim().toLowerCase();
    // Nothing typed, or a folder's path: list that folder, as an explorer would.
    if (mode === "code" && (!query.trim() || query.endsWith("/"))) {
      const listing = code.tree.get(query.trim().replace(/\/$/, ""));
      if (listing) return listing;
    }
    const pool =
      mode === "blueprints" ? blueprints
      : mode === "unsure" ? findings.unsure
      : mode === "problems" ? findings.problems
      : mode === "docs" ? docs
      : mode === "code" ? code.all
      : actionsOnly ? actions
      : q ? [...levels, ...docs, ...actions]
      : levels;
    return pool
      // A hint or a body counts only as a plain substring: scattered letters
      // across a sentence match nearly anything.
      .map((it) => ({ it, s: score(q, it.label) ?? (it.hint?.toLowerCase().includes(q) ? 1 : it.body?.includes(q) ? 0.5 : null) }))
      .filter((x): x is { it: Item; s: number } => x.s !== null)
      .sort((a, b) => b.s - a.s)
      .slice(0, 60)
      .map((x) => x.it);
  }, [mode, query, levels, code, docs, actions, blueprints, findings]);

  useEffect(() => {
    list.current?.querySelector(`[data-i="${sel}"]`)?.scrollIntoView({ block: "nearest" });
  }, [sel]);

  if (!mode) return null;
  const close = () => setMode(null);
  const run = (it: Item | undefined) => {
    if (!it) return;
    close();
    it.run();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex justify-center bg-night/20 px-4 pt-[12vh]"
      onPointerDown={(e) => e.target === e.currentTarget && close()}
    >
      <div
        role="dialog"
        aria-label="Go to"
        className="flex h-fit max-h-[60vh] w-full max-w-[600px] flex-col overflow-hidden border border-border-strong bg-card shadow-lift"
      >
        <input
          ref={input}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setSel(0);
          }}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              e.preventDefault();
              e.stopPropagation();
              close();
            } else if (e.key === "ArrowDown") {
              e.preventDefault();
              setSel((s) => Math.min(s + 1, shown.length - 1));
            } else if (e.key === "ArrowUp") {
              e.preventDefault();
              setSel((s) => Math.max(s - 1, 0));
            } else if (e.key === "Enter") {
              e.preventDefault();
              run(shown[sel]);
            }
          }}
          placeholder={
            mode === "blueprints" ? "Switch to a blueprint…"
            : mode === "unsure" ? `${findings.unsure.length} ${findings.unsure.length === 1 ? "level" : "levels"} the blueprint is not certain about — filter…`
            : mode === "problems" ? `${findings.problems.length} ${findings.problems.length === 1 ? "problem" : "problems"} found in the code — filter…`
            : mode === "docs" ? (docList === null ? "Finding the docs…" : `${docList.length} docs in this project — filter…`)
            : mode === "code" ? "Open a file, folder or symbol in the editor…"
            : "Go to a level, or type > for actions"
          }
          className="h-11 w-full shrink-0 border-b border-border-gray bg-transparent px-4 text-[14px] text-ink placeholder:text-faint focus:outline-none"
        />
        <ul ref={list} role="listbox" className="min-h-0 overflow-y-auto py-1">
          {shown.length ? (
            shown.map((it, i) => (
              <li key={it.key} data-i={i} role="option" aria-selected={i === sel}>
                <button
                  type="button"
                  onPointerMove={() => setSel(i)}
                  onClick={() => run(it)}
                  className={cn(
                    "flex w-full cursor-pointer gap-2.5 px-4 text-left",
                    it.detail ? "items-start py-2" : "items-center py-[7px]",
                    // Not surface-container-low: in Dark that is the card's own colour, a step too close to show.
                    i === sel && "bg-surface-container",
                  )}
                >
                  <KindIcon kind={it.kind} />
                  <span className="min-w-0 flex-1">
                    <span className="flex items-center gap-2.5">
                      <span className={cn("truncate text-[13px] text-ink", it.kind === "symbol" && "shrink-0")}>{it.label}</span>
                      {it.node && it.kind === "level" ? <StateChip state={it.node.state} alarm={it.node.alarm} /> : null}
                      {it.hint ? <span className="min-w-0 truncate text-[12px] text-faint">{it.hint}</span> : null}
                      <span className="flex-1" />
                      {it.kbd ? <Kbd>{it.kbd}</Kbd> : null}
                    </span>
                    {it.detail ? (
                      <span className="mt-0.5 line-clamp-2 text-[12px] leading-snug text-muted-slate">{it.detail}</span>
                    ) : null}
                  </span>
                </button>
              </li>
            ))
          ) : (
            <li className="px-4 py-3 text-[13px] text-faint">
              {mode === "unsure" && !findings.unsure.length
                ? "Every level is certain."
                : mode === "problems" && !findings.problems.length
                  ? "The blueprint found no problems."
                  : mode === "docs" && docList && !docList.length
                    ? "This project has no Markdown."
                    : "Nothing matches."}
            </li>
          )}
        </ul>
        <footer className="flex shrink-0 items-center gap-3 border-t border-border-gray bg-surface px-4 py-1.5 text-[11.5px] text-faint">
          <span className="flex items-center gap-1"><Kbd>↑</Kbd><Kbd>↓</Kbd> move</span>
          <span className="flex items-center gap-1"><Kbd>Enter</Kbd> open</span>
          {mode === "all" || mode === "actions" ? <span className="flex items-center gap-1"><Kbd>&gt;</Kbd> actions</span> : null}
          <span className="flex-1" />
          <span className="flex items-center gap-1"><Kbd>Esc</Kbd> close</span>
        </footer>
      </div>
    </div>
  );
}

function KindIcon({ kind }: { kind: Item["kind"] }) {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn(
        "shrink-0",
        kind === "unsure" ? "mt-[3px] text-amber-ink" : kind === "problem" ? "mt-[3px] text-clay-ink" : "text-faint",
      )}
      aria-hidden
    >
      {kind === "unsure" ? (
        <>
          <circle cx="8" cy="8" r="6" />
          <path d="M6.3 6.2a1.8 1.8 0 1 1 2.4 1.7c-.5.2-.7.5-.7 1v.4M8 11.4v.1" />
        </>
      ) : kind === "problem" ? (
        <path d="M8 2 14.5 13.5h-13zM8 6.5v3M8 11.6v.1" />
      ) : kind === "level" ? (
        <>
          <rect x="2" y="2.5" width="12" height="11" rx="2" />
          <path d="M5 6h6M5 9h4" />
        </>
      ) : kind === "doc" ? (
        <DocIcon />
      ) : kind === "file" ? (
        <path d="M4 1.5h5l3 3v10H4zM9 1.5v3h3" />
      ) : kind === "symbol" ? (
        <path d="M6 3.5c-1.5 0-2 .7-2 2v1c0 .8-.5 1.5-1.5 1.5 1 0 1.5.7 1.5 1.5v1c0 1.3.5 2 2 2M10 3.5c1.5 0 2 .7 2 2v1c0 .8.5 1.5 1.5 1.5-1 0-1.5.7-1.5 1.5v1c0 1.3-.5 2-2 2" />
      ) : kind === "blueprint" || kind === "folder" ? (
        <path d="M1.5 4.5a1 1 0 0 1 1-1h3.6l1.5 1.5h5.9a1 1 0 0 1 1 1v6.5a1 1 0 0 1-1 1h-11a1 1 0 0 1-1-1z" />
      ) : (
        <path d="m5 4 4 4-4 4M9 12h3" />
      )}
    </svg>
  );
}

app/components/chrome/project-rail.tsx:
"use client";

import { listen } from "@tauri-apps/api/event";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef } from "react";
import { StatusDot } from "@/components/agent/status-dot";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { openProjects } from "@/components/projects/projects";
import { keys } from "@/components/ui/button";
import { arrived, closeProject, keepOnly, useOpenProjects } from "@/lib/client/open-projects";
import { useDesktop, useMac } from "@/lib/client/platform";
import { useRailExpanded, useRailWidth } from "@/lib/client/rail";
import { openSettings } from "@/lib/client/settings";
import { openFeedback } from "@/components/chrome/feedback";
import { FeedbackGlyph, GearGlyph } from "@/components/chrome/icons";
import { FoldButton } from "@/components/chrome/titlebar";
import { cn } from "@/lib/client/utils";

/** Two letters that name a project at a glance: the first of each of its first two words, else its first two letters. */
export function initials(label: string) {
  const words = label.split(/[^A-Za-z0-9]+/).filter(Boolean);
  const text = words.length > 1 ? words[0][0] + words[1][0] : (words[0] ?? label).slice(0, 2);
  return text.toLowerCase();
}

/**
 * The projects open in the window, down its left edge: a square each with
 * its initials and the dot of the loudest Claude among its workspace tabs
 * (components/agent/workspace.tsx), the open one marked with an accent bar. The rail
 * opens to show their names (the fold button above it, kept between launches);
 * + opens another, imports one, or manages them. Switching keeps every
 * terminal running, and the workspace shows the tabs of the project switched
 * to. Cmd+1–9 (Ctrl+1–9 off a Mac) picks one. Middle click closes one. Where you
 * are inside the blueprint is the blueprint tabs' to say (components/chrome/tabs.tsx).
 */
export function ProjectRail() {
  const desktop = useDesktop();
  const mac = useMac();
  const width = useRailWidth();
  const wide = useRailExpanded();
  const { name, blueprints } = useBlueprint();
  const router = useRouter();
  const { open, last, status } = useOpenProjects();
  const shown = open.flatMap((id) => blueprints.filter((m) => m.id === id));
  const go = useCallback((id: string | null | undefined) => id && id !== name && router.push(`/?blueprint=${encodeURIComponent(id)}`), [name, router]);

  const was = useRef<string | null>(null);
  useEffect(() => {
    arrived(name, was.current);
    was.current = name;
  }, [name]);
  useEffect(() => keepOnly(blueprints.map((m) => m.id)), [blueprints]);

  // Off a Mac here; on one the menu bar takes the keys (src-tauri/src/lib.rs),
  // so they work from inside a Preview's page too.
  const ids = shown.map((m) => m.id).join("\n");
  useEffect(() => {
    const pick = (n: string) => go(n === "last" ? last : ids.split("\n")[Number(n) - 1]);
    const onKey = (e: KeyboardEvent) => {
      if (!e.ctrlKey || e.metaKey || e.altKey) return;
      // Ctrl+Tab is the tabs' own (components/agent/workspace.tsx, components/chrome/tabs.tsx).
      const n = !e.shiftKey && /^Digit[1-9]$/.test(e.code) ? e.code.slice(5) : null;
      if (!n) return;
      e.preventDefault();
      e.stopPropagation();
      pick(n);
    };
    if (!mac) window.addEventListener("keydown", onKey, true);
    const fromMenu = mac ? listen<string>("blueprint:project", (e) => pick(e.payload)) : undefined;
    return () => {
      window.removeEventListener("keydown", onKey, true);
      void fromMenu?.then((f) => f());
    };
  }, [mac, go, last, ids]);

  const close = (id: string) => {
    if (id === name) {
      const at = shown.findIndex((m) => m.id === id);
      go((shown[at + 1] ?? shown[at - 1])?.id);
    }
    const root = shown.find((m) => m.id === id)?.root;
    closeProject(id, root && !shown.some((m) => m.id !== id && m.root === root) ? root : undefined);
  };

  if (!desktop) return null;
  return (
    <aside
      aria-label="Projects"
      data-chrome="bar"
      style={{ width }}
      className="flex shrink-0 select-none flex-col gap-2 overflow-y-auto border-r border-border-gray bg-surface-container-low px-2 py-2"
    >
      {mac ? <FoldButton wide={wide} /> : null}
      <div role="tablist" aria-label="Open projects" aria-orientation="vertical" className="flex flex-col gap-2">
        {shown.map((m, i) => {
          const here = m.id === name;
          const dot = m.root ? status[m.root] : undefined;
          return (
            <div
              key={m.id}
              role="tab"
              aria-selected={here}
              title={`${m.label}${i < 9 ? ` (${keys(mac, String(i + 1))})` : ""}`}
              onAuxClick={(e) => {
                if (e.button === 1 && shown.length > 1) {
                  e.preventDefault();
                  close(m.id);
                }
              }}
              className={cn(
                "group relative flex h-11 min-w-0 items-center border transition-colors",
                here
                  ? "border-border-gray bg-surface-container text-ink shadow-[inset_3px_0_0_var(--color-accent)]"
                  : "border-border-gray text-muted-slate hover:bg-surface-container hover:text-ink",
              )}
            >
              <button
                type="button"
                onClick={() => go(m.id)}
                className={cn(
                  "flex h-full min-w-0 flex-1 cursor-pointer items-center gap-2.5 font-mono text-[12px] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
                  wide ? "px-3" : "justify-center",
                  here && "font-semibold",
                )}
              >
                <span className="shrink-0">{initials(m.label)}</span>
                {wide ? <span className="truncate">{m.label}</span> : null}
              </button>
              {dot ? (
                <span className={cn("flex", wide ? "mr-2 shrink-0" : "absolute bottom-1 right-1")}>
                  <StatusDot status={dot} />
                </span>
              ) : null}
              {wide && shown.length > 1 ? (
                <button
                  type="button"
                  onClick={() => close(m.id)}
                  aria-label={`Close ${m.label}`}
                  className="mr-2 flex size-4 shrink-0 cursor-pointer items-center justify-center text-faint opacity-0 hover:bg-border-gray hover:text-ink focus-visible:opacity-100 group-hover:opacity-100"
                >
                  <svg aria-hidden width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round">
                    <path d="m1.5 1.5 5 5m0-5-5 5" />
                  </svg>
                </button>
              ) : null}
            </div>
          );
        })}
        <button
          type="button"
          onClick={() => openProjects()}
          aria-label="Open another project"
          title="Open another project"
          className={cn(
            "flex h-11 cursor-pointer items-center gap-2.5 border border-border-gray font-mono text-[12px] text-faint transition-colors hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:outline-accent",
            wide ? "px-3" : "justify-center",
          )}
        >
          <svg aria-hidden width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
            <path d="M5 1.5v7M1.5 5h7" />
          </svg>
          {wide ? <span>Open project</span> : null}
        </button>
      </div>
      <div className="mt-auto flex flex-col gap-1 border-t border-border-gray pt-2">
        <RailTool label="Report a bug or send feedback" short="Feedback" wide={wide} onClick={openFeedback}>
          <FeedbackGlyph />
        </RailTool>
        <RailTool label="Settings" short="Settings" wide={wide} onClick={openSettings}>
          <GearGlyph />
        </RailTool>
      </div>
    </aside>
  );
}

/** A tool at the foot of the rail: its icon, and its name when the rail is open. */
function RailTool({ label, short, wide, onClick, children }: { label: string; short: string; wide: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      title={label}
      className={cn(
        "flex h-10 cursor-pointer items-center gap-2.5 text-[12px] text-muted-slate transition-colors hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
        wide ? "px-3" : "justify-center",
      )}
    >
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.25" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        {children}
      </svg>
      {wide ? <span>{short}</span> : null}
    </button>
  );
}

app/components/chrome/settings.tsx:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { Fragment, useCallback, useEffect, useState } from "react";
import { DIALOG, Field, INPUT, Overlay, Segmented } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { AgentIcon, CLAUDE, useInstalled } from "@/components/agent/agents";
import { PanelClose, PanelHead } from "@/components/ui/panel";
import { followTheme, onOpenSettings, readSettings, saveSettings, useSettings, type Ground, type Settings, type Theme } from "@/lib/client/settings";
import { useDesktop } from "@/lib/client/platform";
import { onCreditChanged, percent, pollSignIn, readCredit, resetsAt, setCredit, setFallback, signOut, startSignIn, type Credit } from "@/lib/client/credit";

/**
 * Settings, as a dialog over the blueprint, in groups: how it looks, Claude Code,
 * dictation, the Preview, and what is sent to Blueprint. Every change is saved as
 * it is made, so there is nothing to confirm and nothing to undo. Outside the
 * desktop app (a page framed in a Preview) only the look applies, so only it shows.
 */

const THEMES: { value: Theme; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
];

const GROUNDS: { value: Ground; label: string }[] = [
  { value: "plain", label: "Plain" },
  { value: "dots", label: "Dots" },
  { value: "squares", label: "Squares" },
];

type Found = { path: string; version: string | null } | null;

/** Opens a page in the reader's own browser, not a Preview tab. */
export const external = (url: string) => void invoke("preview_external", { url }).catch(() => window.open(url, "_blank"));

/**
 * GitHub's device sign-in, as two steps: the code, then the page it goes on.
 * Shown bare, the code read as something GitHub had sent rather than something
 * to type in. It is copied as it shows, where the webview allows it.
 */
export function GitHubCode({ code, url, onCancel }: { code: string; url: string; onCancel: () => void }) {
  const [copied, setCopied] = useState(false);
  const copy = useCallback(() => void navigator.clipboard.writeText(code).then(() => setCopied(true), () => {}), [code]);
  useEffect(copy, [copy]);
  return (
    <div className="flex flex-col gap-3 text-[12.5px]">
      <div>
        <p className="text-ink">1. Copy this code</p>
        <div className="mt-1.5 flex items-center gap-2">
          <span className="select-all border border-border-strong bg-card px-3 py-1.5 font-mono text-[20px] tracking-[0.2em] text-ink">{code}</span>
          <Button onClick={copy}>{copied ? "Copied" : "Copy"}</Button>
        </div>
      </div>
      <div>
        <p className="text-ink">2. Paste it on GitHub and authorize Blueprint</p>
        <div className="mt-1.5 flex items-center gap-2">
          <Button variant="primary" onClick={() => external(url)}>
            Open GitHub
          </Button>
          <span className="font-mono text-[11.5px] text-faint">{url.replace(/^https:\/\//, "")}</span>
        </div>
      </div>
      <p className="text-muted-slate">
        Waiting for GitHub…{" "}
        <button type="button" onClick={onCancel} className="cursor-pointer text-accent hover:underline">
          Cancel
        </button>
      </p>
    </div>
  );
}

/** A group of settings under its name; only the one picked in the list shows, but all stay mounted so none redraws as it loads. */
function Group({ title, shown, children }: { title: Section; shown: Section; children: React.ReactNode }) {
  return (
    <section aria-label={title} hidden={title !== shown} className="flex flex-col gap-6">
      <h3 className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">{title}</h3>
      {children}
    </section>
  );
}

const SECTIONS = ["Appearance", "Claude Code", "Dictation", "Preview", "Privacy", "About"] as const;
type Section = (typeof SECTIONS)[number];

export function SettingsDialog() {
  const [open, setOpen] = useState(false);
  const [section, setSection] = useState<Section>("Appearance");
  // What is on screen is what is saved: there is no draft to keep in step.
  const draft = useSettings();
  // undefined while looking.
  const [found, setFound] = useState<Found | undefined>(undefined);
  const agents = [CLAUDE, ...useInstalled()];
  const desktop = useDesktop();

  const detect = useCallback((claudePath: string) => {
    setFound(undefined);
    invoke<Found>("claude_detect", { configured: claudePath.trim() || null })
      .then(setFound)
      .catch(() => setFound(null));
  }, []);

  useEffect(
    () =>
      onOpenSettings(() => {
        setOpen(true);
        setSection("Appearance");
        if (desktop) detect(readSettings().claudePath);
      }),
    [detect, desktop],
  );

  // Mounted for the app's whole life, so this keeps the page on the saved theme.
  useEffect(followTheme, []);

  if (!open) return null;
  const close = () => {
    tidy();
    setOpen(false);
  };
  // Typing keeps its spaces until the field is left, so a trim never moves the caret.
  const set = (next: Partial<Settings>) => saveSettings({ ...readSettings(), ...next });
  const tidy = () => {
    const now = readSettings();
    set({ claudePath: now.claudePath.trim(), model: now.model.trim() });
  };

  return (
    <Overlay onClose={close}>
      <form
        role="dialog"
        aria-label="Settings"
        onSubmit={(e) => {
          e.preventDefault();
          close();
        }}
        className={`${DIALOG} ${desktop ? "h-[560px] max-w-[780px]" : "max-w-[520px]"}`}
      >
        <PanelHead title="Settings" right={<PanelClose type="submit" />} />
        <div className="flex min-h-0 flex-1">
          {desktop ? (
            <nav aria-label="Settings sections" className="flex w-44 shrink-0 flex-col gap-0.5 overflow-y-auto border-r border-border-gray bg-surface-container-low p-3">
              {SECTIONS.map((name) => (
                <button
                  key={name}
                  type="button"
                  aria-current={name === section}
                  onClick={() => setSection(name)}
                  className={`cursor-pointer px-3 py-2.5 text-left text-[13px] transition-colors focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent ${
                    name === section ? "bg-surface-container font-semibold text-ink shadow-[inset_3px_0_0_var(--color-accent)]" : "text-muted-slate hover:bg-surface-container hover:text-ink"
                  }`}
                >
                  {name}
                </button>
              ))}
            </nav>
          ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-6 overflow-y-auto px-7 py-6">
          <Group title="Appearance" shown={section}>
            <Field group label="Theme">
              <Segmented label="Theme" value={draft.theme} options={THEMES} onChange={(theme) => set({ theme })} />
            </Field>
            <Field group label="Background">
              <Segmented label="Background" value={draft.ground} options={GROUNDS} onChange={(ground) => set({ ground })} />
            </Field>
          </Group>
          {desktop ? (
            <>
              <Group title="Claude Code" shown={section}>
                <BlueprintCredit />
                <Field label="Claude Code">
                  <input
                    value={draft.claudePath}
                    onChange={(e) => set({ claudePath: e.target.value })}
                    onBlur={() => {
                      tidy();
                      detect(draft.claudePath);
                    }}
                    placeholder={found?.path ?? "~/.local/bin/claude"}
                    spellCheck={false}
                    className={INPUT}
                  />
                  <div className="mt-1.5 flex items-baseline gap-3 font-mono text-[11.5px]">
                    {found === undefined ? (
                      <span className="text-faint">Looking…</span>
                    ) : found ? (
                      <span className="truncate text-accent">
                        ✓ {found.path}
                        {found.version ? ` (${found.version})` : ""}
                      </span>
                    ) : (
                      <span className="text-clay-ink">
                        {draft.claudePath.trim() ? "Nothing at that path." : "Not found — install Claude Code, or enter its path."}
                      </span>
                    )}
                    <button
                      type="button"
                      onClick={() => detect(draft.claudePath)}
                      className="ml-auto shrink-0 cursor-pointer text-accent hover:underline"
                    >
                      Detect again
                    </button>
                  </div>
                </Field>
                <Field label="Model">
                  <input
                    value={draft.model}
                    onChange={(e) => set({ model: e.target.value })}
                    onBlur={tidy}
                    placeholder="default"
                    spellCheck={false}
                    className={INPUT}
                  />
                </Field>
                <Field
                  group
                  label="Skills and web research"
                >
                  <Segmented
                    label="Skills and web research"
                    value={draft.research}
                    options={[
                      { value: true, label: "Without asking" },
                      { value: false, label: "As in Claude Code" },
                    ]}
                    onChange={(research) => set({ research })}
                  />
                </Field>
                {agents.length > 1 ? (
                  <Field
                    group
                    label="Default agent"
                  >
                    <Segmented
                      label="Default agent"
                      value={draft.agent}
                      options={agents.map((a) => ({
                        value: a.id,
                        label: (
                          <>
                            <AgentIcon id={a.id} />
                            {a.label}
                          </>
                        ),
                      }))}
                      onChange={(agent) => set({ agent })}
                    />
                  </Field>
                ) : null}
              </Group>
              <Group title="Dictation" shown={section}>
                <Field
                  group
                  label="Claude Code dictation"
                >
                  <Segmented
                    label="Claude Code dictation"
                    value={draft.voice}
                    options={[
                      { value: true, label: "On" },
                      { value: false, label: "As in Claude Code" },
                    ]}
                    onChange={(voice) => set({ voice })}
                  />
                </Field>
                <Field
                  group
                  label="On-device dictation"
                >
                  <OnDevice />
                </Field>
                <Field group label="Media while dictating">
                  <Segmented
                    label="Media while dictating"
                    // Unset until the first dictation asks; until then nothing is quieted.
                    value={draft.quietMedia ?? false}
                    options={[
                      { value: true, label: "Quiet it" },
                      { value: false, label: "Leave it" },
                    ]}
                    onChange={(quietMedia) => set({ quietMedia })}
                  />
                </Field>
              </Group>
              <Group title="Preview" shown={section}>
                <Field group label="Dev server">
                  <Segmented
                    label="Dev server"
                    value={draft.devServer}
                    options={[
                      { value: true, label: "Start it" },
                      { value: false, label: "Leave it" },
                    ]}
                    onChange={(devServer) => set({ devServer })}
                  />
                </Field>
                <Field
                  group
                  label="Saved sign-ins"
                >
                  <SignIns />
                </Field>
              </Group>
              <Group title="Privacy" shown={section}>
                <Field
                  group
                  label="Run reports"
                >
                  <RunReports />
                </Field>
              </Group>
              <Group title="About" shown={section}>
                <Field group label="Version">
                  <Version />
                </Field>
              </Group>
            </>
          ) : null}
        </div>
        </div>
      </form>
    </Overlay>
  );
}

/**
 * Blueprint credit (lib/server/credit.ts): Claude on Blueprint's own Bedrock in place of the user's
 * Claude Code, for a GitHub account signed in here. Offered while the promotion is on; once signed
 * in, its three windows show as Claude Code's /usage shows its own.
 */
function BlueprintCredit() {
  const [c, setC] = useState<Credit | null>(null);
  // GitHub's code while the reader enters it, or why signing in stopped.
  const [signin, setSignin] = useState<{ code: string; url: string; interval: number } | { reason: string } | null>(null);
  useEffect(() => {
    const read = () => void readCredit().then(setC);
    read();
    return onCreditChanged(read);
  }, []);
  useEffect(() => {
    if (!signin || !("code" in signin)) return;
    let stop = false;
    let t: ReturnType<typeof setTimeout>;
    const poll = (wait: number) => {
      t = setTimeout(async () => {
        const p = await pollSignIn().catch(() => ({ wait }));
        if (stop) return;
        if ("login" in p) setSignin(null);
        else if ("reason" in p) setSignin({ reason: p.reason });
        else poll(p.wait);
      }, wait * 1000);
    };
    poll(signin.interval);
    return () => {
      stop = true;
      clearTimeout(t);
    };
  }, [signin]);
  if (!c || (!c.login && !c.promo)) return null;

  const begin = async () => {
    const r = await startSignIn().catch(() => ({ reason: "Blueprint could not start the sign-in." }));
    setSignin(r);
    if ("code" in r) external(r.url);
  };
  const meters = c.available && c.on && c.meters ? ([["Session", c.meters.session], ["Week", c.meters.week], ["Blueprints", c.meters.maps]] as const) : [];
  return (
    <Field
      group
      label="Blueprint credit"
    >
      {c.login ? (
        <>
          {c.available && (
            <Segmented
              label="Blueprint credit"
              value={c.on}
              options={[
                { value: true, label: "Use Blueprint credit" },
                { value: false, label: "Use my Claude Code" },
              ]}
              onChange={(on) => {
                setC({ ...c, on });
                void setCredit(on);
              }}
            />
          )}
          {meters.length > 0 && (
            <div className="mt-3 max-w-[460px] border border-border-gray bg-card px-3.5 py-3">
              <p className="mb-3 font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">Usage</p>
              <div className="grid grid-cols-[auto_1fr_auto_auto] items-center gap-x-3 gap-y-2.5 font-mono text-[11.5px]">
                {meters.map(([label, m]) => {
                  const used = percent(m);
                  const at = resetsAt(m);
                  return (
                    <Fragment key={label}>
                      <span className="text-ink">{label}</span>
                      <span className="block h-1.5 min-w-16 bg-surface-container">
                        <span className="block h-full bg-accent" style={{ width: `${used ?? 0}%` }} />
                      </span>
                      <span className="text-right tabular-nums text-ink">{used == null ? "No limit" : `${used}%`}</span>
                      <span className="text-faint">{at ? `resets ${at}` : ""}</span>
                    </Fragment>
                  );
                })}
              </div>
            </div>
          )}
          {c.available && c.on && (
            <label className="mt-3 flex w-fit cursor-pointer items-center gap-2.5">
              <input
                type="checkbox"
                checked={c.fallback}
                onChange={(e) => {
                  setC({ ...c, fallback: e.target.checked });
                  void setFallback(e.target.checked);
                }}
                className="accent-accent"
              />
              <span className="text-[12.5px] text-ink">Switch to my Claude Code when it runs out</span>
            </label>
          )}
          {c.reason && <p className="mt-2 text-[12px] text-clay-ink">{c.reason}</p>}
          <div className="mt-4 flex items-baseline gap-2 border-t border-border-gray pt-3 font-mono text-[11.5px] text-faint">
            <span>
              Signed in as <span className="text-ink">@{c.login}</span>
            </span>
            <span aria-hidden>·</span>
            <button type="button" onClick={() => void signOut()} className="cursor-pointer text-accent hover:underline">
              Sign out
            </button>
            <a
              href="https://blpr.dev/promotion"
              onClick={(e) => (e.preventDefault(), external("https://blpr.dev/promotion"))}
              className="ml-auto text-accent hover:underline"
            >
              Promotion terms
            </a>
          </div>
        </>
      ) : signin && "code" in signin ? (
        <GitHubCode code={signin.code} url={signin.url} onCancel={() => setSignin(null)} />
      ) : (
        <>
          <Button onClick={() => void begin()}>Sign in with GitHub</Button>
          {signin && <p className="mt-1.5 text-[12px] text-clay-ink">{signin.reason}</p>}
        </>
      )}
    </Field>
  );
}

/** Whether finished runs are reported (lib/server/telemetry.ts); kept by the server, which sends them. */
function RunReports() {
  const [on, setOn] = useState<boolean | null>(null);
  useEffect(() => {
    fetch("/api/telemetry")
      .then((r) => r.json())
      .then((t: { on: boolean }) => setOn(t.on), () => setOn(null));
  }, []);
  const choose = (value: boolean) => {
    setOn(value);
    void fetch("/api/telemetry", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ on: value }) });
  };
  return (
    <Segmented
      label="Run reports"
      value={on}
      options={[
        { value: true, label: "Send" },
        { value: false, label: "Don't send" },
      ]}
      onChange={choose}
    />
  );
}

/** The release running and any staged to replace it (lib/server/update.ts); the About window shows only macOS's. */
function Version() {
  const [s, setS] = useState<{ version: string | null; ready: string | null } | null>(null);
  useEffect(() => {
    fetch("/api/update")
      .then((r) => r.json())
      .then(setS, () => setS(null));
  }, []);
  if (!s) return null;
  return (
    <p className="text-[13px] text-ink">
      {s.version ?? "Built from source"}
      {s.ready ? <span className="text-muted-slate"> · {s.ready} downloaded, used when Blueprint restarts</span> : null}
    </p>
  );
}

type ModelStatus = { model: "missing" | "downloading" | "ready"; bytes: number; total: number; error: string | null };

/** The speech model for on-device dictation (src-tauri/src/dictate.rs): fetched once, kept until removed. */
function OnDevice() {
  const [s, setS] = useState<ModelStatus | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const read = useCallback(() => {
    invoke<ModelStatus>("dictate_status").then(setS, (e) => setFailed(String(e)));
  }, []);
  useEffect(() => {
    read();
  }, [read]);
  // Polled only while it downloads, for the progress and for when it lands.
  useEffect(() => {
    if (s?.model !== "downloading") return;
    const t = setInterval(read, 1000);
    return () => clearInterval(t);
  }, [s?.model, read]);
  const act = (cmd: string) => invoke(cmd).then(read, (e) => setFailed(String(e)));
  const mb = (n: number) => Math.round(n / 1e6);
  if (!s) return <span className="font-mono text-[11.5px] text-faint">{failed ?? "Looking…"}</span>;
  return (
    <div className="flex items-baseline gap-3 font-mono text-[11.5px]">
      {s.model === "ready" ? (
        <span className="text-accent">✓ Parakeet v3, {mb(s.total)} MB, on this machine</span>
      ) : s.model === "downloading" ? (
        <span className="text-ink">
          Downloading… {mb(s.bytes)} of {mb(s.total)} MB
        </span>
      ) : (
        <span className={s.error || failed ? "text-clay-ink" : "text-faint"}>
          {s.error ?? failed ?? `Needs its speech model, ${mb(s.total)} MB, downloaded once.`}
        </span>
      )}
      {s.model === "missing" ? (
        <button type="button" onClick={() => act("dictate_download")} className="ml-auto shrink-0 cursor-pointer text-accent hover:underline">
          {s.bytes ? "Resume download" : "Download"}
        </button>
      ) : (
        <button type="button" onClick={() => act("dictate_remove")} className="ml-auto shrink-0 cursor-pointer text-faint hover:text-ink">
          {s.model === "ready" ? "Remove" : "Stop"}
        </button>
      )}
    </div>
  );
}

type Kept = { global: string[]; projects: Record<string, string[]> };

/** The sign-ins the preview keeps (src-tauri/src/signins.rs): for all projects, then each project's own. */
function SignIns() {
  const [kept, setKept] = useState<Kept | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const read = useCallback(() => {
    invoke<Kept>("signin_list").then(setKept, (e) => setFailed(String(e)));
  }, []);
  useEffect(read, [read]);
  if (!kept) return <span className="font-mono text-[11.5px] text-faint">{failed ?? "Looking…"}</span>;
  const rows = [
    ...kept.global.map((site) => ({ site, root: null as string | null, where: "All projects" })),
    ...Object.entries(kept.projects).flatMap(([root, sites]) =>
      sites.map((site) => ({ site, root, where: root.split("/").filter(Boolean).pop() ?? root })),
    ),
  ];
  if (!rows.length) return <span className="font-mono text-[11.5px] text-faint">None yet.</span>;
  return (
    <ul className="flex flex-col gap-1 font-mono text-[11.5px]">
      {rows.map((r) => (
        <li key={`${r.root ?? ""}:${r.site}`} className="flex items-baseline gap-3">
          <span className="truncate text-ink">{r.site}</span>
          <span className="truncate text-faint" title={r.root ?? undefined}>
            {r.where}
          </span>
          <button
            type="button"
            onClick={() => invoke("signin_forget", { root: r.root, site: r.site }).then(read, (e) => setFailed(String(e)))}
            className="ml-auto shrink-0 cursor-pointer text-faint hover:text-ink"
          >
            Forget
          </button>
        </li>
      ))}
      {failed ? <li className="text-clay-ink">{failed}</li> : null}
    </ul>
  );
}

app/components/chrome/statusbar.tsx:
"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
import { Kbd, keys } from "@/components/ui/button";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { openReview } from "@/components/review/diff";
import { openFiles, useFiles } from "@/components/blueprint/files";
import { openPalette } from "@/components/chrome/palette";
import { openProjects, remakeBlueprint } from "@/components/projects/projects";
import { Menu, type MenuItem } from "@/components/ui/menu";
import { projectAction } from "@/lib/client/api";
import { claudePath } from "@/lib/client/claude";
import type { Explain } from "@/lib/server/vault";
import { UNFOLLOWED, claudeMidTurnIn, followTurn } from "@/lib/agent/turns";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import type { Node } from "@/lib/blueprint/schema";
import { STATIC_BLUEPRINT } from "@/lib/blueprint/source";
import { onCreditChanged, percent, readCredit, resetsAt, type Credit } from "@/lib/client/credit";
import { openSettings } from "@/lib/client/settings";
import { cn } from "@/lib/client/utils";
import { isDesktop, useMac } from "@/lib/client/platform";
import { invoke } from "@tauri-apps/api/core";

/**
 * The line along the bottom of the window: what is true of the whole blueprint,
 * whatever level is open. Which commit it describes, the problems it found,
 * whether an update is running, and the two keys that get you
 * anywhere. It is the one place this lives, so no level has to repeat it.
 */
export function StatusBar() {
  const { name, blueprints, RUN, L0, TOP } = useBlueprint();
  const local = blueprints.some((m) => m.id === name && m.local);
  const [project, reread] = useProject(name, local);

  const problems = useMemo(() => {
    let problems = 0;
    const walk = (nodes: Node[]) => {
      for (const n of nodes) {
        problems += n.issues?.length ?? 0;
        walk(n.children ?? []);
      }
    };
    walk(L0);
    // The repository is a level too (D60): its problems count, as the list this opens includes them.
    problems += TOP.issues?.length ?? 0;
    return problems;
  }, [L0, TOP]);
  const files = useFiles();
  const mac = useMac();

  return (
    <footer data-chrome="bar" className="flex h-6 shrink-0 select-none items-center gap-0.5 border-t border-border-gray bg-surface-container-low px-2 text-[11.5px] text-muted-slate">
      {project ? (
        <BlueprintMenu id={name} commit={RUN.commit?.slice(0, 7)} p={project} onChanged={reread} />
      ) : (
        <Item title="The commit this blueprint describes" mono>
          <CommitIcon />
          {RUN.commit?.slice(0, 7) ?? "no commit"}
        </Item>
      )}
      {files?.added.length ? (
        <Item title="Files added since the blueprint was made — click to list them" onClick={() => openFiles("added")} className="text-amber-ink">
          {files.added.length} not on the blueprint yet
        </Item>
      ) : null}
      {problems ? (
        <Item title="Problems the blueprint found in the code — click to list them" onClick={() => openPalette("problems")} className="text-clay-ink">
          <span aria-hidden>⚠</span>
          {problems} {problems === 1 ? "problem" : "problems"}
        </Item>
      ) : null}
      <span className="min-w-0 flex-1" />
      <BlueprintUpdates key={name} p={project} root={RUN.root} local={local} />
      {STATIC_BLUEPRINT ? null : <UpdateReady />}
      {STATIC_BLUEPRINT ? null : <CreditLeft />}
      <Item title="Go to a level, or run an action" onClick={() => openPalette()}>
        Go to <Kbd className={KEY}>{keys(mac, "P")}</Kbd>
      </Item>
      {STATIC_BLUEPRINT ? null : (
        <Item title="Claude Code & terminal" onClick={toggleWorkspace}>
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <rect x="1.5" y="2.5" width="13" height="11" rx="2" />
            <path d="M4.5 6.5 6.5 8l-2 1.5M8.5 10h3" />
          </svg>
          Workspace <Kbd className={KEY}>{keys(mac, "`")}</Kbd>
        </Item>
      )}
    </footer>
  );
}

/** What is left of this 5-hour session's Blueprint credit, while tabs run on it (lib/server/credit.ts). */
/** A newer Blueprint, downloaded and staged (lib/server/update.ts); it goes in when the app next quits, or now. */
function UpdateReady() {
  const [ready, setReady] = useState<string | null>(null);
  useEffect(() => {
    if (!isDesktop()) return;
    const read = () =>
      void fetch("/api/update")
        .then((r) => r.json() as Promise<{ ready: string | null }>)
        .then((s) => setReady(s.ready), () => {});
    read();
    // Asking is local and cheap; the server looks for a release at most every 6 hours.
    const t = setInterval(read, 60_000);
    return () => clearInterval(t);
  }, []);
  if (!ready) return null;
  return (
    <Item title={`Blueprint ${ready} is downloaded. Restart to use it now, or it's used the next time Blueprint opens.`} onClick={() => void invoke("update_restart")} className="text-ink">
      Restart to update
    </Item>
  );
}

function CreditLeft() {
  const [c, setC] = useState<Credit | null>(null);
  useEffect(() => {
    const read = () => void readCredit().then(setC);
    read();
    // The window fills as tabs work, and it is cheap to ask.
    const t = setInterval(read, 60_000);
    const off = onCreditChanged(read);
    return () => {
      clearInterval(t);
      off();
    };
  }, []);
  const session = c?.available && c.on ? c.meters?.session : undefined;
  const used = session && percent(session);
  if (!c?.meters || !session || used == null) return null;
  const ends = resetsAt(session);
  const week = percent(c.meters.week);
  return (
    <Item
      title={`Blueprint credit: ${used}% of this session used${ends ? `, until ${ends}` : ""}${week != null ? `; ${week}% of the week` : ""}. Change it in Settings.`}
      onClick={openSettings}
    >
      Credit {100 - used}%{ends ? ` · ${ends}` : ""}
    </Item>
  );
}

function CommitIcon() {
  return (
    <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden>
      <circle cx="8" cy="8" r="2.5" />
      <path d="M1 8h4.5M10.5 8H15" />
    </svg>
  );
}

/** The open project as the vault has it (app/api/projects/route.ts, GET with an id). */
interface ProjectState {
  status: "empty" | "generating" | "ready" | "failed" | "cancelled";
  paused: boolean;
  explain: Explain;
  update: Update | null;
  redoing?: string[];
}

/**
 * Follows the open project every 2 seconds, for its updates and for what its
 * blueprint menu offers. Only the user's own projects: an example is no project.
 * The second value reads it again at once, after an action changed it.
 */
function useProject(id: string, local: boolean): [ProjectState | null, () => void] {
  const [got, setGot] = useState<{ id: string; p: ProjectState | null } | null>(null);
  const [asked, setAsked] = useState(0);
  useEffect(() => {
    if (!local) return;
    let live = true;
    const read = () =>
      fetch(`/api/projects?id=${encodeURIComponent(id)}`)
        .then((r) => r.json())
        .then((p: ProjectState | null) => live && setGot({ id, p }))
        .catch(() => {});
    void read();
    const timer = setInterval(read, 2000);
    return () => {
      live = false;
      clearInterval(timer);
    };
  }, [id, local, asked]);
  const reread = useCallback(() => setAsked((n) => n + 1), []);
  return [local && got?.id === id ? got.p : null, reread];
}

/**
 * The commit the blueprint describes, and what to do with the blueprint itself:
 * bring it up to the code, make it again, or stop it following the code. They
 * act on the blueprint that is open, so they are here rather than in Projects.
 */
function BlueprintMenu({ id, commit, p, onChanged }: { id: string; commit?: string; p: ProjectState; onChanged: () => void }) {
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const run = async (body: () => Promise<Record<string, unknown>>) => {
    setError(null);
    try {
      await projectAction(await body());
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
    onChanged();
  };
  const generating = p.status === "generating";
  const updating = p.update?.status === "running";
  const items: MenuItem[] = [
    {
      label: "Update Blueprint",
      disabled: generating || updating || p.status !== "ready",
      onClick: () => void run(async () => ({ action: "regenerate", id, claude: await claudePath(), explain: p.explain })),
    },
    { label: "Remake Blueprint", disabled: generating, onClick: () => remakeBlueprint(id) },
    {
      label: p.paused ? "Start Auto-Updates" : "Stop Auto-Updates",
      disabled: generating,
      separated: true,
      onClick: () => void run(async () => ({ action: "pause", id, paused: !p.paused, claude: p.paused ? await claudePath() : undefined })),
    },
  ];
  return (
    <>
      <Item
        title={`The commit this blueprint describes${p.paused ? ". It no longer follows the code" : ""}. Update, remake, or stop updating it`}
        menu={Boolean(at)}
        onClick={(e) => {
          const r = e.currentTarget.getBoundingClientRect();
          setAt(at ? null : { x: r.left, y: r.top - 4 });
        }}
        className="mr-1 border-x border-border-gray text-ink"
      >
        <CommitIcon />
        <span className="font-medium">Blueprint</span>
        <span className="font-mono text-[11px] text-muted-slate">{commit ?? "no commit"}</span>
        {p.paused ? <span className="text-amber-ink">· paused</span> : null}
        <svg width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="text-muted-slate">
          <path d="m1.5 5 2.5-2.5L6.5 5" />
        </svg>
      </Item>
      {at ? <Menu x={at.x} y={at.y} up title={commit ? `Built from ${commit}` : "Not built from a commit"} items={items} onClose={() => setAt(null)} /> : null}
      {error ? (
        <Item title={`${error} Click to dismiss.`} onClick={() => setError(null)} className="min-w-0 text-clay-ink">
          <span className="truncate">✗ {error}</span>
        </Item>
      ) : null}
    </>
  );
}

/** The one thing to do about what the bar says, filled so it reads as a button and not a note. */
const BAR_ACTION =
  "flex h-[18px] shrink-0 cursor-pointer items-center bg-accent px-2 font-sans text-[11px] font-medium text-on-accent hover:bg-accent-strong focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent";

/** A key, sized to the bar. */
const KEY = "h-[15px] min-w-[15px] text-[10px]";

function Item({
  children,
  title,
  onClick,
  menu,
  mono,
  className,
}: {
  children: React.ReactNode;
  title: string;
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  /** Opens a menu; true while it is open. */
  menu?: boolean;
  mono?: boolean;
  className?: string;
}) {
  const cls = cn(
    "flex h-full shrink-0 items-center gap-1.5 px-1.5",
    mono && "font-mono text-[11px]",
    onClick && "cursor-pointer hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
    menu && "bg-surface-container text-ink",
    className,
  );
  return onClick ? (
    <button type="button" title={title} onClick={onClick} aria-haspopup={menu === undefined ? undefined : "menu"} aria-expanded={menu} className={cls}>
      {children}
    </button>
  ) : (
    <span title={title} className={cls}>
      {children}
    </span>
  );
}

interface Update {
  status: "running" | "done" | "failed";
  finishedAt?: string;
  changed?: string[];
  sections?: string[];
  error?: string;
}

/**
 * The section ids an update is rewriting right now, for the open level to say
 * so where the reader is looking (components/blueprint/canvas.tsx): the status bar alone
 * was missed, and a minute with nothing changing read as the update not working.
 */
let redoing: string[] = [];
const redoListeners = new Set<() => void>();
function setRedoing(next: string[]) {
  if (next.join("\n") === redoing.join("\n")) return;
  redoing = next;
  redoListeners.forEach((l) => l());
}
const NONE: string[] = [];
export function useRedoing(): string[] {
  return useSyncExternalStore(
    (l) => (redoListeners.add(l), () => redoListeners.delete(l)),
    () => redoing,
    () => NONE,
  );
}

/**
 * Follows the open blueprint while an agent changes its code: an update redoing
 * the touched sections (lib/server/vault.ts) shows here while it runs. The blueprint takes
 * each section as it lands by itself (components/blueprint/blueprint-context.tsx); this only
 * says what is happening. Only the user's own projects update; an
 * example describes some other copy of its code, so when an agent edits its
 * checkout this says so and offers to import it.
 *
 * The blueprint updates once per commit. Between commits this says how far the
 * code has moved from what the blueprint describes (lib/server/live.ts, followed
 * with the blueprint each second), and asks for an update when HEAD moves. Not
 * while Claude is mid-turn in the checkout: its turn asks when it ends, with its
 * account of what it did. A commit is never retried after it failed, since each
 * try is a paid run; Update now runs regardless.
 */
function BlueprintUpdates({ p, root, local }: { p: ProjectState | null; root?: string; local: boolean }) {
  const u = p?.update ?? null;
  const [unfollowed, setUnfollowed] = useState(false);

  useEffect(() => {
    const on = (e: Event) => (e as CustomEvent<string>).detail === root && setUnfollowed(true);
    window.addEventListener(UNFOLLOWED, on);
    return () => window.removeEventListener(UNFOLLOWED, on);
  }, [root]);
  // The last finished update already on screen, so only a new one reloads.
  const seen = useRef<string | undefined>(undefined);
  const [fresh, setFresh] = useState(false);

  const first = useRef(true);
  useEffect(() => {
    if (!p) return;
    setRedoing(u?.status === "running" ? (p.redoing ?? []) : []);
    const done = u?.status !== "running" ? u?.finishedAt : undefined;
    if (!first.current && done && done !== seen.current) setFresh(true);
    if (done) seen.current = done;
    first.current = false;
  }, [p, u]);
  useEffect(() => () => setRedoing([]), []);

  const { live } = useBlueprint();
  const behind = local ? (live?.files ?? []) : [];
  const head = local ? live?.head : undefined;
  // Updating by hand runs whatever is committed.
  const follow = () => {
    if (root) void followTurn(root, { transcript: null, corrections: [] }, true);
  };
  // A new commit updates the blueprint; the server runs it only for a HEAD it
  // has not updated at (lib/server/vault.ts). Claude mid-turn asks with its turn when it ends.
  // Paused, nothing follows: turning updates back on catches up (lib/server/vault.ts, setPaused).
  const paused = Boolean(p?.paused);
  useEffect(() => {
    if (!head || !root || paused || claudeMidTurnIn(root)) return;
    void followTurn(root, { transcript: null, corrections: [] });
  }, [head, root, paused]);

  useEffect(() => {
    if (!fresh) return;
    const t = setTimeout(() => setFresh(false), 15000);
    return () => clearTimeout(t);
  }, [fresh]);

  if (unfollowed && root)
    return (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title="This blueprint was made from another copy of the code, so it cannot follow edits here.">
          This blueprint doesn&apos;t follow edits
        </span>
        <button
          type="button"
          onClick={() => {
            setUnfollowed(false);
            openProjects(root);
          }}
          className="shrink-0 cursor-pointer text-accent underline"
        >
          Import to keep it updated
        </button>
        <button type="button" onClick={() => setUnfollowed(false)} aria-label="Dismiss" className="shrink-0 cursor-pointer text-faint hover:text-ink">
          ×
        </button>
      </span>
    );
  // A turn that changed nothing the blueprint covers passes silently.
  if (!u || (u.status === "done" && (!fresh || !u.sections?.length)))
    return behind.length && root ? (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title={behind.map((f) => `${f.path} +${f.add} −${f.del}`).join("\n")}>
          Editing · {live?.touched.length ? `${live.touched.length} ${live.touched.length === 1 ? "section" : "sections"}` : "no sections"} affected
          {paused ? " · auto-updates paused" : " · blueprint follows on commit"}
        </span>
        {paused ? null : (
          <button type="button" onClick={follow} className={BAR_ACTION}>
            Update now
          </button>
        )}
      </span>
    ) : null;
  const what = u.sections?.length ? u.sections.join(", ") : u.changed?.join(", ");
  return (
    <span
      title={u.status === "failed" ? u.error : what}
      className={cn(
        "mr-2 flex min-w-0 max-w-[420px] items-center gap-1.5 truncate",
        u.status === "failed" ? "text-clay-ink" : u.status === "running" ? "text-amber-ink" : "text-accent",
      )}
    >
      {u.status === "running" ? <span aria-hidden className="size-[7px] shrink-0 animate-pulse rounded-full bg-amber-ink" /> : null}
      <span className="truncate">
        {u.status === "running"
          ? "Updating the blueprint to match the code…"
          : u.status === "failed"
            ? "✗ Blueprint update failed"
            : `✓ Blueprint updated: ${u.sections!.join(", ")}`}
      </span>
      {u.status === "failed" && root ? (
        <button type="button" onClick={follow} className={BAR_ACTION}>
          Retry
        </button>
      ) : null}
      {u.status === "done" ? (
        <button type="button" onClick={() => (setFresh(false), openReview("turn:latest"))} className="shrink-0 cursor-pointer underline">
          see what changed
        </button>
      ) : null}
    </span>
  );
}

