import { PHASE_DEVELOPMENT_SERVER } from "next/constants";
import type { NextConfig } from "next";

// scripts/export-static.mts builds one blueprint as a static site; otherwise this is the dev app.
const exporting = !!process.env.NEXT_PUBLIC_STATIC_BLUEPRINT;

export default function config(phase: string): NextConfig {
  if (exporting) return { output: "export", basePath: process.env.NEXT_PUBLIC_BASE_PATH, distDir: process.env.BLUEPRINT_EXPORT_DIR };
  // In dev the landing page (../landing) frames this app through its own
  // origin, and both are Next apps with chunks of the same names under
  // /_next. Its own prefix lets the landing's proxy tell this app's apart.
  return phase === PHASE_DEVELOPMENT_SERVER ? { assetPrefix: "/blueprint-app" } : {};
}

app/proxy.ts:
import { NextResponse, type NextRequest } from "next/server";

/**
 * This server answers only to the names of this machine. A site that points its own name at
 * 127.0.0.1 (DNS rebinding) would otherwise read its pages as same-origin, the credit's relay
 * secret among them (app/api/credit). The relay is left out: it checks that secret itself, and
 * Proxy would hold every call's body in memory first.
 */
const LOCAL = new Set(["localhost", "127.0.0.1", "[::1]"]);

export function proxy(request: NextRequest) {
  const host = (request.headers.get("host") ?? "").replace(/:\d+$/, "").toLowerCase();
  return LOCAL.has(host) ? NextResponse.next() : new NextResponse("Not this host.", { status: 421 });
}

export const config = { matcher: "/((?!api/credit/relay|_next/static|_next/image).*)" };

app/scripts/api/admin.mjs:
// Installs, landing visits and finished runs, written by install.sh, the landing page and the app,
// and read back by the dashboard at blpr.dev/admin (admin/index.html), which names each call as it
// did when this lived in Supabase. Writes are open to anyone and keep only what fits; every read
// checks the one dashboard password.
import { createHash, randomBytes, randomInt, scryptSync, timingSafeEqual } from "node:crypto";
import { network } from "./auth.mjs";
import { config, status } from "./credit.mjs";
import { daysAgo, get, getMany, put, query, refused, today, update, without } from "./db.mjs";

/** When Blueprint launched. Everything before it was us testing, so the dashboard counts people from here. */
export const LAUNCH = "2026-11-09T08:00:00.000Z";

const clip = (s, n) => (typeof s === "string" ? s.slice(0, n) : undefined);
const num = (x) => (typeof x === "number" && Number.isFinite(x) ? x : undefined);
const fits = (x, n) => (x != null && JSON.stringify(x).length < n ? x : undefined);
const count = (x) => (Array.isArray(x) ? x.length : undefined);

/** One run of install.sh, with where its IP is (geojs.io, as the landing page asks for its country). */
export async function trackInstall({ os, arch, ok, version, ci } = {}, ip) {
  const at = new Date().toISOString();
  const geo = await fetch(`https://get.geojs.io/v1/ip/geo/${encodeURIComponent(ip)}.json`, { signal: AbortSignal.timeout(2000) })
    .then((r) => (r.ok ? r.json() : {}))
    .catch(() => ({}));
  await put({
    pk: "install", sk: `${at}#${randomInt(1e9)}`, at, os: clip(os, 40), arch: clip(arch, 40), ok: ok === true, version: clip(version, 20), ci: ci === true,
    ip: clip(ip, 45), country: clip(geo.country, 80), region: clip(geo.region, 80), city: clip(geo.city, 80), org: clip(geo.organization_name, 80),
  });
}

/** One browser's day on blpr.dev: where it first came from that day, and whether it copied the install command. Kept 400 days. */
export async function trackVisit({ vid, path, referrer, country, region, source, medium, campaign, copied } = {}) {
  if (typeof vid !== "string" || !/^[0-9a-f-]{36}$/i.test(vid)) return;
  const now = new Date().toISOString();
  const ttl = Math.floor(Date.now() / 1000) + 400 * 86400;
  if (copied === true) {
    await update(`visit#${today()}`, vid, "SET copied = :t, last_at = :now, #ttl = :ttl", { ":t": true, ":now": now, ":ttl": ttl }, undefined, { "#ttl": "ttl" });
    return;
  }
  await update(
    `visit#${today()}`,
    vid,
    "SET #v = if_not_exists(#v, :zero) + :one, last_at = :now, first_at = if_not_exists(first_at, :now), #p = if_not_exists(#p, :path), referrer = if_not_exists(referrer, :ref), country = if_not_exists(country, :country), #region = if_not_exists(#region, :region), #src = if_not_exists(#src, :src), medium = if_not_exists(medium, :med), campaign = if_not_exists(campaign, :camp), #ttl = :ttl",
    {
      ":zero": 0, ":one": 1, ":now": now, ":path": clip(path, 200) ?? null, ":ref": clip(referrer, 300) ?? null, ":country": clip(country, 80) ?? null, ":region": clip(region, 80) ?? null,
      ":src": clip(source, 80) ?? null, ":med": clip(medium, 80) ?? null, ":camp": clip(campaign, 120) ?? null, ":ttl": ttl,
    },
    undefined,
    // VIEWS, PATH, REGION, SOURCE and TTL are DynamoDB reserved words.
    { "#v": "views", "#p": "path", "#region": "region", "#src": "source", "#ttl": "ttl" },
  );
}

/** One finished run. What the app sends is whatever its report says; anything oversized is dropped, so the run still counts. */
export async function recordRun({ r } = {}, ip) {
  if (!r || typeof r !== "object") return;
  const at = new Date().toISOString();
  const id = Date.now() * 1000 + randomInt(1000);
  const report = fits(r.report, 262144);
  const bill = report?.bill && typeof report.bill === "object" && !Array.isArray(report.bill) ? Object.values(report.bill) : null;
  await put({ pk: `runbody#${id}`, sk: "body", report: report === undefined ? undefined : JSON.stringify(report), log_tail: typeof r.log_tail === "string" ? r.log_tail.slice(-65536) : undefined });
  await put({
    pk: "run",
    sk: `${at}#${id}`,
    id,
    at,
    install_id: typeof r.install_id === "string" && /^[0-9a-f-]{36}$/.test(r.install_id) ? r.install_id : undefined,
    // The machine's Blueprint credit id, sent while it is signed in: which GitHub account made the blueprint.
    device: typeof r.device === "string" && /^[0-9a-f]{64}$/.test(r.device) ? r.device : undefined,
    // Only so the dashboard can tell a machine on one of our networks (teamip) from a person's.
    net: ip ? network(ip) : undefined,
    app_version: clip(r.app_version, 20),
    mapper_version: Number.isInteger(r.mapper_version) ? r.mapper_version : undefined,
    kind: clip(r.kind, 20),
    status: clip(r.status, 20) ?? "unknown",
    repo: clip(r.repo, 200),
    repo_commit: clip(r.repo_commit, 64),
    backend: clip(r.backend, 40),
    mode: clip(r.mode, 80),
    files: Number.isInteger(r.files) ? r.files : undefined,
    quick_s: num(r.quick_s),
    total_s: num(r.total_s),
    usd: num(r.usd),
    models: fits(r.models, 4096),
    // What the dashboard reads of the report, kept here so a list never loads one.
    problems: count(report?.check?.problems),
    quick_problems: count(report?.quickCheck?.problems),
    sections: count(report?.deepened),
    accepted: Array.isArray(report?.deepened) ? report.deepened.filter((s) => s?.accepted === true).length : undefined,
    tokens: bill ? bill.reduce((a, b) => a + (Number(b?.input) || 0) + (Number(b?.output) || 0) + (Number(b?.cacheRead) || 0), 0) : undefined,
  });
}

const IMAGE = /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+=*$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const sha = (s) => createHash("sha256").update(s).digest("hex");
export const FEEDBACK_STATUS = ["pending", "in progress", "resolved", "closed"];

/**
 * A bug report or feedback, from the app's Feedback dialog (components/chrome/feedback.tsx) or the
 * landing page's contact form, which must give an email to be answered at. Up to three pictures,
 * each its own item since one item holds at most 400 KB; the sender shrinks them to fit. The sender
 * gets back a key, kept only as its hash here, that lets it read the report's status later.
 */
export async function sendFeedback({ f } = {}) {
  const message = typeof f?.message === "string" ? f.message.trim().slice(0, 8000) : "";
  const email = clip(f?.email, 200)?.trim() || undefined;
  const source = f?.source === "landing" ? "landing" : "app";
  if (!message) return { error: "Say what happened." };
  if (email && !EMAIL.test(email)) return { error: "That email doesn't look right." };
  if (source === "landing" && !email) return { error: "Add an email so we can write back." };
  const images = (Array.isArray(f.images) ? f.images : []).filter((s) => typeof s === "string" && s.length < 380_000 && IMAGE.test(s)).slice(0, 3);
  const at = new Date().toISOString();
  const id = Date.now() * 1000 + randomInt(1000);
  const key = randomBytes(24).toString("base64url");
  await Promise.all(images.map((data, i) => put({ pk: `feedbackimg#${id}`, sk: String(i), data })));
  await put({
    pk: "feedback",
    sk: `${at}#${id}`,
    id,
    at,
    source,
    kind: f.kind === "bug" ? "bug" : "feedback",
    status: "pending",
    message,
    email,
    install_id: typeof f.install_id === "string" && /^[0-9a-f-]{36}$/.test(f.install_id) ? f.install_id : undefined,
    app_version: clip(f.app_version, 20),
    os: clip(f.os, 80),
    images: images.length,
    key_hash: sha(key),
  });
  return { ok: true, id, at, key };
}

/** `{reports: [{id, at, key}]}` → the status of each the sender holds the key to, by id. */
export async function feedbackStatus({ reports } = {}) {
  const asked = (Array.isArray(reports) ? reports : [])
    .filter((r) => Number.isSafeInteger(r?.id) && typeof r.at === "string" && r.at.length < 40 && typeof r.key === "string")
    .slice(0, 100);
  const rows = await getMany(asked.map((r) => ({ pk: "feedback", sk: `${r.at}#${r.id}` })));
  const keyOf = new Map(asked.map((r) => [r.id, r.key]));
  return Object.fromEntries(
    rows.filter((r) => keyOf.has(r.id) && r.key_hash === sha(keyOf.get(r.id))).map((r) => [r.id, { status: r.status ?? "pending", updated_at: r.updated_at ?? null }]),
  );
}

/* ── the dashboard ── */

export class NotAllowed extends Error {}

/** The stored password is scrypt `salt:hash` in hex (scripts/api/hash-password.mjs makes one). */
export async function allowed(pw) {
  const item = await get("admin", "pw");
  const [salt, hash] = (item?.hash ?? "").split(":");
  if (!salt || !hash || typeof pw !== "string") throw new NotAllowed("Not allowed");
  const want = Buffer.from(hash, "hex");
  const got = scryptSync(pw, Buffer.from(salt, "hex"), want.length);
  if (!timingSafeEqual(want, got)) throw new NotAllowed("Not allowed");
}

const same = (a, b) => (a ?? null) === (b ?? null);
const median = (xs) => {
  const v = xs.filter((x) => x != null).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = (v.length - 1) / 2;
  return (v[Math.floor(m)] + v[Math.ceil(m)]) / 2;
};
const mean = (xs) => {
  const v = xs.filter((x) => x != null);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
};
const top = (rows, key, n = 15) => {
  const by = new Map();
  for (const r of rows) {
    const k = r.key;
    if (!by.has(k)) by.set(k, new Set());
    by.get(k).add(r.visitor);
  }
  return [...by].map(([k, s]) => ({ [key]: k, visitors: s.size })).sort((a, b) => b.visitors - a.visitors).slice(0, n);
};

/** The updates a new blueprint went on to get: same machine, same repo, until a new blueprint of that repo was made there. */
function updatesOf(g, runs) {
  const next = runs.filter((n) => n.kind !== "update" && same(n.install_id, g.install_id) && same(n.repo, g.repo) && n.at > g.at).map((n) => n.at).sort()[0];
  return runs.filter((u) => u.kind === "update" && same(u.install_id, g.install_id) && same(u.repo, g.repo) && u.at > g.at && (!next || u.at < next));
}

const summary = (r) => without(r, "pk", "sk");

/** The app version each machine ran last, from its runs: what is still in use, so how long the backend must keep answering it. */
function appsInUse(runs) {
  const last = new Map();
  for (const r of runs) if (!last.has(r.install_id ?? null) || last.get(r.install_id ?? null).at < r.at) last.set(r.install_id ?? null, r);
  const by = new Map();
  for (const r of last.values()) by.set(r.app_version ?? "unknown", (by.get(r.app_version ?? "unknown") ?? 0) + 1);
  return [...by].map(([version, machines]) => ({ version, machines })).sort((a, b) => b.machines - a.machines);
}

/**
 * Ours, not people's: GitHub accounts marked `team` on their account item, and any already signed in
 * before launch. The dashboard also leaves out CI's installs, browsers and machines here before
 * launch, and installs from a network this dashboard was opened from.
 */
const teamOf = (accounts) => new Set(accounts.filter((a) => a.team || (a.first_at && a.first_at < LAUNCH)).map((a) => a.sk));
const unique = (xs) => new Set(xs).size;
const sum = (xs) => xs.reduce((a, x) => a + (Number(x) || 0), 0);

/** People's visits, installs and blueprints since launch, each against what was left out as ours. */
export async function overview({ pw } = {}, ip) {
  await allowed(pw);
  // Whoever opens this page is us, and so is an install from their network.
  if (ip) await put({ pk: "teamip", sk: network(ip), at: new Date().toISOString() });
  const chart = Array.from({ length: 30 }, (_, i) => daysAgo(29 - i));
  const live = Array.from({ length: 400 }, (_, i) => daysAgo(i)).filter((d) => d >= LAUNCH.slice(0, 10)).reverse();
  const [allInstalls, allRuns, accounts, devices, nets, ...visitDays] = await Promise.all([
    query("install", { from: LAUNCH }),
    query("run").then((rs) => rs.map(summary)),
    query("account"),
    query("device"),
    query("teamip").then((ts) => new Set(ts.map((t) => t.sk))),
    ...live.map((d) => query(`visit#${d}`)),
  ]);

  // A browser here before launch was one of ours, and stays ours.
  const allVisits = visitDays.flatMap((vs, i) =>
    vs.map((v) => ({
      day: live[i], visitor: v.sk, first_at: v.first_at, views: Number(v.views) || 0, copied: !!v.copied, path: v.path,
      referrer: v.referrer, source: v.source, medium: v.medium, campaign: v.campaign, country: v.country, region: v.region,
    })),
  );
  const early = new Set(allVisits.filter((v) => v.first_at && v.first_at < LAUNCH).map((v) => v.visitor));
  const visits = allVisits.filter((v) => !early.has(v.visitor));

  const whose = (i) => (i.ci ? "ci" : i.team || (i.ip && nets.has(network(i.ip))) ? "us" : "people");
  const installs = allInstalls.filter((i) => whose(i) === "people");
  const worked = installs.filter((i) => i.ok);

  // A machine is ours once it made a blueprint before launch, on one of our networks or accounts, or in a run marked `team`.
  const team = teamOf(accounts);
  const accountOf = new Map(devices.map((d) => [d.sk, d.account]));
  const ourRun = (r) => r.at < LAUNCH || r.team || (r.net && nets.has(r.net)) || team.has(accountOf.get(r.device));
  const ourMachines = new Set(allRuns.filter(ourRun).map((r) => r.install_id ?? null));
  const runs = allRuns.map((r) => ({ ...r, ours: r.at < LAUNCH || ourMachines.has(r.install_id ?? null) }));
  const people = runs.filter((r) => !r.ours);
  const fresh = people.filter((r) => r.kind !== "update");

  const osRows = new Map();
  for (const i of installs) {
    const k = `${i.os ?? "?"} ${i.arch ?? ""}`.trim();
    const o = osRows.get(k) ?? { os: k, installs: 0, failed: 0 };
    if (i.ok) o.installs++;
    else o.failed++;
    osRows.set(k, o);
  }
  const versions = new Map();
  for (const r of runs.filter((r) => r.kind !== "update")) {
    const k = r.mapper_version ?? null;
    if (!versions.has(k)) versions.set(k, []);
    versions.get(k).push(r);
  }
  const place = (x) => [x.region, x.country].filter(Boolean).join(", ") || "unknown";
  return {
    launch: LAUNCH,
    visitors: unique(visits.map((v) => v.visitor)),
    visits: visits.length,
    views: sum(visits.map((v) => v.views)),
    copied: unique(visits.filter((v) => v.copied).map((v) => v.visitor)),
    installs: worked.length,
    installs_failed: installs.length - worked.length,
    // Installs before IPs were kept have none, and are not guessed at.
    installers: unique(worked.filter((i) => i.ip).map((i) => i.ip)),
    machines: unique(people.map((r) => r.install_id ?? null)),
    blueprints: fresh.filter((r) => r.status === "ok").length,
    blueprints_failed: fresh.filter((r) => r.status !== "ok").length,
    updates: people.length - fresh.length,
    blueprints_usd: sum(people.map((r) => r.usd)),
    left_out: {
      installs_ci: allInstalls.filter((i) => whose(i) === "ci").length,
      installs_ours: allInstalls.filter((i) => whose(i) === "us").length,
      browsers: early.size,
      machines: ourMachines.size,
      runs: runs.filter((r) => r.ours && r.at >= LAUNCH).length,
    },
    daily: chart.map((day) => {
      const v = visits.filter((x) => x.day === day);
      const on = (x) => x.at.startsWith(day);
      return {
        day,
        visitors: v.length,
        copied: v.filter((x) => x.copied).length,
        views: sum(v.map((x) => x.views)),
        installs: worked.filter(on).length,
        installs_failed: installs.filter((i) => !i.ok && on(i)).length,
        runs_ok: fresh.filter((r) => r.status === "ok" && on(r)).length,
        runs_failed: fresh.filter((r) => r.status !== "ok" && on(r)).length,
      };
    }),
    // A tagged link (?utm_source= or ?ref=) names its source; otherwise the site the visitor came from.
    referrers: top(visits.map((v) => ({ key: v.source || v.referrer || "direct", visitor: v.visitor })), "referrer"),
    campaigns: top(visits.filter((v) => v.source || v.campaign).map((v) => ({ key: [v.source, v.medium, v.campaign].filter(Boolean).join(" / "), visitor: v.visitor })), "campaign"),
    pages: top(visits.map((v) => ({ key: v.path || "/", visitor: v.visitor })), "page"),
    countries: top(visits.map((v) => ({ key: v.country ?? "unknown", visitor: v.visitor })), "country"),
    regions: top(visits.filter((v) => v.region).map((v) => ({ key: place(v), visitor: v.visitor })), "place"),
    install_os: [...osRows.values()].sort((a, b) => b.installs - a.installs),
    install_places: top(worked.map((i) => ({ key: place(i), visitor: i.sk })), "place"),
    recent_installs: installs
      .sort((a, b) => (a.at < b.at ? 1 : -1))
      .slice(0, 100)
      .map((i) => ({ at: i.at, ok: i.ok, os: i.os, arch: i.arch, version: i.version, ip: i.ip ?? null, org: i.org ?? null, city: i.city ?? null, region: i.region ?? null, country: i.country ?? null })),
    apps: appsInUse(people),
    // Every blueprint, ours too: what compares one generator version with the next.
    versions: [...versions]
      .map(([v, rs]) => {
        const ok = rs.filter((r) => r.status === "ok");
        return {
          mapper_version: v,
          runs: rs.length,
          failed: rs.length - ok.length,
          first_at: rs.map((r) => r.at).sort()[0],
          last_at: rs.map((r) => r.at).sort().at(-1),
          quick_s: median(ok.map((r) => r.quick_s)),
          total_s: median(ok.map((r) => r.total_s)),
          usd: mean(ok.map((r) => r.usd)),
          files: mean(ok.map((r) => r.files)),
          problems: mean(ok.map((r) => r.problems)),
        };
      })
      .sort((a, b) => (b.mapper_version ?? -1) - (a.mapper_version ?? -1)),
    recent: runs
      .filter((r) => r.kind !== "update")
      .sort((a, b) => (a.at < b.at ? 1 : -1))
      .slice(0, 200)
      .map((g) => {
        const u = updatesOf(g, runs);
        const row = without(g, "models", "problems", "quick_problems", "sections", "accepted", "tokens", "device", "net");
        return { ...row, updates: u.length, updates_usd: u.reduce((a, x) => a + (x.usd ?? 0), 0) };
      }),
  };
}

/** One blueprint's report and log, and its updates (with a log only for those that failed). */
export async function run({ pw, run_id } = {}) {
  await allowed(pw);
  const runs = (await query("run")).map(summary);
  const g = runs.find((r) => String(r.id) === String(run_id));
  if (!g) return null;
  const ups = updatesOf(g, runs).sort((a, b) => (a.at < b.at ? 1 : -1));
  const bodies = new Map((await getMany([g, ...ups].map((r) => ({ pk: `runbody#${r.id}`, sk: "body" })))).map((b) => [b.pk, b]));
  const body = (r) => bodies.get(`runbody#${r.id}`) ?? {};
  const parse = (s) => (s ? JSON.parse(s) : null);
  return {
    models: g.models ?? null,
    report: parse(body(g).report),
    log_tail: body(g).log_tail ?? null,
    updates: ups.map((u) => ({
      id: u.id, at: u.at, status: u.status, mapper_version: u.mapper_version ?? null, total_s: u.total_s ?? null, usd: u.usd ?? null,
      report: parse(body(u).report), log_tail: u.status !== "ok" ? (body(u).log_tail ?? null) : null,
    })),
  };
}

/** Every new blueprint of one repo, oldest first, with what the dashboard compares across generator versions. */
export async function repo({ pw, repo_name } = {}) {
  await allowed(pw);
  const runs = (await query("run")).map(summary);
  return runs
    .filter((g) => g.kind !== "update" && g.repo === repo_name)
    .sort((a, b) => (a.at < b.at ? -1 : 1))
    .map((g) => ({
      id: g.id, at: g.at, install_id: g.install_id ?? null, mapper_version: g.mapper_version ?? null, status: g.status,
      repo_commit: g.repo_commit ?? null, files: g.files ?? null, quick_s: g.quick_s ?? null, total_s: g.total_s ?? null, usd: g.usd ?? null,
      tokens: g.tokens ?? null, quick_problems: g.quick_problems ?? null, problems: g.problems ?? null,
      sections: g.sections ?? null, accepted: g.accepted ?? null, updates: updatesOf(g, runs).length,
    }));
}

/**
 * Blueprint credit (credit.mjs), at list price as it charges. People's use since launch: every account
 * not ours, whole, since none of them was here before; by model from their calls (req#, kept 30 days).
 * And the bill: everyone's spend, ours included, which is what Bedrock charges.
 */
export async function credit({ pw } = {}) {
  await allowed(pw);
  const days = Array.from({ length: 30 }, (_, i) => daysAgo(29 - i));
  const [c, accounts, spend, months, use, usage, life, devices, runs] = await Promise.all([
    config(),
    query("account"),
    query("creditday", { from: days[0] }),
    query("creditmonth"),
    Promise.all(days.map((d) => query(`use#${d}`))),
    Promise.all(days.map((d) => query(`usage#${d}`))),
    query("life"),
    query("device"),
    query("run"),
  ]);
  const team = teamOf(accounts);
  // An account made by hand to let someone in has no first_at until they sign in.
  const people = accounts.filter((a) => a.first_at && !team.has(a.sk));
  const calls = (await Promise.all(people.map((a) => query(`req#${a.sk}`, { from: LAUNCH })))).flat();
  const lifeOf = new Map(life.map((l) => [l.sk, l]));
  const lifetime = (l) => ({
    tab_usd: (Number(l?.tab_micro) || 0) / 1e6,
    gen_usd: (Number(l?.gen_micro) || 0) / 1e6,
    tab_tokens: Number(l?.tab_tok) || 0,
    gen_tokens: Number(l?.gen_tok) || 0,
    calls: (Number(l?.tab_calls) || 0) + (Number(l?.gen_calls) || 0),
    tab_calls: Number(l?.tab_calls) || 0,
    gen_calls: Number(l?.gen_calls) || 0,
    in_tok: Number(l?.in_tok) || 0, out_tok: Number(l?.out_tok) || 0, cr_tok: Number(l?.cr_tok) || 0, cw_tok: Number(l?.cw_tok) || 0,
    since: l?.first_at ?? null,
  });
  const together = (ls) => {
    const t = lifetime(null);
    for (const l of ls) for (const k of Object.keys(t)) if (k !== "since") t[k] += l[k];
    return t;
  };
  // Blueprints by GitHub account, through the machine each was made on.
  const accountOf = new Map(devices.map((d) => [d.sk, d.account]));
  const madeBy = new Map();
  for (const r of runs) {
    const a = r.device && accountOf.get(r.device);
    if (!a) continue;
    const m = madeBy.get(a) ?? { maps: 0, maps_failed: 0, updates: 0, map_report_usd: 0, repos: new Set(), last_map_at: null };
    if (r.kind === "update") m.updates++;
    else if (r.status === "ok") m.maps++;
    else m.maps_failed++;
    m.map_report_usd += Number(r.usd) || 0;
    if (r.repo) m.repos.add(r.repo);
    if (r.kind !== "update" && (!m.last_map_at || r.at > m.last_map_at)) m.last_map_at = r.at;
    madeBy.set(a, m);
  }
  // People first, then by what each has cost; each one's allowance this week, as the app shows it.
  const spent = (x) => { const l = lifetime(lifeOf.get(x.sk)); return l.tab_usd + l.gen_usd; };
  const listed = [...accounts].sort((a, b) => team.has(a.sk) - team.has(b.sk) || spent(b) - spent(a)).slice(0, 200);
  const nowMeters = new Map(await Promise.all(listed.map(async (a) => [a.sk, (await status(a.sk).catch(() => null))?.meters ?? null])));
  const none = () => ({ tab_usd_30: 0, gen_usd_30: 0, calls_30: 0, tokens_30: 0, flagged_30: 0, active_days_30: 0, active_7: false, last_at: null });
  const weekAgo = daysAgo(6);
  const tok = (u) => (Number(u.in_tok) || 0) + (Number(u.out_tok) || 0) + (Number(u.cr_tok) || 0) + (Number(u.cw_tok) || 0);
  const by = new Map();
  for (const u of use.flat()) {
    const d = by.get(u.sk) ?? none();
    d.tab_usd_30 += (Number(u.tab_micro) || 0) / 1e6;
    d.gen_usd_30 += (Number(u.gen_micro) || 0) / 1e6;
    d.calls_30 += (Number(u.tab_calls) || 0) + (Number(u.gen_calls) || 0);
    d.tokens_30 += tok(u);
    d.flagged_30 += Number(u.flagged) || 0;
    d.active_days_30++;
    if (u.pk.slice(4) >= weekAgo) d.active_7 = true;
    if (!d.last_at || u.last_at > d.last_at) d.last_at = u.last_at;
    by.set(u.sk, d);
  }

  // People's calls by model, counted as usage#<day> counts everyone's.
  const FIELDS = ["calls", "micro", "in_tok", "out_tok", "cr_tok", "cw_tok", "cw1h_tok", "flagged", "failed", "throttled"];
  const models = new Map();
  for (const q of calls) {
    const k = `${q.lane}#${q.family}`;
    const m = models.get(k) ?? Object.fromEntries([["lane", q.lane], ["family", q.family], ...FIELDS.map((f) => [f, 0])]);
    const one = {
      calls: 1, micro: q.micro, in_tok: q.in_tok, out_tok: q.out_tok, cr_tok: q.cr_tok, cw_tok: q.cw_tok, cw1h_tok: q.cw1h_tok,
      flagged: q.flags ? 1 : 0, failed: q.code >= 200 && q.code < 300 ? 0 : 1, throttled: q.code === 429 ? 1 : 0,
    };
    for (const f of FIELDS) m[f] += Number(one[f]) || 0;
    models.set(k, m);
  }
  // usage#<day> / refused: everyone's calls turned away, by why.
  const refusedBy = {};
  for (const u of usage.flat().filter((u) => u.sk === "refused"))
    for (const [k, v] of Object.entries(without(u, "pk", "sk", "ttl"))) refusedBy[k] = (refusedBy[k] ?? 0) + (Number(v) || 0);

  const month = today().slice(0, 7);
  return {
    config: c,
    people: { ...together(people.map((a) => lifetime(lifeOf.get(a.sk)))), accounts: people.length, active_7: people.filter((a) => by.get(a.sk)?.active_7).length },
    team_accounts: team.size,
    models: [...models.values()].map(({ micro, ...m }) => ({ ...m, usd: micro / 1e6 })).sort((a, b) => b.usd - a.usd),
    daily: days.map((day, i) => {
      const mine = use[i].filter((u) => !team.has(u.sk));
      return {
        day,
        tab_usd: mine.reduce((a, u) => a + (Number(u.tab_micro) || 0), 0) / 1e6,
        gen_usd: mine.reduce((a, u) => a + (Number(u.gen_micro) || 0), 0) / 1e6,
        tokens: mine.reduce((a, u) => a + tok(u), 0),
        active: mine.length,
        signups: people.filter((a) => a.first_at?.startsWith(day)).length,
        bill_usd: Number(spend.find((x) => x.sk === day)?.usd) || 0,
      };
    }),
    bill: {
      usd_month: Number(months.find((m) => m.sk === month)?.usd) || 0,
      usd_30: spend.reduce((a, d) => a + (Number(d.usd) || 0), 0),
      life: lifetime(lifeOf.get("all")),
    },
    refused: Object.entries(refusedBy).map(([k, n]) => ({ kind: k.replace("_", " · "), n })).sort((a, b) => b.n - a.n),
    accounts: listed.map((a) => {
      const m = madeBy.get(a.sk);
      return {
        account: a.sk, login: a.login ?? null, gh_created: a.gh_created ?? null, first_at: a.first_at ?? null, machines: a.devices?.size ?? 0, team: team.has(a.sk),
        allowed: !!a.allowed, blocked: !!a.blocked, uncapped: !!a.uncapped, note: a.note ?? null, ...(by.get(a.sk) ?? none()),
        life: lifetime(lifeOf.get(a.sk)),
        maps: m?.maps ?? 0, maps_failed: m?.maps_failed ?? 0, updates: m?.updates ?? 0, map_report_usd: m?.map_report_usd ?? 0,
        repos: m ? [...m.repos].slice(0, 50) : [], last_map_at: m?.last_map_at ?? null,
        meters: nowMeters.get(a.sk) ?? null,
      };
    }),
  };
}

/** Every bug report and piece of feedback, newest first, without its pictures. */
export async function feedback({ pw } = {}) {
  await allowed(pw);
  return (await query("feedback")).map((r) => without(r, "pk", "sk", "key_hash")).sort((a, b) => (a.at < b.at ? 1 : -1));
}

/** One report's pictures, as the data URLs the sender sent. */
export async function feedbackImages({ pw, id } = {}) {
  await allowed(pw);
  if (!Number.isSafeInteger(Number(id))) return [];
  return (await query(`feedbackimg#${Number(id)}`)).sort((a, b) => Number(a.sk) - Number(b.sk)).map((i) => i.data);
}

/** Moves a report along; its sender sees the new status in the app. */
export async function setFeedbackStatus({ pw, id, at, status } = {}) {
  await allowed(pw);
  if (!Number.isSafeInteger(id) || typeof at !== "string" || !FEEDBACK_STATUS.includes(status)) return null;
  return update("feedback", `${at}#${id}`, "SET #s = :s, updated_at = :now", { ":s": status, ":now": new Date().toISOString() }, "attribute_exists(pk)", { "#s": "status" }).catch((e) => {
    if (refused(e)) return null;
    throw e;
  });
}

app/scripts/api/auth.mjs:
// Who may use Blueprint credit: a GitHub account, checked here with GitHub itself. A machine id alone
// was never enough, since the app computes it and anyone can make one up; it stays only to hold an
// account to a few machines and a machine to one account. Signing in gives the machine a session,
// which it keeps; the session is swapped for access tokens that last 30 minutes, which the proxy
// checks without reading the table.
import { createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { config } from "./credit.mjs";
import { del, get, put, refused, today, update } from "./db.mjs";

const ACCESS_SECONDS = 30 * 60;
const SESSION_DAYS = 90;

const hash = (s) => createHash("sha256").update(s).digest("hex");
const mac = (s) => createHmac("sha256", process.env.TOKEN_SECRET).update(s).digest("base64url");
const bearer = (headers) => (headers.authorization ?? "").replace(/^Bearer\s+/i, "");
const epoch = () => Math.floor(Date.now() / 1000);

/** The network an address is on: an IPv6 address by its /64, since one machine can rotate through all of that. */
export function network(ip) {
  const a = String(ip);
  if (!a.includes(":")) return a;
  const [head, tail = ""] = a.split("::");
  const h = head ? head.split(":") : [];
  const t = tail ? tail.split(":") : [];
  const full = [...h, ...Array(Math.max(0, 8 - h.length - t.length)).fill("0"), ...t];
  return `${full.slice(0, 4).join(":")}::/64`;
}

/** The person behind a token the app got from GitHub's device flow. The token itself is not kept. */
async function githubUser(token) {
  if (typeof token !== "string" || !token || token.length > 512) return null;
  const r = await fetch("https://api.github.com/user", {
    headers: { authorization: `Bearer ${token}`, accept: "application/vnd.github+json", "user-agent": "blueprint-credit", "x-github-api-version": "2022-11-28" },
    signal: AbortSignal.timeout(10_000),
  }).catch(() => null);
  const u = r?.ok ? await r.json().catch(() => null) : null;
  return u?.id && u.type === "User" ? { id: `gh:${u.id}`, login: String(u.login), created: String(u.created_at) } : null;
}

/** `{github_token, device}` → a session for this machine, or why not. */
export async function signIn({ github_token, device } = {}, ip) {
  if (typeof device !== "string" || !/^[0-9a-f]{64}$/.test(device)) return { reason: "Not a device id." };
  const gh = await githubUser(github_token);
  if (!gh) return { reason: "GitHub didn't accept that sign-in. Try again." };
  const c = await config();
  if (!((Date.now() - Date.parse(gh.created)) / 86400_000 >= c.gh_min_age_days))
    return { reason: `Blueprint credit needs a GitHub account at least ${c.gh_min_age_days} days old.` };

  const [account, machine] = await Promise.all([get("account", gh.id), get("device", device)]);
  if (account?.blocked) return { reason: "Blueprint credit isn't available to this GitHub account." };
  const other = "This machine already uses Blueprint credit with another GitHub account.";
  if (machine?.account && machine.account !== gh.id) return { reason: other };
  const limit = account?.devices_per_account ?? c.devices_per_account;
  const full = `This GitHub account already uses Blueprint credit on ${limit} machines.`;
  const had = !!account?.devices?.has?.(device);

  // One free allowance per person: a network can only start a few new ones a day.
  if (!account) {
    try {
      await update(`ipreg#${network(ip)}`, today(), "SET n = if_not_exists(n, :zero) + :one, #ttl = :ttl",
        { ":zero": 0, ":one": 1, ":max": c.new_accounts_per_ip_day, ":ttl": epoch() + 2 * 86400 }, "attribute_not_exists(n) OR n < :max", { "#ttl": "ttl" });
    } catch (e) {
      if (refused(e)) return { reason: "Too many new Blueprint credit accounts from this network today." };
      throw e;
    }
  }

  const now = new Date().toISOString();
  try {
    await update("account", gh.id, "SET login = :l, gh_created = :c, first_at = if_not_exists(first_at, :now), last_at = :now ADD devices :d",
      { ":l": gh.login, ":c": gh.created, ":now": now, ":d": new Set([device]), ":dv": device, ":lim": limit },
      "attribute_not_exists(devices) OR contains(devices, :dv) OR size(devices) < :lim");
  } catch (e) {
    if (refused(e)) return { reason: full };
    throw e;
  }
  // Bound after the account, and only if no other account got there first.
  try {
    await update("device", device, "SET account = :a, #at = if_not_exists(#at, :now), ip = if_not_exists(ip, :ip)",
      { ":a": gh.id, ":now": now, ":ip": String(ip).slice(0, 64) }, "attribute_not_exists(account) OR account = :a", { "#at": "at" });
  } catch (e) {
    if (!refused(e)) throw e;
    if (!had) await update("account", gh.id, "DELETE devices :d", { ":d": new Set([device]) });
    return { reason: other };
  }

  const session = `s1.${randomBytes(32).toString("base64url")}`;
  await put({ pk: "session", sk: hash(session), account: gh.id, device, at: now, last_at: now, ttl: epoch() + SESSION_DAYS * 86400 });
  return { session, login: gh.login };
}

/** A session's next access token, or null once it has been signed out or has lapsed. */
export async function refresh(headers) {
  const s = bearer(headers);
  if (!s.startsWith("s1.")) return null;
  const row = await get("session", hash(s));
  // DynamoDB deletes an expired row up to days later; until then it is still gone.
  if (!row || Number(row.ttl) < epoch()) return null;
  // Kept alive by use, written at most hourly.
  if (Date.now() - Date.parse(row.last_at) > 3600_000)
    await update("session", row.sk, "SET last_at = :now, #ttl = :ttl", { ":now": new Date().toISOString(), ":ttl": epoch() + SESSION_DAYS * 86400 }, undefined, { "#ttl": "ttl" });
  const exp = epoch() + ACCESS_SECONDS;
  const payload = Buffer.from(JSON.stringify({ a: row.account, d: row.device, exp })).toString("base64url");
  return { token: `a1.${payload}.${mac(`a1.${payload}`)}`, exp };
}

export async function signOut(headers) {
  const s = bearer(headers);
  if (s.startsWith("s1.")) await del("session", hash(s));
}

/** The account and machine an access token was made for, while it lasts. */
export function accessOf(headers) {
  const [v, payload, sig] = bearer(headers).split(".");
  if (v !== "a1" || !payload || !sig) return null;
  const want = Buffer.from(mac(`a1.${payload}`));
  const got = Buffer.from(sig);
  if (want.length !== got.length || !timingSafeEqual(want, got)) return null;
  try {
    const p = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    return p.exp > epoch() && typeof p.a === "string" ? { account: p.a, device: p.d } : null;
  } catch {
    return null;
  }
}

app/scripts/api/credit.mjs:
// Blueprint credit: Claude on Blueprint's own Bedrock, for people signed in to Blueprint with GitHub
// (auth.mjs). Answers as Bedrock does, so Claude Code (in Bedrock mode) and the generator
// (scripts/generate/bedrock.ts) talk to it unchanged, both through the app's local relay. Each call is
// shaped (policy.mjs), admitted against its account's allowance, forwarded byte for byte to one of
// the project's tagged inference profiles, and settled at what Bedrock says it used.
//
// `tab` is Claude Code in a Blueprint tab and has a 5-hour window and a weekly one, as Claude Code's
// own plans do; `gen` is blueprint generation and has a weekly window. Spend is in millionths of a
// dollar at list price (a price in $ per million tokens is micro-dollars per token). The settings
// are the `credit / config` item (DEFAULTS), changed in the DynamoDB console, never in the app. An
// account's own item can carry any of the limits, or `uncapped`, `allowed` (let in while the credit
// is off for everyone) or `blocked`.
import { createHash, createHmac, randomBytes } from "node:crypto";
import { network } from "./auth.mjs";
import { del, get, put, refused, today, update, without } from "./db.mjs";
import { shape } from "./policy.mjs";

const REGION = process.env.AWS_REGION || "us-east-1";
const HOST = `bedrock-runtime.${REGION}.amazonaws.com`;
const PROFILES = JSON.parse(process.env.PROFILES ?? "{}");
const OPS = new Set(["invoke-with-response-stream", "invoke", "count-tokens"]);

/** $ per million tokens through a global profile (the 5.5 models); a cache write costs 1.25× input. Haiku's is for prompts up to 100K tokens. */
const PRICE = { haiku: { in: 0.1, out: 0.5, cr: 0.01 }, sonnet: { in: 2, out: 10, cr: 0.2 }, opus: { in: 4, out: 20, cr: 0.2 } };

const familyOf = (model) => (/haiku/i.test(model) ? "haiku" : /opus/i.test(model) ? "opus" : "sonnet");

/* ── settings ── */

export const DEFAULTS = {
  enabled: false,
  ends_at: null,
  policy: "log",
  gh_min_age_days: 30,
  devices_per_account: 2,
  new_accounts_per_ip_day: 5,
  window_hours: 5,
  week_hours: 168,
  // About half of Claude Pro: its 5-hour session runs to roughly $6–8 of Claude Code at list price.
  tab_usd_5h: 4,
  tab_usd_week: 40,
  // Maps are offered as unlimited: this is fair use, about sixteen mid-size maps a week, which nobody making maps
  // reaches. It is what holds the lane to its price, since anyone signed in can call it without the generator.
  gen_usd_week: 200,
  // A tab's own throttles; map generation has none, so it runs as fast as Bedrock takes it.
  tab_inflight: 10,
  usd_per_minute: 1,
  max_tokens: 32000,
  // The generator's authors ask for 64,000 (scripts/generate/author.ts); cut at 32,000 they stop mid-answer.
  gen_max_tokens: 64000,
  // What `gen` calls are held to when it differs from `policy`: the generator is Blueprint's own, so its shape is known.
  gen_policy: null,
  // Everyone's spend this calendar month, kept under the AWS Budget's own cut-off (80% of $6,000), so
  // the credit stops with a clear message before Bedrock is taken away from this function.
  monthly_usd_ceiling: 4500,
};
let cached = null;
/** The settings, read at most every 30 seconds per running copy of this function. */
export async function config() {
  if (cached && Date.now() - cached.at < 30_000) return cached.value;
  const value = { ...DEFAULTS, ...without(await get("credit", "config"), "pk", "sk") };
  cached = { at: Date.now(), value };
  return value;
}

const MICRO = 1e6;
const epoch = () => Math.floor(Date.now() / 1000);
const ended = (c) => !!c.ends_at && Date.now() >= Date.parse(c.ends_at);
const open = (c, a) => !!a && !a.blocked && (!!a.allowed || (!!c.enabled && !ended(c)));

/** What the landing page asks: whether the promotion is on for everyone right now, and when it ends. */
export async function promo() {
  const c = await config();
  return { on: !!c.enabled && !ended(c), ends_at: c.ends_at ?? null };
}

/** The windows a lane spends from, and how long each stays open. */
const WINDOWS = { tab: ["tab5h", "tabweek"], gen: ["genweek"] };
const hoursOf = (c, w) => (w === "tab5h" ? c.window_hours : c.week_hours);
const LIMIT_OF = { tab5h: "tab_usd_5h", tabweek: "tab_usd_week", genweek: "gen_usd_week" };
const pick = (c, a, k) => a?.[k] ?? c[k];
/** A window's cap in µ$, or null for none: an uncapped account, or a limit set to null. */
const limitOf = (c, a, w) => (a?.uncapped || pick(c, a, LIMIT_OF[w]) == null ? null : pick(c, a, LIMIT_OF[w]) * MICRO);
const capOf = (c, a, w) => limitOf(c, a, w) ?? Number.MAX_SAFE_INTEGER;

/** Spend in a window while it is open, and when it closes; nothing once it has. */
async function windowOf(account, w, hours) {
  const row = await get(`win#acct:${account}`, w);
  const ends = row?.started ? Date.parse(row.started) + hours * 3600_000 : 0;
  return ends > Date.now() ? { used: Number(row.micro) || 0, resets: new Date(ends).toISOString() } : { used: 0, resets: null };
}

/** What the app shows: whether the credit is there for this account, and each of its windows. */
export async function status(account) {
  const c = await config();
  const a = await get("account", account);
  const meters = Object.fromEntries(
    await Promise.all(
      Object.keys(LIMIT_OF).map(async (w) => [w, { ...(await windowOf(account, w, hoursOf(c, w))), limit: limitOf(c, a, w) }]),
    ),
  );
  const reason = !a ? "Sign in again." : a.blocked ? "Blueprint credit isn't available to this account." : ended(c) && !a.allowed ? "Blueprint's free Claude Code promotion has ended." : !open(c, a) ? "Blueprint credit isn't open yet." : undefined;
  return { available: open(c, a), reason, login: a?.login ?? null, ends_at: c.ends_at ?? null, meters };
}

/* ── admitting and settling a call ── */

/**
 * Adds `micro` to an open window while it is under `cap`, or starts the window afresh once the last has
 * closed. The update is conditional, so calls made at once each see the others' share. `started` names
 * the window it was charged to, so settling never lands on the next one; `resets` is when a full window opens again.
 */
async function charge(account, w, hours, cap, micro, again = true) {
  const key = `win#acct:${account}`;
  const cut = new Date(Date.now() - hours * 3600_000).toISOString();
  try {
    const row = await update(key, w, "SET micro = micro + :m", { ":m": micro, ":cut": cut, ":cap": cap }, "started > :cut AND micro < :cap");
    return { started: row.started };
  } catch (e) {
    if (!refused(e)) throw e;
  }
  const row = await get(key, w);
  if (row?.started > cut) {
    // Opened by a call made at the same moment, after this one's update missed it: under the cap, charge it.
    if (again && Number(row.micro) < cap) return charge(account, w, hours, cap, micro, false);
    return { resets: new Date(Date.parse(row.started) + hours * 3600_000).toISOString() };
  }
  const started = new Date().toISOString();
  try {
    await put({ pk: key, sk: w, started, micro, ttl: epoch() + hours * 3600 + 86400 }, "attribute_not_exists(pk) OR attribute_not_exists(started) OR started <= :cut", { ":cut": cut });
    return { started };
  } catch (e) {
    // Another call opened the window first: it is open now.
    if (!refused(e) || !again) throw e;
    return charge(account, w, hours, cap, micro, false);
  }
}

/** One of the account's `n` call slots on a lane, held until released; null when all are taken. A lease ends with the function's 15-minute limit, so a call that dies holding one frees it. */
async function takeSlot(account, lane, n) {
  const lease = randomBytes(8).toString("hex");
  for (let i = 0; i < n; i++) {
    try {
      await put({ pk: `slot#${account}`, sk: `${lane}#${i}`, lease_id: lease, lease_until: Date.now() + 900_000, ttl: epoch() + 1800 }, "attribute_not_exists(pk) OR lease_until < :now", { ":now": Date.now() });
      return { sk: `${lane}#${i}`, lease };
    } catch (e) {
      if (!refused(e)) throw e;
    }
  }
  return null;
}

const quiet = (p) =>
  p.catch((e) => {
    if (!refused(e)) console.error(e);
  });

/** Moves everything a call reserved from its guess to what it cost, and lets its slot go. Settling at 0 undoes a call that never ran. */
async function settle(account, lane, held, micro) {
  const d = micro - held.guess;
  await Promise.all([
    // Only to the window the call was charged to: one that has since closed and reopened is left alone.
    ...held.windows.map(({ w, started }) => quiet(update(`win#acct:${account}`, w, "ADD micro :d", { ":d": d, ":s": started }, "started = :s"))),
    held.minute && quiet(update(`rate#${account}`, held.minute, "ADD micro :d", { ":d": d })),
    held.day && quiet(update("creditday", held.day, "ADD usd :u, #lane :u", { ":u": d / MICRO }, undefined, { "#lane": `${lane}_usd` })),
    held.month && quiet(update("creditmonth", held.month, "ADD usd :u", { ":u": d / MICRO })),
    held.slot && quiet(del(`slot#${account}`, held.slot.sk, "lease_id = :l", { ":l": held.slot.lease })),
  ]);
}

const until = (iso) => Math.max(1, Math.round((Date.parse(iso) - Date.now()) / 1000));

/**
 * Whether this account may make a call now, reserving `guess` against every limit it meets: a call
 * slot, the account's spend this minute, everyone's spend this month, and the lane's windows. A refusal
 * gives back whatever was reserved before it. `wait` refusals are a throttle the caller retries;
 * the others last until `resets`.
 */
async function admit(c, account, a, lane, guess) {
  if (!open(c, a)) return { ok: false, kind: "closed", reason: ended(c) && !a?.allowed ? "Blueprint's free Claude Code promotion has ended." : "Blueprint credit isn't available to this account." };
  const held = { guess, windows: [], minute: null, day: null, month: null, slot: null };
  const no = async (r) => (await settle(account, lane, held, 0), { ok: false, ...r });

  if (lane === "tab") {
    held.slot = await takeSlot(account, lane, pick(c, a, "tab_inflight"));
    if (!held.slot) return no({ kind: "slots", wait: 5, reason: "Too many Claude calls at once on this account; this one waits its turn." });
  }

  if (lane === "tab" && !a.uncapped) {
    const minute = new Date().toISOString().slice(0, 16);
    const cap = pick(c, a, "usd_per_minute") * MICRO;
    try {
      await update(`rate#${account}`, minute, "ADD micro :m SET #ttl = :ttl", { ":m": guess, ":cap": cap, ":ttl": epoch() + 3600 }, "attribute_not_exists(micro) OR micro < :cap", { "#ttl": "ttl" });
      held.minute = minute;
    } catch (e) {
      if (!refused(e)) throw e;
      return no({ kind: "minute", wait: 61 - new Date().getSeconds(), reason: "This account is spending fast; calls slow down for a minute." });
    }
  }

  const day = today();
  const month = day.slice(0, 7);
  try {
    // An uncapped account's spend still counts toward the month, but the month's ceiling doesn't stop it.
    if (a.uncapped) await update("creditmonth", month, "ADD usd :u", { ":u": guess / MICRO });
    else await update("creditmonth", month, "ADD usd :u", { ":u": guess / MICRO, ":cap": c.monthly_usd_ceiling }, "attribute_not_exists(usd) OR usd < :cap");
    held.month = month;
  } catch (e) {
    if (!refused(e)) throw e;
    return no({ kind: "month", reason: "Blueprint credit has run out for this month. Switch to your own Claude Code in Settings.", resets: new Date(Date.UTC(+month.slice(0, 4), +month.slice(5, 7), 1)).toISOString() });
  }
  // The day's spend, for the admin page.
  await update("creditday", day, "ADD usd :u, #lane :u", { ":u": guess / MICRO }, undefined, { "#lane": `${lane}_usd` });
  held.day = day;

  for (const w of WINDOWS[lane]) {
    const { started, resets } = await charge(account, w, hoursOf(c, w), capOf(c, a, w), guess);
    if (resets) return no({ kind: w, reason: w === "genweek" ? "This week's Blueprint credit for maps is used up." : "Your Blueprint credit for Claude Code is used up for now.", resets });
    held.windows.push({ w, started });
  }
  return { ok: true, held };
}

/** A rough price for a call before Bedrock says what it used: its prompt as if a tenth were new, and up to 4,000 tokens out. */
const guessOf = (family, bytes, maxTokens) => Math.ceil((bytes / 4) * PRICE[family].in * 0.1 + Math.min(maxTokens, 4000) * PRICE[family].out);
/**
 * The most a call can cost: a token per byte of prompt, all of it written to the hour cache, and every token
 * out it may ask for. Maps have no cap on calls at once, so only this keeps a burst within the week's cap:
 * the window stops admitting once it is reached, over it by at most the last call's own.
 */
const worstOf = (family, bytes, maxTokens) => Math.ceil(bytes * PRICE[family].in * 2 + maxTokens * PRICE[family].out);
/** A one-hour cache write costs twice the input price; `cache_write` counts both kinds. */
const microOf = (family, u) => {
  const p = PRICE[family];
  const hour = Math.min(u.cache_write_1h ?? 0, u.cache_write);
  return Math.ceil(u.input * p.in + (u.cache_write - hour) * p.in * 1.25 + hour * p.in * 2 + u.cache_read * p.cr + u.output * p.out);
};

/* ── SigV4, for the one host and two headers this needs ── */
const sha = (s) => createHash("sha256").update(s).digest("hex");
const hmac = (k, s) => createHmac("sha256", k).update(s).digest();
function signed(path, body, extra) {
  const now = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");
  const day = now.slice(0, 8);
  const headers = { host: HOST, "x-amz-date": now, ...(process.env.AWS_SESSION_TOKEN ? { "x-amz-security-token": process.env.AWS_SESSION_TOKEN } : {}) };
  const names = Object.keys(headers).sort();
  // Bedrock, like every service but S3, signs each path segment encoded a second time.
  const uri = path.split("/").map((s) => encodeURIComponent(s)).join("/");
  const canonical = ["POST", uri, "", ...names.map((n) => `${n}:${headers[n]}`), "", names.join(";"), sha(body)].join("\n");
  const scope = `${day}/${REGION}/bedrock/aws4_request`;
  const toSign = ["AWS4-HMAC-SHA256", now, scope, sha(canonical)].join("\n");
  let k = hmac(`AWS4${process.env.AWS_SECRET_ACCESS_KEY}`, day);
  for (const part of [REGION, "bedrock", "aws4_request"]) k = hmac(k, part);
  const signature = createHmac("sha256", k).update(toSign).digest("hex");
  return {
    ...extra,
    ...headers,
    authorization: `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/${scope}, SignedHeaders=${names.join(";")}, Signature=${signature}`,
  };
}

/**
 * Reads the usage out of Bedrock's event stream as it passes, without holding it up: each message is
 * a length-prefixed frame whose payload is {"bytes": base64 of one Anthropic stream event}. A stream
 * cut off before its final usage is counted by the characters that did come.
 */
function meter() {
  const usage = { input: 0, output: 0, cache_read: 0, cache_write: 0, cache_write_1h: 0 };
  let buf = Buffer.alloc(0);
  let chars = 0;
  let final = false;
  const take = (ev) => {
    if (ev.type === "content_block_delta") chars += (ev.delta?.text ?? ev.delta?.thinking ?? ev.delta?.partial_json ?? "").length;
    const u = ev.type === "message_start" ? ev.message?.usage : ev.type === "message_delta" ? ev.usage : null;
    if (!u) return;
    if (ev.type === "message_delta") final = true;
    if (u.input_tokens != null) usage.input = u.input_tokens;
    if (u.cache_read_input_tokens != null) usage.cache_read = u.cache_read_input_tokens;
    if (u.cache_creation_input_tokens != null) usage.cache_write = u.cache_creation_input_tokens;
    if (u.cache_creation?.ephemeral_1h_input_tokens != null) usage.cache_write_1h = u.cache_creation.ephemeral_1h_input_tokens;
    if (u.output_tokens != null) usage.output = u.output_tokens;
  };
  return {
    usage: () => (final ? usage : { ...usage, output: Math.max(usage.output, Math.ceil(chars / 4)) }),
    push(chunk) {
      buf = Buffer.concat([buf, chunk]);
      while (buf.length >= 12) {
        const total = buf.readUInt32BE(0);
        if (buf.length < total) break;
        const headers = buf.readUInt32BE(4);
        const payload = buf.subarray(12 + headers, total - 4);
        buf = buf.subarray(total);
        try {
          const b = JSON.parse(payload.toString("utf8")).bytes;
          if (b) take(JSON.parse(Buffer.from(b, "base64").toString("utf8")));
        } catch {
          // An exception frame, or one this does not read: it still reached the caller.
        }
      }
    },
    json(text) {
      try {
        const u = JSON.parse(text).usage ?? {};
        take({ type: "message_start", message: { usage: u } });
        take({ type: "message_delta", usage: u });
      } catch {
        // Not a reply with usage.
      }
    },
  };
}

/** A refused call, counted by why for the admin page: none of them reached Bedrock. */
const countRefusal = (lane, kind) =>
  quiet(update(`usage#${today()}`, "refused", "ADD #k :one SET #ttl = if_not_exists(#ttl, :ttl)", { ":one": 1, ":ttl": epoch() + 400 * 86400 }, undefined, { "#k": `${lane}_${kind ?? "other"}`, "#ttl": "ttl" }));

/** One call kept 30 days, for review, and its tokens added to the account's day and to its model's. */
async function record(account, lane, family, ip, headers, flags, code, u, micro) {
  const now = new Date();
  await Promise.all([
    quiet(
      update(`usage#${today()}`, `${lane}#${family}`, "ADD calls :one, micro :m, in_tok :i, out_tok :o, cr_tok :r, cw_tok :w, cw1h_tok :h, flagged :f, failed :x, throttled :t SET #ttl = if_not_exists(#ttl, :ttl)",
        { ":one": 1, ":m": micro, ":i": u.input, ":o": u.output, ":r": u.cache_read, ":w": u.cache_write, ":h": u.cache_write_1h ?? 0, ":f": flags.length ? 1 : 0, ":x": code >= 200 && code < 300 ? 0 : 1, ":t": code === 429 ? 1 : 0, ":ttl": epoch() + 400 * 86400 },
        undefined, { "#ttl": "ttl" }),
    ),
    quiet(
      put({
        pk: `req#${account}`,
        sk: `${now.toISOString()}#${randomBytes(3).toString("hex")}`,
        lane,
        family,
        cls: String(headers["x-claude-code-request-class"] ?? "").slice(0, 20) || undefined,
        code,
        in_tok: u.input,
        out_tok: u.output,
        cr_tok: u.cache_read,
        cw_tok: u.cache_write,
        cw1h_tok: u.cache_write_1h || undefined,
        micro,
        net: network(ip),
        flags: flags.length ? flags : undefined,
        ttl: epoch() + 30 * 86400,
      }),
    ),
    quiet(
      update(`use#${today()}`, account, "ADD #calls :one, #micro :m, in_tok :i, out_tok :o, cr_tok :r, cw_tok :w, flagged :f SET last_at = :now, #ttl = :ttl",
        { ":one": 1, ":m": micro, ":i": u.input, ":o": u.output, ":r": u.cache_read, ":w": u.cache_write, ":f": flags.length ? 1 : 0, ":now": now.toISOString(), ":ttl": epoch() + 120 * 86400 },
        undefined, { "#calls": `${lane}_calls`, "#micro": `${lane}_micro`, "#ttl": "ttl" }),
    ),
    // Kept for good, everyone's and each account's: the dashboard's lifetime totals, which the dated rows above expire out of.
    ...["all", account].map((sk) =>
      quiet(
        update("life", sk, "ADD #calls :one, #micro :m, #tok :t, in_tok :i, out_tok :o, cr_tok :r, cw_tok :w, failed :x, flagged :f SET first_at = if_not_exists(first_at, :now), last_at = :now",
          { ":one": 1, ":m": micro, ":t": u.input + u.output + u.cache_read + u.cache_write, ":i": u.input, ":o": u.output, ":r": u.cache_read, ":w": u.cache_write, ":x": code >= 200 && code < 300 ? 0 : 1, ":f": flags.length ? 1 : 0, ":now": now.toISOString() },
          undefined, { "#calls": `${lane}_calls`, "#micro": `${lane}_micro`, "#tok": `${lane}_tok` }),
      ),
    ),
  ]);
}

/** Answers one Bedrock call on a lane, as Bedrock would, writing to `stream`. */
export async function relay({ stream, reply, account, ip, lane, model, op, headers, body }) {
  if (!OPS.has(op)) return reply(404, { message: "Not found." });
  const c = await config();
  const a = await get("account", account);
  const refuse = (r) => {
    const after = r.wait ?? (r.resets ? until(r.resets) : null);
    // A throttle Claude Code and the generator retry; a used-up allowance they show at once, which a retry-after over 60 does.
    return reply(429, { message: r.wait ? r.reason : `${r.reason}${r.resets && !r.reason.includes("midnight") ? ` It opens again at ${new Date(r.resets).toUTCString()}.` : ""} Switch to my Claude Code below to keep going on your own.` }, {
      "x-should-retry": r.wait ? "true" : "false",
      "x-amzn-errortype": r.wait ? "ThrottlingException" : "ServiceQuotaExceededException",
      ...(after ? { "retry-after": String(after) } : {}),
    });
  };

  // Counting tokens costs nothing, so it is not metered, only kept to Claude models.
  if (op === "count-tokens") {
    const id = decodeURIComponent(model);
    if (!open(c, a)) return refuse({ reason: "Blueprint credit isn't available to this account." });
    if (!/^((global|us|eu|apac)\.)?anthropic\.claude-[\w.:-]+$/.test(id)) return reply(400, { message: "Not a Claude model." });
    return forward({ stream, op, target: id, headers, body });
  }

  const family = familyOf(decodeURIComponent(model));
  const shaped = shape({ lane, body, headers, maxTokens: lane === "gen" ? c.gen_max_tokens : c.max_tokens });
  if (!shaped.body) return reply(400, { message: "Not a model call." }, { "x-amzn-errortype": "ValidationException" });
  if (shaped.flags.length && (lane === "gen" ? (c.gen_policy ?? c.policy) : c.policy) === "enforce") {
    await record(account, lane, family, ip, headers, shaped.flags, 403, { input: 0, output: 0, cache_read: 0, cache_write: 0 }, 0);
    return reply(403, { message: "Blueprint credit only runs Claude Code in Blueprint's tabs and Blueprint's own map generation." }, { "x-amzn-errortype": "AccessDeniedException" });
  }

  const guess = (lane === "gen" ? worstOf : guessOf)(family, shaped.body.length, shaped.maxTokens);
  const ok = await admit(c, account, a, lane, guess);
  if (!ok.ok) return (await countRefusal(lane, ok.kind), refuse(ok));

  const meters = meter();
  let code = 0;
  try {
    code = await forward({ stream, op, target: PROFILES[family], headers, body: shaped.body, meters });
  } finally {
    // Settled whatever happened to the stream: a call the caller walked away from still cost what it used.
    const u = code >= 200 && code < 300 ? meters.usage() : { input: 0, output: 0, cache_read: 0, cache_write: 0 };
    const micro = microOf(family, u);
    await settle(account, lane, ok.held, micro);
    await record(account, lane, family, ip, headers, shaped.flags, code, u, micro);
  }
}

/** Sends one call to Bedrock and its reply back as Bedrock gave it; the reply's status. */
async function forward({ stream, op, target, headers, body, meters }) {
  const upstream = `/model/${encodeURIComponent(target)}/${op}`;
  // Nothing else: Bedrock's own headers can pick a dearer service tier or a guardrail, billed but not metered here.
  const pass = Object.fromEntries(Object.entries(headers).filter(([k]) => k === "content-type" || k === "accept"));
  const res = await fetch(`https://${HOST}${upstream}`, { method: "POST", headers: signed(upstream, body, pass), body });
  const out = awslambda.HttpResponseStream.from(stream, {
    statusCode: res.status,
    headers: Object.fromEntries([...res.headers].filter(([k]) => k === "content-type" || k.startsWith("x-amzn-"))),
  });
  if (op === "invoke-with-response-stream" && res.ok) {
    try {
      for await (const chunk of res.body) {
        const b = Buffer.from(chunk);
        meters?.push(b);
        // The caller has gone: stop reading, so Bedrock stops writing what nobody reads.
        if (out.destroyed) break;
        out.write(b);
      }
    } catch (e) {
      // Bedrock dropped the stream partway: the caller sees it end short and retries, and what it used is still billed.
      console.error(e);
    }
  } else {
    const text = await res.text();
    if (op === "invoke" && res.ok) meters?.json(text);
    out.write(text);
  }
  out.end();
  return res.status;
}

