/**
 * Numbers for comparing blueprints, the explorify benchmark included. A blueprint that
 * matches these is not proven good — that takes a walk through it in the
 * browser — but one that misses them is reliably worse.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- blueprint and report JSON */
import { existsSync, readFileSync } from "node:fs";
import type { Node } from "@/lib/blueprint/schema";
import type { BlueprintFile } from "@/lib/blueprint/build";
import { rootOf } from "@/lib/server/blueprints";
import { citations, type BlueprintIndex } from "@/lib/blueprint/coverage";
import { bareLines, check, fileReader, LEAF } from "./check";
import { owners, type Cut } from "./cut";

export function evaluate(name: string, blueprint: BlueprintFile) {
  const nodes: Node[] = [];
  const walk = (n: Node) => { nodes.push(n); (n.children ?? []).forEach(walk); };
  blueprint.AUTHORED.forEach(walk);
  const blocks = nodes.flatMap((n) => n.anatomy ?? []);
  const diagrams = blocks.filter((b) => b.kind === "diagram") as any[];
  const parents = nodes.filter((n) => n.children?.length);
  // D40: how much of the way down is through the picture.
  const linked = parents.map((n) => {
    const kids = new Set(n.children!.map((c) => c.id));
    const opened = new Set((n.anatomy ?? []).flatMap((b: any) => (b.kind === "diagram" ? b.boxes.map((x: any) => x.opens) : [])).filter((id: string) => kids.has(id)));
    return opened.size / kids.size;
  });
  const report = existsSync(`blueprints/${name}/report.json`) ? JSON.parse(readFileSync(`blueprints/${name}/report.json`, "utf8")) : null;
  const root = rootOf(blueprint.RUN);
  const generated = Boolean(blueprint.RUN.models);
  const problems = existsSync(root) ? check(blueprint, root, { generated }).problems.length : "no checkout";
  const depth = (n: Node): number => 1 + Math.max(0, ...(n.children ?? []).map(depth));
  // How far each leaf is from being one piece of code (LEAF in check.ts).
  const leaves = nodes.filter((n) => !n.children?.length);
  const span = (n: Node) => (n.code ?? []).reduce((a, c) => a + c.end - c.start + 1, 0);
  const fat = leaves.filter((n) => (n.code?.length ?? 0) > LEAF.refs || new Set((n.code ?? []).map((c) => c.file)).size > LEAF.files || span(n) > LEAF.lines);
  const spans = leaves.map(span).sort((a, b) => a - b);
  const parentBoxes = parents.flatMap((n) => (n.anatomy ?? []).flatMap((b: any) => (b.kind === "diagram" ? b.boxes : [])));
  const median = (xs: number[]) => (xs.length ? xs[Math.floor(xs.length / 2)] : 0);
  // How much of a leaf's explanation leads to its code, and how much of the blueprint a newcomer can read.
  const steps = leaves.flatMap((n) => (n.anatomy ?? []).flatMap((b: any) => (b.kind === "flow" || b.kind === "sequence" ? b.rows : [])));
  const explained = nodes.filter((n) => n.explain?.body);
  // What the blueprint leaves a developer to find alone: source no level cites, levels that only restate one file, arrows pointing at an import.
  const index: BlueprintIndex | null = existsSync(`blueprints/${name}/index.json`) ? JSON.parse(readFileSync(`blueprints/${name}/index.json`, "utf8")) : null;
  const cited = citations(blueprint.AUTHORED);
  const source = Object.entries(index?.files ?? {}).filter(([, f]) => f.status === "source").map(([p]) => p);
  const filesUnder = (n: Node): Set<string> => new Set([...(n.code ?? []).map((c) => c.file), ...(n.children ?? []).flatMap((c) => [...filesUnder(c)])]);
  const linesOf = existsSync(root) ? fileReader(root) : null;
  const arrows = [...diagrams, ...(blueprint.OVERVIEW?.anatomy ?? []).filter((b) => b.kind === "diagram")].flatMap((d: any) => d.arrows);
  const bare = arrows.filter((a: any) => {
    const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(a.at ?? "");
    const lines = m && linesOf?.(m[1]);
    return lines ? bareLines(lines).slice(+m![2] - 1, +(m![3] ?? m![2])).every(Boolean) : false;
  });
  const asked = existsSync(`blueprints/${name}/ask.json`) ? JSON.parse(readFileSync(`blueprints/${name}/ask.json`, "utf8")).summary : null;
  const pct = (x?: number) => (x === undefined ? "" : Math.round(100 * x));
  return {
    blueprint: name,
    roots: blueprint.AUTHORED.length,
    nodes: nodes.length,
    depth: blueprint.AUTHORED.map(depth).join(""),
    "kids/parent": +(parents.reduce((a, n) => a + n.children!.length, 0) / Math.max(1, parents.length)).toFixed(1),
    "refs/node": +(nodes.reduce((a, n) => a + (n.code?.length ?? 0), 0) / nodes.length).toFixed(1),
    "diagram %": Math.round((100 * nodes.filter((n) => n.anatomy?.some((b) => b.kind === "diagram")).length) / nodes.length),
    "boxes/diagram": +(diagrams.reduce((a, d) => a + d.boxes.length, 0) / Math.max(1, diagrams.length)).toFixed(1),
    "opens %": Math.round((100 * linked.reduce((a, x) => a + x, 0)) / Math.max(1, linked.length)),
    "blocks/node": +(blocks.length / nodes.length).toFixed(1),
    "parts w/o box %": Math.round((100 * linked.reduce((a, x) => a + (1 - x), 0)) / Math.max(1, linked.length)),
    "inert boxes %": Math.round((100 * parentBoxes.filter((x: any) => !x.opens).length) / Math.max(1, parentBoxes.length)),
    "fat leaves %": Math.round((100 * fat.length) / Math.max(1, leaves.length)),
    "leaf refs": +(leaves.reduce((a, n) => a + (n.code?.length ?? 0), 0) / Math.max(1, leaves.length)).toFixed(1),
    "leaf lines med": median(spans),
    "leaf lines max": spans[spans.length - 1] ?? 0,
    "leaf blocks": +(leaves.reduce((a, n) => a + (n.anatomy?.length ?? 0), 0) / Math.max(1, leaves.length)).toFixed(1),
    "leaf diagrams %": Math.round((100 * leaves.filter((n) => n.anatomy?.some((b) => b.kind === "diagram")).length) / Math.max(1, leaves.length)),
    "steps cited %": Math.round((100 * steps.filter((r: any) => r.at).length) / Math.max(1, steps.length)),
    "explain %": Math.round((100 * explained.length) / nodes.length),
    "explain words": median(explained.map((n) => n.explain!.body.split(/\s+/).filter(Boolean).length).sort((a, b) => a - b)),
    "explain pics %": Math.round((100 * explained.filter((n) => n.explain!.blocks?.length).length) / Math.max(1, explained.length)),
    "explain kinds": [...new Set(explained.flatMap((n) => (n.explain!.blocks ?? []).map((b) => b.kind)))].join(","),
    glossary: blueprint.OVERVIEW?.glossary?.length ?? 0,
    walks: blueprint.OVERVIEW?.walkthroughs?.length ?? (blueprint.OVERVIEW?.walkthrough ? 1 : 0),
    "data table": (blueprint.OVERVIEW?.anatomy ?? []).some((b) => b.kind === "table" && /data lives/i.test(b.caption ?? "")) ? 1 : 0,
    "uncited files %": index ? Math.round((100 * source.filter((p) => !cited.has(p)).length) / Math.max(1, source.length)) : "",
    "one-file parts %": Math.round((100 * parents.filter((n) => filesUnder(n).size === 1).length) / Math.max(1, parents.length)),
    "import arrows": bare.length,
    "ask blueprint %": pct(asked?.blueprint?.score),
    "ask grep %": pct(asked?.grep?.score),
    "ask both %": pct(asked?.both?.score),
    "ask both tok": asked?.both?.tokens ?? "",
    "ask grep tok": asked?.grep?.tokens ?? "",
    "detail words": median(nodes.map((n) => (n.detail ?? "").split(/\s+/).filter(Boolean).length).sort((a, b) => a - b)),
    issues: nodes.reduce((a, n) => a + (n.issues?.length ?? 0), 0),
    "not certain %": Math.round((100 * nodes.filter((n) => n.state !== "derived").length) / nodes.length),
    problems,
    "inferred arrows %": report?.arrows?.total ? Math.round((100 * report.arrows.inferred) / report.arrows.total) : "",
    usd: report?.fullUsd ?? "",
    // Tokens sent and received over the whole run, cached prompt reads included (in thousands).
    "k tokens": report ? Math.round(Object.values(report.bill as Record<string, { input: number; output: number; cacheRead: number }>).reduce((a, b) => a + b.input + b.output + b.cacheRead, 0) / 1000) : "",
    min: report ? Math.round(report.elapsed.total / 60) : "",
  };
}

/**
 * How far a fresh cut drifts from the blueprint's own: for each source file, do the
 * two cuts put it with the same neighbours? Root ids and titles differ between
 * samples, so files are compared pairwise — two files together in one cut and
 * apart in the other is a disagreement.
 */
export function stability(name: string, otherCutFile: string): string {
  const a: Cut = JSON.parse(readFileSync(`blueprints/${name}/.cache/cut.json`, "utf8"));
  const b: Cut = JSON.parse(readFileSync(otherCutFile, "utf8"));
  const sums = Object.keys(JSON.parse(readFileSync(`blueprints/${name}/.cache/summaries.json`, "utf8")));
  const key = (c: Cut, p: string) => owners(c, p).sort().join(",") || "(excluded)";
  let agree = 0, total = 0;
  for (let i = 0; i < sums.length; i++)
    for (let j = i + 1; j < sums.length; j++) {
      const sa = key(a, sums[i]) === key(a, sums[j]);
      const sb = key(b, sums[i]) === key(b, sums[j]);
      total++;
      if (sa === sb) agree++;
    }
  return `${name}: ${a.roots.length} vs ${b.roots.length} roots; pairwise file-grouping agreement ${((100 * agree) / total).toFixed(1)}% over ${sums.length} files\n  A: ${a.roots.map((r) => r.title).join(" · ")}\n  B: ${b.roots.map((r) => r.title).join(" · ")}`;
}

app/scripts/generate/fast.ts:
/**
 * The fast blueprint (--fast): the same blueprint file, made in four phases where code
 * does what code can and a model only names and describes.
 *
 * 1. Extraction, no model: the inventory, the fact graph, and from them the
 *    module graph (calls between components, weighted) and the entry points,
 *    written to arch.json. The summarize stage's reading of each file is the
 *    one model input, as in the full pipeline.
 * 2. Partition, no model: files grouped by directory into a tree. The top
 *    level is the deepest directory level with at most TOP_MAX groups; inside
 *    a component, groups of at most MAX_FILES files, by subdirectory, and a
 *    flat directory still too big split along its own imports.
 * 3. Fan out: one short call per component, all at once, no tools and no
 *    thinking: its title, sub, what it is responsible for, and a title for
 *    each of its groups and files.
 * 4. Synthesize: one short call over the components and the module graph for
 *    the blueprint's top line, their order and a label per arrow. Arrows are drawn
 *    from the graph, never from the model: an arrow it names that the graph
 *    lacks is listed as a discrepancy, not drawn. The blueprint is checked once and
 *    its problems listed, not sent back for repair.
 *
 * What it gives up against the full pipeline: levels follow directories, not
 * what a person does; a file's level lists its functions as steps rather than
 * explaining them; there are no explainers and no walkthroughs.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model answers */
import { basename } from "node:path";
import type { Node } from "@/lib/blueprint/schema";
import type { BlueprintFile, Overview } from "@/lib/blueprint/build";
import { prefixFor } from "./author";
import { ask, UsageLimitError, type Tool } from "./bedrock";
import { check, LEAF, looksLikePath, SUB_WORDS, words } from "./check";
import type { Graph } from "./graph";
import { isSource, type Inventory } from "./inventory";
import { oneLine, type FileSummary } from "./summarize";
import { thinArrows } from "./thin";

/** Files one group holds at most: one diagram a reader takes in. SLOP_FAST_MAX. */
export const MAX_FILES = Number(process.env.SLOP_FAST_MAX ?? 12);
/** Files past which a component with groups is described in a call per group. SLOP_FAST_SPLIT. */
const SPLIT_FILES = Number(process.env.SLOP_FAST_SPLIT ?? 30);
/** Components the top level holds at most. SLOP_FAST_TOP. */
const TOP_MAX = Number(process.env.SLOP_FAST_TOP ?? 12);
/** Sibling sections of one app merged into one stay within this many files. SLOP_FAST_FAMILY. */
const FAMILY_MAX = Number(process.env.SLOP_FAST_FAMILY ?? 40);
/** Sections the top level keeps at least, however small its families. */
const TOP_MIN = 4;
/** Columns a diagram is laid out in at most: past this it outgrows the page. */
const COLS = 3;

interface Group {
  key: string;
  dir: string;
  files: string[];
  /** For a cluster of a flat directory: the file the others import most, which names it. */
  hub?: string;
}
export interface Component {
  id: string;
  prefix: string;
  dir: string;
  files: string[];
  /** Its middle level, when it is too big to show its files at once; empty when they are its children. */
  groups: Group[];
}
export interface ModuleEdge {
  from: string;
  to: string;
  /** Calls and imports from one component's files into the other's. */
  weight: number;
  calls: number;
  /** The line of one call, preferring one the source states: the arrow's `at`. */
  at?: string;
  inferred: boolean;
  /** What is called, a few names. */
  names: string[];
}

export const slug = (s: string) => s.toLowerCase().replace(/\.[a-z0-9]+$/, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "x";
/** A directory's name as an id: `.claude` → claude. */
const dirSlug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const segsOf = (dir: string) => (dir && dir !== "." ? dir.split("/") : []);
const dirAt = (path: string, depth: number) => path.split("/").slice(0, -1).slice(0, depth).join("/");

/**
 * A directory too big to read as one group, with no subdirectories to split
 * it by: its files joined along their own imports, the most-linked pairs
 * first, while a cluster stays within MAX_FILES (union-find, as a spanning
 * tree is built). Files linked to nothing in it are chunked in name order.
 */
export function splitFlat(dir: string, ps: string[], inv: Inventory): Omit<Group, "key">[] {
  const set = new Set(ps);
  const weight = new Map<string, number>();
  for (const a of ps)
    for (const b of inv.imports[a] ?? [])
      if (set.has(b) && a !== b) {
        const k = a < b ? `${a}\n${b}` : `${b}\n${a}`;
        weight.set(k, (weight.get(k) ?? 0) + 1);
      }
  const root = new Map(ps.map((p) => [p, p]));
  const size = new Map(ps.map((p) => [p, 1]));
  const find = (p: string): string => {
    while (root.get(p) !== p) p = root.get(p)!;
    return p;
  };
  for (const [k] of [...weight].sort((x, y) => y[1] - x[1] || x[0].localeCompare(y[0]))) {
    const [a, b] = k.split("\n").map(find);
    if (a === b || size.get(a)! + size.get(b)! > MAX_FILES) continue;
    root.set(b, a);
    size.set(a, size.get(a)! + size.get(b)!);
  }
  const clusters = new Map<string, string[]>();
  for (const p of ps) clusters.set(find(p), [...(clusters.get(find(p)) ?? []), p]);
  const out: Omit<Group, "key">[] = [];
  const loose: string[] = [];
  for (const files of clusters.values()) {
    if (files.length === 1) {
      loose.push(files[0]);
      continue;
    }
    const into = (f: string) => files.filter((x) => (inv.imports[x] ?? []).includes(f)).length;
    out.push({ dir, files, hub: [...files].sort((a, b) => into(b) - into(a) || a.localeCompare(b))[0] });
  }
  loose.sort();
  for (let i = 0; i < loose.length; i += MAX_FILES) out.push({ dir, files: loose.slice(i, i + MAX_FILES) });
  return out;
}

/** Files in groups of at most MAX_FILES: by directory, deeper where one is too big, along imports where it is flat. */
function fineGroups(paths: string[], inv: Inventory, depth: number): Omit<Group, "key">[] {
  const by = new Map<string, string[]>();
  for (const p of paths) by.set(dirAt(p, depth), [...(by.get(dirAt(p, depth)) ?? []), p]);
  return [...by].flatMap(([dir, ps]) => {
    if (ps.length <= MAX_FILES) return [{ dir, files: ps }];
    const deeper = ps.filter((p) => p.split("/").length - 1 > depth);
    const own = ps.filter((p) => !deeper.includes(p));
    return [...(deeper.length ? fineGroups(deeper, inv, depth + 1) : []), ...(own.length > MAX_FILES ? splitFlat(dir, own, inv) : own.length ? [{ dir, files: own }] : [])];
  });
}

/** Directories two paths share, from the root. */
const shared = (a: string, b: string) => {
  const x = segsOf(a), y = segsOf(b);
  let n = 0;
  while (n < x.length && n < y.length && x[n] === y[n]) n++;
  return n;
};

/**
 * Groups of a component too small to be worth a box (a directory per API
 * route, one file each) folded into the sibling they share the most
 * directories with, while it stays within MAX_FILES; the merged group sits
 * at the directories they share.
 */
function coalesce(groups: Omit<Group, "key">[]): Omit<Group, "key">[] {
  const out = groups.map((g) => ({ ...g, files: [...g.files] }));
  for (let changed = true; changed; ) {
    changed = false;
    const small = out.filter((g) => g.files.length < 3).sort((a, b) => a.files.length - b.files.length || a.dir.localeCompare(b.dir));
    for (const g of small) {
      const into = out
        .filter((o) => o !== g && o.files.length + g.files.length <= MAX_FILES)
        .sort((a, b) => shared(b.dir, g.dir) - shared(a.dir, g.dir) || a.files.length - b.files.length)[0];
      if (!into) continue;
      into.files.push(...g.files);
      into.dir = segsOf(into.dir).slice(0, shared(into.dir, g.dir)).join("/");
      if (into.hub && !g.hub) delete into.hub;
      out.splice(out.indexOf(g), 1);
      changed = true;
      break;
    }
  }
  return out;
}

/** Phase 2: the files as a tree of components and, inside a big one, groups. */
export function partition(inv: Inventory): Component[] {
  const files = inv.files.filter(isSource).map((f) => f.path);
  const fine = fineGroups(files, inv, 1);
  // The top level: the deepest directory level that still has at most TOP_MAX groups.
  const deepest = Math.max(1, ...fine.map((g) => segsOf(g.dir).length));
  const keyAt = (g: Omit<Group, "key">, d: number) => segsOf(g.dir).slice(0, d).join("/") || ".";
  let d = 1;
  for (let k = deepest; k >= 1; k--)
    if (new Set(fine.map((g) => keyAt(g, k))).size <= TOP_MAX) {
      d = k;
      break;
    }
  const tops = new Map<string, Omit<Group, "key">[]>();
  for (const g of fine) tops.set(keyAt(g, d), [...(tops.get(keyAt(g, d)) ?? []), g]);
  let comps = [...tops].map(([dir, gs]) => ({ dir, groups: gs, files: gs.flatMap((g) => g.files) }));

  // A component of one file joins the one it shares the most imports with; one tied to none stays.
  const linked = (a: string[], b: string[]) =>
    a.reduce((n, f) => n + (inv.imports[f] ?? []).filter((t) => b.includes(t)).length, 0) + b.reduce((n, f) => n + (inv.imports[f] ?? []).filter((t) => a.includes(t)).length, 0);
  for (const c of [...comps].filter((x) => x.files.length === 1)) {
    const others = comps.filter((x) => x !== c);
    const best = others.map((o) => [o, linked(c.files, o.files)] as const).sort((a, b) => b[1] - a[1])[0];
    if (best && best[1] > 0) {
      best[0].groups.push(...c.groups);
      best[0].files.push(...c.files);
      comps = others;
    }
  }

  // Sibling sections of one small app (landing/app, landing/components and
  // landing's own files) are one section with them as its groups, smallest
  // family first, while the family stays within FAMILY_MAX files and the top
  // level keeps at least TOP_MIN sections.
  const parentOf = (dir: string) => segsOf(dir).slice(0, -1).join("/");
  for (;;) {
    const fams = new Map<string, typeof comps>();
    for (const c of comps) if (segsOf(c.dir).length >= 2) fams.set(parentOf(c.dir), [...(fams.get(parentOf(c.dir)) ?? []), c]);
    const members = (dir: string, cs: typeof comps) => [...cs, ...comps.filter((c) => c.dir === dir)];
    const size = (cs: typeof comps) => cs.reduce((n, c) => n + c.files.length, 0);
    const pick = [...fams]
      .map(([dir, cs]) => [dir, members(dir, cs)] as const)
      .filter(([, ms]) => ms.length >= 2 && size(ms) <= FAMILY_MAX && comps.length - ms.length + 1 >= TOP_MIN)
      .sort((a, b) => size(a[1]) - size(b[1]))[0];
    if (!pick) break;
    const [dir, ms] = pick;
    const at = comps.indexOf(ms[0]);
    const merged = { dir, groups: ms.flatMap((m) => m.groups), files: ms.flatMap((m) => m.files) };
    comps = comps.filter((c) => !ms.includes(c));
    comps.splice(Math.min(at, comps.length), 0, merged);
  }

  // Ids from the directory's last name, else its last two: `components`, `landing-components`.
  const last = (dir: string, n: number) => segsOf(dir).slice(-n).map(dirSlug).filter(Boolean).join("-") || "root";
  const ids = new Set<string>();
  const taken = new Set<string>();
  return comps.map((c) => {
    let id = comps.some((o) => o !== c && last(o.dir, 1) === last(c.dir, 1)) ? last(c.dir, 2) : last(c.dir, 1);
    for (let n = 2; ids.has(id); n++) id = `${id.replace(/-\d+$/, "")}-${n}`;
    ids.add(id);
    // A middle level only when the files will not fit on one diagram, and there is more than one group.
    const keys = new Set<string>();
    const fine = c.files.length > MAX_FILES ? coalesce(c.groups) : [];
    const groups =
      fine.length > 1
        ? fine.map((g) => {
            const rel = segsOf(g.dir).slice(segsOf(c.dir).length).map(dirSlug).join("-");
            let key = [rel, g.hub ? slug(basename(g.hub)) : ""].filter(Boolean).join("-") || "files";
            for (let n = 2; keys.has(key); n++) key = `${key.replace(/-\d+$/, "")}-${n}`;
            keys.add(key);
            return { ...g, key };
          })
        : [];
    return { id, prefix: prefixFor(id, taken), dir: c.dir, files: [...c.files].sort(), groups };
  });
}

/** Phase 1: the graph's calls rolled up between components; imports add weight but no line. */
export function moduleGraph(g: Graph, comps: Component[]): ModuleEdge[] {
  const owner = new Map<string, string>();
  for (const c of comps) for (const f of c.files) owner.set(f, c.id);
  const fileOf = new Map(g.defs.map((d) => [d.id, d.file]));
  const nameOf = new Map(g.defs.map((d) => [d.id, d.name]));
  const edges = new Map<string, ModuleEdge>();
  // Per link, each name called with how often and one line it is called on, a stated call over one matched by name.
  const called = new Map<string, Map<string, { n: number; at: string; inferred: boolean }>>();
  for (const e of g.edges) {
    const a = owner.get(fileOf.get(e.from) ?? e.from), b = owner.get(fileOf.get(e.to) ?? e.to);
    if (!a || !b || a === b) continue;
    const k = `${a}\n${b}`;
    const m = edges.get(k) ?? { from: a, to: b, weight: 0, calls: 0, inferred: true, names: [] };
    m.weight++;
    if (e.kind !== "imports" && e.lines.length) {
      m.calls++;
      const name = nameOf.get(e.to) ?? basename(e.to);
      const byName = called.get(k) ?? new Map();
      const c = byName.get(name) ?? { n: 0, at: `${fileOf.get(e.from) ?? e.from}:${e.lines[0]}`, inferred: e.how !== "extracted" };
      c.n += e.lines.length;
      if (c.inferred && e.how === "extracted") [c.at, c.inferred] = [`${fileOf.get(e.from) ?? e.from}:${e.lines[0]}`, false];
      byName.set(name, c);
      called.set(k, byName);
    }
    edges.set(k, m);
  }
  // The names most called first, and the arrow's line one of the first's calls: what its label describes is what it cites.
  for (const [k, m] of edges) {
    const byName = [...(called.get(k) ?? new Map<string, { n: number; at: string; inferred: boolean }>())].sort((x, y) => y[1].n - x[1].n || Number(x[1].inferred) - Number(y[1].inferred));
    m.names = byName.slice(0, 4).map(([n]) => n);
    if (byName.length) [m.at, m.inferred] = [byName[0][1].at, byName[0][1].inferred];
  }
  return [...edges.values()].sort((x, y) => y.weight - x.weight);
}

/** Files nothing in the repository imports, that import something: where the code starts. */
export function entrypoints(inv: Inventory): string[] {
  const imported = new Set(Object.values(inv.imports).flat());
  return inv.files.filter((f) => isSource(f) && !imported.has(f.path) && (inv.imports[f.path] ?? []).length).map((f) => f.path);
}

const NAMED = {
  title: { type: "string", description: "1-3 words, Title Case: what this is to a reader, named for what its parts do together. Never a filler word: not Core, Main, Other, Misc, Supporting, Extended, Files or Utilities alone. No file names." },
  sub: { type: "string", description: `At most ${SUB_WORDS} words (count them): what it does. No file names.` },
};
const FILES_FIELD = {
  type: "array",
  description: "One entry per file listed, in the order a reader should meet them.",
  items: { type: "object", additionalProperties: false, required: ["path", "title", "sub"], properties: { path: { type: "string" }, ...NAMED } },
};
const HEAD_FIELDS = {
  title: { type: "string", description: "1-4 words, Title Case. What a person does here, as an action ('Reading A Post', 'Signing Up'), or for shared code a plain noun ('Shared Layouts')." },
  sub: { type: "string", description: `At most ${SUB_WORDS} words (count them), plainly: what someone does or gets here. No file names.` },
  responsibility: { type: "string", description: "1-2 sentences, at most 40 words: what this component is responsible for, in this project's words." },
  interface: { type: "array", items: { type: "string" }, description: "Its key functions, components or routes that the rest of the code uses." },
  notes: { type: "string", description: "Anything surprising, or empty." },
  groups: {
    type: "array",
    description: "One entry per group listed (none if no groups are listed), in the order a reader should meet them.",
    items: { type: "object", additionalProperties: false, required: ["key", "title", "sub", "detail"], properties: { key: { type: "string" }, ...NAMED, detail: { type: "string", description: "1-2 sentences, at most 40 words: what this group does." } } },
  },
};
const HEAD_REQUIRED = ["title", "sub", "responsibility", "interface", "groups"];
const COMPONENT_TOOL: Tool = {
  name: "component",
  description: "Record what this component of the codebase is.",
  input_schema: { type: "object", additionalProperties: false, required: [...HEAD_REQUIRED, "files"], properties: { ...HEAD_FIELDS, files: FILES_FIELD } },
};
/** A big component's own level and groups, its files described group by group (FILES_TOOL) beside it. */
const HEAD_TOOL: Tool = {
  name: "component",
  description: "Record what this component of the codebase is and what each of its groups does.",
  input_schema: { type: "object", additionalProperties: false, required: HEAD_REQUIRED, properties: HEAD_FIELDS },
};
const FILES_TOOL: Tool = {
  name: "files",
  description: "Record what each file of this group is.",
  input_schema: { type: "object", additionalProperties: false, required: ["files"], properties: { files: FILES_FIELD } },
};
const SHORTEN_TOOL: Tool = {
  name: "shortened",
  description: "Record each text rewritten within its limit.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["texts"],
    properties: { texts: { type: "array", items: { type: "object", additionalProperties: false, required: ["n", "text"], properties: { n: { type: "integer" }, text: { type: "string" } } } } },
  },
};

const SYNTH_TOOL: Tool = {
  name: "overview",
  description: "Record the blueprint's top level.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["sub", "detail", "order", "arrows"],
    properties: {
      sub: { type: "string", description: `At most ${SUB_WORDS} words: what this project is.` },
      detail: { type: "string", description: "Two sentences, at most 40 words: what the project does and how its components divide the work." },
      order: { type: "array", items: { type: "string" }, description: "Every component id, in the order a reader should meet them: what a person meets first, shared code last." },
      arrows: {
        type: "array",
        description: "A label for each link listed, and only those.",
        items: { type: "object", additionalProperties: false, required: ["from", "to", "label"], properties: { from: { type: "string" }, to: { type: "string" }, label: { type: "string", description: "2-4 words, at most 24 characters: what the link means ('renders the cards', 'formats dates')." } } },
      },
    },
