//! The web in the preview: pages from outside this machine (a search, a
//! library's docs, a service the project calls), which the proxy (preview.rs)
//! cannot frame. Each opens in a webview of its own laid over the Preview
//! tab's viewport (components/preview/preview.tsx keeps it there), with the same agent
//! inside (agent.js). The page never calls the app: the tab asks it things by
//! running script in it and collects what it has to say the same way, so a
//! site on the open web is handed nothing of the app's.
//!
//! And Claude's clicks and keys, on macOS: given to the webview as AppKit
//! events, the preview's own frame or one of these pages alike. A page cannot
//! tell them from a person's, so whatever works for the user works for Claude:
//! a popup, a file picker, a button in a frame from another site.

use serde::Deserialize;
use serde_json::{json, Value};
use std::sync::mpsc;
use std::time::Duration;
use tauri::webview::{NewWindowResponse, PageLoadEvent};
use tauri::{AppHandle, Emitter, LogicalPosition, LogicalSize, Manager, Rect, Url, WebviewBuilder, WebviewUrl};

const AGENT: &str = include_str!("agent.js");
const GONE: &str = "The page is gone from the preview.";

fn web(url: &str) -> Result<Url, String> {
    let u = Url::parse(url).map_err(|_| format!("Not an address: {url}"))?;
    if !matches!(u.scheme(), "http" | "https") {
        return Err(format!("Only http and https pages open in the preview, not {url}"));
    }
    Ok(u)
}

/// A page from the web, at a place in the window: CSS pixels of the app's
/// page, with `zoom` the scale the viewport is drawn at. With `project`, in
/// that project's own store of sign-ins rather than the shared one (signins.rs).
/// `label` is the tab's to choose, so the page's first load, which can finish
/// before this returns, is already known to be its own.
#[tauri::command]
pub async fn browser_open(
    app: AppHandle,
    label: String,
    url: String,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    zoom: f64,
    project: Option<String>,
) -> Result<String, String> {
    let window = app.get_window("main").ok_or("The window is gone.")?;
    if !label.starts_with("browser-") || app.get_webview(&label).is_some() {
        return Err(format!("Not a label for a new page: {label}"));
    }
    let (tell, me) = (app.clone(), label.clone());
    let (own, mine) = (app.clone(), label.clone());
    let mut builder = WebviewBuilder::new(&label, WebviewUrl::External(web(&url)?))
        // Told that it is asked, rather than posting to a page around it.
        .initialization_script(format!("(function (BLUEPRINT_NATIVE) {{\n{AGENT}\n}})(true);"))
        .on_page_load(move |_, load| {
            let done = matches!(load.event(), PageLoadEvent::Finished);
            let _ = tell.emit_to("main", "blueprint:browser", json!({ "label": me, "url": load.url().as_str(), "done": done }));
        })
        // The preview is one page: what would open a window opens here.
        .on_new_window(move |url, _| {
            if let Some(view) = own.get_webview(&mine) {
                let _ = view.navigate(url);
            }
            NewWindowResponse::Deny
        });
    if let Some(root) = project {
        builder = builder.data_store_identifier(crate::signins::store_of(&root));
    }
    let view = window
        .add_child(builder, LogicalPosition::new(x, y), LogicalSize::new(width, height))
        .map_err(|e| e.to_string())?;
    let _ = view.set_zoom(zoom);
    #[cfg(target_os = "linux")]
    over_app(&view, x, y, width, height);
    Ok(label)
}

#[tauri::command]
pub async fn browser_place(app: AppHandle, label: String, x: f64, y: f64, width: f64, height: f64, zoom: f64, shown: bool) -> Result<(), String> {
    let view = app.get_webview(&label).ok_or(GONE)?;
    let bounds = Rect { position: LogicalPosition::new(x, y).into(), size: LogicalSize::new(width, height).into() };
    view.set_bounds(bounds).map_err(|e| e.to_string())?;
    #[cfg(target_os = "linux")]
    over_app(&view, x, y, width, height);
    view.set_zoom(zoom).map_err(|e| e.to_string())?;
    if shown { view.show() } else { view.hide() }.map_err(|e| e.to_string())
}

/// On Linux, Tauri packs a window's webviews one under another in a box,
/// where `set_bounds` cannot move them: a page would sit below the app,
/// taking half the window. So the app's own webview is put in an overlay
/// (`overlay_app`, as the window opens) and each page is laid over it there,
/// at `x`, `y` of the app's page, in logical pixels.
#[cfg(target_os = "linux")]
fn over_app(view: &tauri::Webview, x: f64, y: f64, width: f64, height: f64) {
    use gtk::prelude::*;
    let _ = view.with_webview(move |page| {
        let w: gtk::Widget = page.inner().upcast();
        let Some(parent) = w.parent() else { return };
        if parent.downcast_ref::<gtk::Overlay>().is_none() {
            // Still where Tauri packed it, in the window's box beside the overlay.
            let Some(container) = parent.downcast_ref::<gtk::Box>() else { return };
            let Some(overlay) = container.children().into_iter().find_map(|c| c.downcast::<gtk::Overlay>().ok()) else {
                return;
            };
            container.remove(&w);
            w.set_halign(gtk::Align::Start);
            w.set_valign(gtk::Align::Start);
            overlay.add_overlay(&w);
        }
        // Margins cannot be negative: a page partly out of sight is hidden (webview.ts).
        w.set_margin_start(x.max(0.0).round() as i32);
        w.set_margin_top(y.max(0.0).round() as i32);
        w.set_size_request(width.max(1.0).round() as i32, height.max(1.0).round() as i32);
    });
}

/// The app's webview, moved from the window's box into an overlay in its
/// place, for pages from the web to be laid over (`over_app`).
#[cfg(target_os = "linux")]
pub fn overlay_app(window: &tauri::WebviewWindow) {
    use gtk::prelude::*;
    let _ = window.with_webview(|app_view| {
        let view: gtk::Widget = app_view.inner().upcast();
        let Some(container) = view.parent().and_then(|p| p.downcast::<gtk::Box>().ok()) else {
            return;
        };
        let at = container.child_position(&view);
        let overlay = gtk::Overlay::new();
        container.remove(&view);
        overlay.add(&view);
        container.pack_start(&overlay, true, true, 0);
        container.reorder_child(&overlay, at);
        overlay.show();
        view.grab_focus();
    });
}

#[tauri::command]
pub async fn browser_go(app: AppHandle, label: String, url: String) -> Result<(), String> {
    app.get_webview(&label).ok_or(GONE)?.navigate(web(&url)?).map_err(|e| e.to_string())
}

/// Runs `js` in the page and returns its value. The tab's agent calls go
/// through this, and so does collecting what the page has said since.
#[tauri::command]
pub async fn browser_eval(app: AppHandle, label: String, js: String) -> Result<Value, String> {
    let view = app.get_webview(&label).ok_or(GONE)?;
    let (tx, rx) = mpsc::channel();
    view.eval_with_callback(js, move |out| {
        let _ = tx.send(out);
    })
    .map_err(|e| e.to_string())?;
    let out = rx.recv_timeout(Duration::from_secs(5)).map_err(|_| "The page did not answer.".to_string())?;
    Ok(serde_json::from_str(&out).unwrap_or(Value::Null))
}

/// A picture of the page, as a PNG data address: the tab shows it in the
/// page's place while a menu or dialog of the app's is over it, as the
/// webview, drawn above the app, would otherwise cover that.
#[tauri::command]
pub async fn browser_picture(app: AppHandle, label: String) -> Result<String, String> {
    let view = app.get_webview(&label).ok_or(GONE)?;
    let (tx, rx) = mpsc::channel::<Option<Vec<u8>>>();
    view.with_webview(move |w| picture(w, tx)).map_err(|e| e.to_string())?;
    let png = rx.recv_timeout(Duration::from_secs(5)).ok().flatten().ok_or("The page gave no picture.")?;
    Ok(format!("data:image/png;base64,{}", crate::mcp::base64(&png)))
}

#[cfg(windows)]
fn picture(w: tauri::webview::PlatformWebview, tx: mpsc::Sender<Option<Vec<u8>>>) {
    use webview2_com::CapturePreviewCompletedHandler;
    use webview2_com::Microsoft::Web::WebView2::Win32::COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG;
    use windows::Win32::Foundation::HGLOBAL;
    use windows::Win32::System::Com::StructuredStorage::{CreateStreamOnHGlobal, GetHGlobalFromStream};
    use windows::Win32::System::Com::{IStream, STATFLAG_NONAME, STATSTG};
    use windows::Win32::System::Memory::{GlobalLock, GlobalUnlock};

    fn bytes(stream: &IStream) -> Option<Vec<u8>> {
        unsafe {
            let mut stat = STATSTG::default();
            stream.Stat(&mut stat, STATFLAG_NONAME).ok()?;
            let global = GetHGlobalFromStream(stream).ok()?;
            let at = GlobalLock(global) as *const u8;
            if at.is_null() {
                return None;
            }
            let png = std::slice::from_raw_parts(at, stat.cbSize as usize).to_vec();
            let _ = GlobalUnlock(global);
            Some(png)
        }
    }

    let done = tx.clone();
    let started = (|| unsafe {
        let core = w.controller().CoreWebView2()?;
        let stream = CreateStreamOnHGlobal(HGLOBAL::default(), true)?;
        let out = stream.clone();
        let handler = CapturePreviewCompletedHandler::create(Box::new(move |result| {
            let _ = done.send(result.ok().and_then(|_| bytes(&out)));
            Ok(())
        }));
        core.CapturePreview(COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG, &stream, &handler)
    })();
    if started.is_err() {
        let _ = tx.send(None);
    }
}

#[cfg(target_os = "macos")]
fn picture(w: tauri::webview::PlatformWebview, tx: mpsc::Sender<Option<Vec<u8>>>) {
    use objc2_app_kit::{NSBitmapImageFileType, NSBitmapImageRep, NSImage};
    use objc2_foundation::{NSDictionary, NSError};
    use objc2_web_kit::{WKSnapshotConfiguration, WKWebView};

    unsafe {
        let view = &*(w.inner() as *const WKWebView);
        let config = WKSnapshotConfiguration::new(objc2::MainThreadMarker::new_unchecked());
        let done = block2::RcBlock::new(move |image: *mut NSImage, _: *mut NSError| {
            let png = image.as_ref().and_then(|image| {
                let tiff = image.TIFFRepresentation()?;
                let rep = NSBitmapImageRep::imageRepWithData(&tiff)?;
                let png = rep.representationUsingType_properties(NSBitmapImageFileType::PNG, &NSDictionary::new())?;
                Some(png.to_vec())
            });
            let _ = tx.send(png);
        });
        view.takeSnapshotWithConfiguration_completionHandler(Some(&config), &done);
    }
}

#[cfg(not(any(windows, target_os = "macos")))]
fn picture(_: tauri::webview::PlatformWebview, tx: mpsc::Sender<Option<Vec<u8>>>) {
    let _ = tx.send(None);
}

#[tauri::command]
pub async fn browser_close(app: AppHandle, label: String) {
    if let Some(view) = app.get_webview(&label) {
        let _ = view.close();
    }
}

/// One thing a person does with a mouse or keyboard. `x` and `y` are points
/// from the top left of the webview it is done in.
#[derive(Deserialize)]
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
pub struct Act {
    kind: String,
    #[serde(default)]
    x: f64,
    #[serde(default)]
    y: f64,
    /// 0 the left button, 2 the right.
    #[serde(default)]
    button: u8,
    #[serde(default = "one")]
    clicks: isize,
    /// A key with its modifiers for `key` ("Enter", "cmd+a"), the characters for `text`.
    #[serde(default)]
    text: String,
}

fn one() -> isize {
    1
}

/// Does `acts` in a preview's webview, by its label. With `back`, the
/// keyboard is given back to whatever had it, so Claude's clicks never take
/// it from the user. Whether the window was active: WebKit follows a hover
/// only in one that is.
#[tauri::command]
pub async fn native_input(app: AppHandle, view: String, back: bool, acts: Vec<Act>) -> Result<bool, String> {
    #[cfg(target_os = "macos")]
    {
        let (tx, rx) = mpsc::channel();
        let run = move |w: tauri::webview::PlatformWebview| {
            // On the main thread: Tauri's promise for with_webview.
            let _ = tx.send(unsafe { macos::send(&*(w.inner() as *const objc2_app_kit::NSView), &acts, back) });
        };
        let target = app.get_webview(&view).ok_or(GONE)?;
        target.with_webview(run).map_err(|e| e.to_string())?;
        rx.recv_timeout(Duration::from_secs(5)).map_err(|_| "The input was not taken.".to_string())?
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = (app, view, back, acts);
        Err("native input is macOS only".into())
    }
}

#[cfg(target_os = "macos")]
mod macos {
    use super::{code_of, Act};
    use objc2::runtime::NSObjectProtocol;
    use objc2::{msg_send, sel, MainThreadMarker};
    use objc2_app_kit::{NSApplication, NSEvent, NSEventModifierFlags, NSEventType, NSView};
    use objc2_foundation::{NSPoint, NSProcessInfo, NSString};

    pub fn send(view: &NSView, acts: &[Act], back: bool) -> Result<bool, String> {
        let window = view.window().ok_or("The preview is not in a window.")?;
        // A press or a key takes the keyboard, as a person's click would; a hover does not.
        let takes = acts.iter().any(|a| a.kind != "move");
        let had = window.firstResponder();
        if takes {
            window.makeFirstResponder(Some(view));
        }
        let done = deliver(view, &window, acts);
        // Given back in this same turn of the main thread, so no key the user
        // presses can land in the page in between.
        if takes && back {
            window.makeFirstResponder(had.as_deref());
        }
        done?;
        Ok(window.isKeyWindow())
    }

    fn deliver(view: &NSView, window: &objc2_app_kit::NSWindow, acts: &[Act]) -> Result<(), String> {
        let number = window.windowNumber();
        let start = NSProcessInfo::processInfo().systemUptime();
        let (flipped, height) = (view.isFlipped(), view.bounds().size.height);
        let at = |x: f64, y: f64| view.convertPoint_toView(NSPoint::new(x, if flipped { y } else { height - y }), None);
        for (i, a) in acts.iter().enumerate() {
            let time = start + i as f64 * 0.001;
            match a.kind.as_str() {
                "move" | "down" | "up" | "drag" => {
                    let right = a.button == 2;
                    let kind = match a.kind.as_str() {
                        "move" => NSEventType::MouseMoved,
                        "drag" => NSEventType::LeftMouseDragged,
                        "down" if right => NSEventType::RightMouseDown,
                        "down" => NSEventType::LeftMouseDown,
                        _ if right => NSEventType::RightMouseUp,
                        _ => NSEventType::LeftMouseUp,
                    };
                    let pressure = if matches!(a.kind.as_str(), "down" | "drag") { 1.0 } else { 0.0 };
                    let event = NSEvent::mouseEventWithType_location_modifierFlags_timestamp_windowNumber_context_eventNumber_clickCount_pressure(
                        kind,
                        at(a.x, a.y),
                        NSEventModifierFlags::empty(),
                        time,
                        number,
                        None,
                        0,
                        a.clicks,
                        pressure,
                    )
                    .ok_or("AppKit made no mouse event.")?;
                    match kind {
                        // WKWebView has no mouseMoved: of its own (its tracking
                        // area takes moves), so a hover is given the way WebKit's
                        // tests give one: it reaches the page with the window in
                        // the back too.
                        NSEventType::MouseMoved if view.respondsToSelector(sel!(_simulateMouseMove:)) => unsafe {
                            let _: () = msg_send![view, _simulateMouseMove: &*event];
                        },
                        NSEventType::MouseMoved => window.sendEvent(&event),
                        NSEventType::LeftMouseDragged => view.mouseDragged(&event),
                        NSEventType::LeftMouseDown => view.mouseDown(&event),
                        NSEventType::RightMouseDown => view.rightMouseDown(&event),
                        NSEventType::RightMouseUp => view.rightMouseUp(&event),
                        _ => view.mouseUp(&event),
                    }
                }
                "key" => {
                    let (code, chars, flags) = combo(&a.text).ok_or_else(|| format!("Not a key: {}", a.text))?;
                    key(view, number, time, code, &chars, flags)?;
                }
                "text" => {
                    for c in a.text.chars() {
                        let (code, chars) = if c == '\n' { (36, "\r".to_string()) } else { (code_of(c), c.to_string()) };
                        key(view, number, time, code, &chars, NSEventModifierFlags::empty())?;
                    }
                }
                other => return Err(format!("Unknown input: {other}")),
            }
        }
        Ok(())
    }

    fn key(view: &NSView, number: isize, time: f64, code: u16, chars: &str, flags: NSEventModifierFlags) -> Result<(), String> {
        let chars = NSString::from_str(chars);
        let event = |kind| {
            NSEvent::keyEventWithType_location_modifierFlags_timestamp_windowNumber_context_characters_charactersIgnoringModifiers_isARepeat_keyCode(
                kind,
                NSPoint::new(0.0, 0.0),
                flags,
                time,
                number,
                None,
                &chars,
                &chars,
                false,
                code,
            )
            .ok_or("AppKit made no key event.")
        };
        let down = event(NSEventType::KeyDown)?;
        view.keyDown(&down);
        // The page hears a shortcut, but the edit it stands for is the Edit
        // menu's, which acts only in the key window: done here instead, so it
        // works with the app behind others.
        if flags.contains(NSEventModifierFlags::Command) {
            let edit = match (chars.to_string().to_ascii_lowercase().as_str(), flags.contains(NSEventModifierFlags::Shift)) {
                ("a", _) => Some(sel!(selectAll:)),
                ("c", _) => Some(sel!(copy:)),
                ("x", _) => Some(sel!(cut:)),
                ("v", _) => Some(sel!(paste:)),
                ("z", false) => Some(sel!(undo:)),
                ("z", true) => Some(sel!(redo:)),
                _ => None,
            };
            if let Some(edit) = edit {
                // send() runs on the main thread (native_input).
                let app = NSApplication::sharedApplication(unsafe { MainThreadMarker::new_unchecked() });
                unsafe { app.sendAction_to_from(edit, Some(view), None) };
            }
        }
        let up = event(NSEventType::KeyUp)?;
        view.keyUp(&up);
        Ok(())
    }

    /// "Enter", "a", "shift+Tab", "cmd+a": the key code, its characters and the modifiers.
    fn combo(text: &str) -> Option<(u16, String, NSEventModifierFlags)> {
        let mut parts: Vec<&str> = text.split('+').collect();
        let name = parts.pop()?;
        let mut flags = NSEventModifierFlags::empty();
        for m in parts {
            flags |= match m.to_ascii_lowercase().as_str() {
                "ctrl" | "control" => NSEventModifierFlags::Control,
                "shift" => NSEventModifierFlags::Shift,
                "alt" | "option" => NSEventModifierFlags::Option,
                "cmd" | "command" | "meta" | "super" => NSEventModifierFlags::Command,
                _ => return None,
            };
        }
        let (code, chars) = super::key_of(name)?;
        Some((code, chars, flags))
    }
}

/// The key code and characters AppKit gives a key, by its name or its character.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
fn key_of(name: &str) -> Option<(u16, String)> {
    let named = match name.to_ascii_lowercase().as_str() {
        "enter" | "return" => Some((36, "\r")),
        "tab" => Some((48, "\t")),
        "escape" | "esc" => Some((53, "\u{1b}")),
        "backspace" => Some((51, "\u{7f}")),
        "delete" => Some((117, "\u{f728}")),
        "space" => Some((49, " ")),
        "up" | "arrowup" => Some((126, "\u{f700}")),
        "down" | "arrowdown" => Some((125, "\u{f701}")),
        "left" | "arrowleft" => Some((123, "\u{f702}")),
        "right" | "arrowright" => Some((124, "\u{f703}")),
        "home" => Some((115, "\u{f729}")),
        "end" => Some((119, "\u{f72b}")),
        "pageup" => Some((116, "\u{f72c}")),
        "pagedown" => Some((121, "\u{f72d}")),
        _ => None,
    };
    if let Some((code, chars)) = named {
        return Some((code, chars.into()));
    }
    let mut it = name.chars();
    let c = it.next()?;
    it.next().is_none().then(|| (code_of(c), c.to_string()))
}

/// The key a character is on, on a US keyboard, by its position in this
/// string; 0 for one it has no key of its own for, which pages rarely read.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
fn code_of(c: char) -> u16 {
    const KEYS: &str = "asdfhgzxcv\0bqweryt123465=97-80]ou[ip\rlj'k;\\,/nm.\t `";
    KEYS.chars().position(|k| k == c.to_ascii_lowercase()).map_or(0, |i| i as u16)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keys_have_their_macos_codes() {
        assert_eq!(key_of("Enter"), Some((36, "\r".into())));
        assert_eq!(key_of("a").map(|k| k.0), Some(0));
        assert_eq!(key_of("B").map(|k| k.0), Some(11));
        assert_eq!(key_of("m").map(|k| k.0), Some(46));
        assert_eq!(key_of("0").map(|k| k.0), Some(29));
        assert_eq!(key_of("`").map(|k| k.0), Some(50));
        assert_eq!(key_of("ArrowUp").map(|k| k.0), Some(126));
        assert_eq!(key_of("nope"), None);
    }

    #[test]
    fn only_web_pages_open() {
        assert!(web("https://example.com/a?b").is_ok());
        assert!(web("file:///etc/passwd").is_err());
        assert!(web("javascript:alert(1)").is_err());
    }
}

app/src-tauri/src/claude.rs:
//! Claude Code in the workspace's tabs. Every tab is the user's shell on a
//! pty (pty.rs); a new one starts their own `claude` in it first, so it looks
//! and behaves exactly as it does in their terminal, and quitting Claude leaves
//! the shell behind. What this module adds is finding that binary, and the
//! launcher that lets the blueprint hand it context.
//!
//! The launcher is a small script, `blueprint-claude`, on each tab's PATH. It runs
//! the user's `claude` with `--settings` carrying a `UserPromptSubmit` hook,
//! and while it runs it keeps a `.live` marker beside the tab's queue: that is
//! how the UI knows Claude is in front in a tab, and able to take context.
//! `--settings` adds to the user's own settings, so their login, hooks, MCP
//! servers, theme and status line all still apply.
//!
//! The hand-off is a file. Each tab has its own queue under the temp dir,
//! named in `$BLUEPRINT_CONTEXT`. Picking on the blueprint appends a block to it —
//! `[Blueprint section: …]` for a whole section, `[Blueprint element: …]` for one thing on
//! a level — and the hook drains it on the next prompt: whatever a prompt hook
//! prints is added to that prompt's context. The file being gone is how the
//! UI knows a pick was delivered (components/agent/workspace.tsx shows it).

use portable_pty::CommandBuilder;
use std::io::Write;
use std::path::{Path, PathBuf};

/// Every prompt first says where the user is on the blueprint (`.where`, kept by the
/// app as they move; see `place`): its first line always, so "what am I
/// reading?" has an answer, and the section itself only when it has changed
/// since the last prompt, so one page read for a while is not sent each turn.
/// Then it drains the queue: the `mv` is atomic, so a pick appended while
/// Claude reads lands in a fresh file for the next prompt rather than being lost.
pub const HOOK: &str = r#"f="$BLUEPRINT_CONTEXT"; w="$f.where"; if [ -s "$w" ]; then head -n 1 "$w"; cmp -s "$w" "$w.sent" || { tail -n +2 "$w"; cp "$w" "$w.sent"; }; fi; [ -s "$f" ] || exit 0; mv "$f" "$f.sent" && cat "$f.sent""#;

/// The scripts beside the launcher, on the PATH of Claude's Bash tool. The
/// tab's PATH has them, but Claude Code builds its Bash tool's environment
/// from a shell of its own, which on Windows drops them; what a session-start
/// hook writes to `$CLAUDE_ENV_FILE` is what every command there starts with.
const ON_PATH: &str = r#"[ -n "$CLAUDE_ENV_FILE" ] && [ -n "$BLUEPRINT_BIN" ] || exit 0; d="$BLUEPRINT_BIN"; command -v cygpath >/dev/null 2>&1 && d=$(cygpath -u "$d"); printf 'export PATH="%s:$PATH"\n' "$d" >> "$CLAUDE_ENV_FILE""#;

/// Blueprint credit is for Claude alone (`credit`), and Claude's Bash tool would hand it to every
/// command it runs, the user's own app among them: each of those starts with it unset.
const NO_CREDIT: &str = r#"[ -n "$CLAUDE_ENV_FILE" ] && [ -f "$BLUEPRINT_CONTEXT.credit" ] || exit 0; sed -n 's/^export \([A-Z0-9_]*\)=.*/unset \1/p' "$BLUEPRINT_CONTEXT.credit" >> "$CLAUDE_ENV_FILE""#;

/// The conversation Claude is having in this tab, from the hook's input, so
/// the app can resume it in the tab it reopens after a restart. A `/clear`
/// starts a new one, and this follows it.
const SESSION: &str = r#"id=$(sed -n 's/.*"session_id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1); [ -n "$id" ] && printf '%s\n' "$id" > "$BLUEPRINT_CONTEXT.session"; exit 0"#;

/// After a tool that can change files: this turn may have edited code.
const EDITED: &str = r#": > "$BLUEPRINT_CONTEXT.dirty""#;
/// The tools EDITED follows. Bash among them, since a shell command can edit too.
const EDITING_TOOLS: &str = "Edit|Write|MultiEdit|NotebookEdit|Bash";

/// A plan Claude asks to start on: the hook's input, which carries the plan's
/// Markdown, kept whole for the app to draw (components/agent/plan.tsx). Renamed
/// into place, so a plan is never read half written. A new plan ends the last
/// one's checklist, before the app can draw the new one with its ticks, and
/// its file waits (`.pending`) to become the checklist's once accepted.
const PLAN: &str = r#"f="$BLUEPRINT_CONTEXT"; rm -f "$f.steps" "$f.accepted"; cat > "$f.plan.part" && sed -n 's/.*"planFilePath": *"\([^"]*\)".*/\1/p' "$f.plan.part" | head -n 1 > "$f.pending" && mv "$f.plan.part" "$f.plan""#;
/// ExitPlanMode only runs once the user has accepted the plan, in the terminal
/// or from the plan's own tab.
const APPROVED: &str = r#": > "$BLUEPRINT_CONTEXT.approved""#;

/// On a long build Claude loses its place, and the to-do tool it would keep a
/// list in is off for the newer models (Claude Code turns it on only for older
/// ones). So the plan's own Steps are the list: Claude marks them with
/// `blueprint-plan-step` (STEP), the plan's tab shows them ticked off (`steps_of`),
/// and the hooks below hold Claude to them. A macro, to be `concat!`ed into
/// each hook that says it; no quotes in it, since it goes out inside JSON.
macro_rules! checklist {
    () => {
        "Its Steps are your checklist, ticked off in the plan tab the user watches: run `blueprint-plan-step <n> doing` as you start a step and `blueprint-plan-step <n> done` as soon as it is finished, in order. A step that turns out wrong or unneeded is `blueprint-plan-step <n> skipped <why>`, and you tell the user why. Work the plan missed goes in the step it belongs to. Do not end the build with a step unmarked, and finish with the checks under Check."
    };
}
/// Said to Claude as the accepted plan comes back to it.
const TODOS: &str = concat!(
    r#"f="$BLUEPRINT_CONTEXT"; [ -s "$f.pending" ] && mv "$f.pending" "$f.accepted"; printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"The plan is accepted. "#,
    checklist!(),
    r#" Run `blueprint-plan-step 1 doing` before you change any file."}}'"#
);
/// A plan accepted with "Yes, clear context" never finishes its ExitPlanMode:
/// Claude Code denies the call, clears the conversation and starts a new one
/// with the plan as its first message. So a clear with a plan still waiting
/// may be that, or a `/clear` after the plan was turned down; Claude is told
/// which way to read it, and nothing holds it to the steps (UNFINISHED,
/// REMIND) until it marks one.
const CLEARED: &str = concat!(
    r#"f="$BLUEPRINT_CONTEXT"; [ -s "$f.pending" ] || exit 0; p=$(cat "$f.pending"); mv "$f.pending" "$f.accepted"; [ -f "$p" ] || exit 0; printf '%s\n\n' 'If the first message asks you to implement the plan below, the user accepted it. "#,
    checklist!(),
    r#" Run `blueprint-plan-step 1 doing` before you change any file. The plan:'; cat "$p"; exit 0"#
);
/// Compacting summarizes the plan away mid-build; it is said again, whole,
/// with what is marked so far.
const REMIND: &str = concat!(
    r#"f="$BLUEPRINT_CONTEXT"; p=$(cat "$f.accepted" 2>/dev/null); [ -s "$f.steps" ] && [ -f "$p" ] || exit 0; printf '%s\n\n' 'The conversation was compacted while you were building the plan below, which the user accepted: pick up from the first step not marked done. "#,
    checklist!(),
    r#" The plan:'; cat "$p"; printf '\n\nMarked so far (step, state, note):\n'; cat "$f.steps"; exit 0"#
);
/// A new Claude in the tab is not building the last one's plan.
const FRESH: &str = r#"rm -f "$BLUEPRINT_CONTEXT.accepted" "$BLUEPRINT_CONTEXT.pending""#;
/// At the end of a turn, steps of the accepted plan still unmarked keep Claude
/// going: exit 2 hands it the reason instead of stopping. Once per turn, since
/// Claude Code says when a stop is already one this sent back, so a Claude
/// waiting on the user can still stop. Writes the tab's `done` itself, so a
/// turn sent back never shows as finished. All marked, the plan is let go.
const UNFINISHED: &str = r#"f="$BLUEPRINT_CONTEXT"; p=$(cat "$f.accepted" 2>/dev/null); if [ -s "$f.steps" ] && [ -f "$p" ] && ! grep -q '"stop_hook_active": *true'; then left=$(M="$f.steps" awk 'BEGIN { m = ENVIRON["M"]; while ((getline l < m) > 0) { split(l, a, "\t"); s[a[1]] = a[2] } } /^##[ \t]/ { on = tolower($0) ~ /step/; next } on && /^[0-9]+[.)][ \t]/ { n = $0 + 0; if (s[n] != "done" && s[n] != "skipped") o = o (o == "" ? "" : ", ") n } END { print o }' "$p"); if [ -n "$left" ]; then printf 'Steps of the plan the user accepted not marked done yet: %s. Finish them now, in order, marking each with blueprint-plan-step. One already finished: mark it done. One no longer wanted, or that cannot be done: `blueprint-plan-step <n> skipped <why>`, and tell the user. If you are waiting on the user, say what you need and stop.\n' "$left" >&2; exit 2; fi; rm -f "$f.accepted"; fi; printf done > "$f.status""#;

/// Claude Code's own dialog shows the plan as its file reads once the hooks
/// have run, and the plan's tab is where it is read: its diagrams are JSON in
/// a terminal. So while the dialog is up the file is only the plan's title and
/// OPEN_PLAN, which the terminal makes a link that opens (or reopens) the
/// plan's tab (components/agent/shell.tsx); it stays in the scrollback, so a closed
/// plan can be found again. The whole plan waits beside the queue (`.hidden`)
/// for RESTORE.
const HIDE: &str = r#"h="$BLUEPRINT_CONTEXT.hidden"; p=$(sed -n 's/.*"planFilePath": *"\([^"]*\)".*/\1/p' | head -n 1); [ -f "$p" ] || exit 0; awk '/^# / && !t { print; print ""; t = 1 } END { print "`▸ Open plan`" }' "$p" > "$h.shown" && ! cmp -s "$p" "$h.shown" && cp "$p" "$h" && printf '%s' "$p" > "$h.file" && cp "$h.shown" "$p"; exit 0"#;
/// The whole plan back in its file, at the first hook after the dialog is
/// answered, accepted or not, so a revision starts from it. Unless the file
/// changed meanwhile (the user edited it with ctrl+g): then it is theirs.
const RESTORE: &str = r#"h="$BLUEPRINT_CONTEXT.hidden"; [ -e "$h.file" ] || exit 0; p=$(cat "$h.file"); cmp -s "$p" "$h.shown" && cp "$h" "$p"; rm -f "$h" "$h.file" "$h.shown"; exit 0"#;

/// Refuses a Bash call that would start a browser of its own: gstack's shared
/// Chromium (`$B`, browse/dist/browse, which its /browse, /qa, /scrape and
/// design skills drive), or Chrome itself. Exit 2 hands the reason to Claude.
const NO_BROWSER: &str = r#"grep -qE 'browse/dist/browse|\$B [a-z]|Google Chrome|chrome --headless' || exit 0; echo 'Browsing happens in the Preview here (the blueprint-preview tools), never a headless Chromium or Chrome. Do this step with navigate, computer and get_page_text instead.' >&2; exit 2"#;

/// Plan mode still prompts for these despite the allow rules in `prepare`; a
/// hook's allow skips that prompt and still loses to the deny rules.
const PLAN_READS: &str = r#"grep -qE '"permission_mode": *"plan"' || exit 0; echo '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"allow"}}'"#;

/// What Claude is doing, for the dot on its tab: each hook below writes one
/// word, `working`, `waiting` (a question or a permission only the user can
/// answer) or `done`.
fn status(word: &str) -> serde_json::Value {
    serde_json::json!({ "type": "command", "command": format!(r#"printf {word} > "$BLUEPRINT_CONTEXT.status""#) })
}

/// At the end of a turn, `.turn` is written when the turn may have edited code or
/// found the blueprint wrong (blueprint-fix), and is what makes the blueprint
/// follow the agent.
const TURN: &str = r#"f="$BLUEPRINT_CONTEXT"; s=$(cat); [ -e "$f.dirty" ] || [ -s "$f.fix" ] || exit 0; rm -f "$f.dirty"; printf '%s' "$s" > "$f.turn.part" && mv "$f.turn.part" "$f.turn"; exit 0"#;

/// What Claude runs when it finds the blueprint wrong: one line per section, kept
/// beside the tab's queue until the turn ends. Allowed without asking.
const FIX: &str = r#"#!/bin/sh
# Tells Blueprint the blueprint is wrong about a section (src-tauri/src/claude.rs).
[ -n "$BLUEPRINT_CONTEXT" ] || { echo "Not in a Blueprint tab; nothing to correct." >&2; exit 1; }
[ $# -ge 2 ] || { echo 'usage: blueprint-fix "<section title>" "<what the blueprint gets wrong, and what is true>"' >&2; exit 2; }
printf '%s\t%s\n' "$(printf '%s' "$1" | tr '\t\n' '  ')" "$(printf '%s' "$2" | tr '\t\n' '  ')" >> "$BLUEPRINT_CONTEXT.fix"
echo "Noted. The blueprint's \"$1\" will be corrected after this turn."
"#;

/// What Claude runs to put the user in front of what it is talking about: one
/// line per act, taken by the app on its next poll rather than at the end of
/// the turn. Refs are written as the user said them and resolved by the app.
/// Allowed without asking.
const SHOW: &str = r#"#!/bin/sh
# Drives the open blueprint: shows a section, a diff, or the history (src-tauri/src/claude.rs).
[ -n "$BLUEPRINT_CONTEXT" ] || { echo "Not in a Blueprint tab; nothing to show." >&2; exit 1; }
clean() { printf '%s' "$1" | tr '\t\n' '  '; }
case "$1" in
section)
  [ -n "$2" ] || { echo 'usage: blueprint-show section "<section title or id>"' >&2; exit 2; }
  printf 'section\t%s\t\n' "$(clean "$2")" >> "$BLUEPRINT_CONTEXT.act"
  echo "Showing \"$2\" on the blueprint."
  ;;
diff)
  [ $# -ge 2 ] || { echo 'usage: blueprint-show diff "<from>" ["<to>"]' >&2; exit 2; }
  printf 'diff\t%s\t%s\n' "$(clean "$2")" "$(clean "$3")" >> "$BLUEPRINT_CONTEXT.act"
  echo "Showing the diff${2:+ from \"$2\"}${3:+ to \"$3\"} on the blueprint."
  ;;
timeline)
  printf 'timeline\t\t\n' >> "$BLUEPRINT_CONTEXT.act"
  echo "Showing the history of the code over the blueprint."
  ;;
file)
  [ -n "$2" ] || { echo 'usage: blueprint-show file "<path>" [<line>]' >&2; exit 2; }
  case "$2" in /*) p=$2 ;; *) p="$PWD/$2" ;; esac
  [ -f "$p" ] || { echo "No file at $p." >&2; exit 1; }
  case "$3" in ''|*[!0-9]*) n= ;; *) n=$3 ;; esac
  printf 'file\t%s\t%s\n' "$(clean "$p")" "$n" >> "$BLUEPRINT_CONTEXT.act"
  echo "Opening $p in Blueprint."
  ;;
*)
  echo 'usage: blueprint-show section "<section title or id>" | blueprint-show diff "<from>" ["<to>"] | blueprint-show timeline | blueprint-show file "<path>" [<line>]' >&2
  exit 2
  ;;
esac
"#;

/// A terminal's output, for any agent in a tab: Claude has `read_terminal`
/// (mcp.rs), and this reaches the same tool for the agents that have no MCP
/// config. Allowed without asking.
const TERMINAL: &str = r#"#!/bin/sh
# Prints what a Blueprint terminal printed, the dev server's by default (src-tauri/src/mcp.rs).
[ -n "$BLUEPRINT_MCP_URL" ] || { echo "Not in a Blueprint tab; no terminals to read." >&2; exit 1; }
case "$2" in ''|*[!0-9]*) lines=200 ;; *) lines=$2 ;; esac
name=$(printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g' | tr '\t\n' '  ')
curl -sS --fail-with-body "$BLUEPRINT_MCP_URL/text" -H 'Content-Type: application/json' \
  -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"read_terminal\",\"arguments\":{\"name\":\"$name\",\"lines\":$lines}}}"
"#;

/// The blueprint's own table of contents, for naming a section that was not picked.
///
/// The user asks "how do sign ups work?" with nothing attached, so the only
/// section names in context are whatever they happened to pick earlier —
/// usually none. Without this, `blueprint-show section` would be a guess at a
/// title that may not exist, which is how a reader ends up somewhere they did
/// not ask to be. The outline is written beside the tab's queue when the tab
/// starts (pty.rs), from the blueprint the page already has.
const LIST: &str = r#"#!/bin/sh
# Lists the open blueprint, section by section (src-tauri/src/claude.rs).
[ -n "$BLUEPRINT_CONTEXT" ] || { echo "Not in a Blueprint tab; no blueprint to list." >&2; exit 1; }
[ -s "$BLUEPRINT_CONTEXT.blueprint" ] || { echo "This repository has no blueprint yet." >&2; exit 1; }
cat "$BLUEPRINT_CONTEXT.blueprint"
"#;

/// What Claude runs to mark a step of the plan it is building (`checklist!`):
/// one line per mark, the latest for a step standing (`steps_of`). Allowed
/// without asking.
const STEP: &str = r#"#!/bin/sh
# Marks a step of the accepted plan, for its tab in Blueprint (src-tauri/src/claude.rs).
[ -n "$BLUEPRINT_CONTEXT" ] || { echo "Not in a Blueprint tab; no plan to mark." >&2; exit 1; }
usage='usage: blueprint-plan-step <step number> doing|done|skipped ["why"]'
case "$1" in ''|*[!0-9]*) echo "$usage" >&2; exit 2 ;; esac
case "$2" in doing|done|skipped) ;; *) echo "$usage" >&2; exit 2 ;; esac
n=$1 state=$2
shift 2
printf '%s\t%s\t%s\n' "$n" "$state" "$(printf '%s' "$*" | tr '\t\n' '  ')" >> "$BLUEPRINT_CONTEXT.steps"
echo "Step $n: $state."
"#;

/// What every agent in a tab is told about the blueprint: how picks arrive, where the
/// user is, `blueprint-fix`, `blueprint-show`, the blueprint's tools and the preview.
/// A macro, so SYSTEM and AGENT_SYSTEM are one text each.
macro_rules! blueprint_system {
    () => {
        "This session was opened from Blueprint, an app that blueprints this \
repository as a tree of sections (user journey, data flow, the code behind each). The user \
can attach things they picked on the blueprint: a whole section arrives as a block starting with \
`[Blueprint section:`, one element of a section (a row, a diagram box, a step, a line of code) as \
one starting with `[Blueprint element:`. Each names where it sits on the blueprint, what it says, and \
the code behind it. Treat what is attached as what the user is asking about, and read the \
listed code when it is relevant. Each prompt also opens with a `[Reading now:` line naming \
the section the user has open, followed by that section when it has changed since the last \
prompt. When they ask what they are reading, or say \"this\" or \"here\" with nothing \
attached, they mean that section: summarize or answer from it and the code it lists. It is \
told to you, not shown to them, so never mention having been told where they are. Do not edit files unless asked. The blueprint can be wrong: when \
you find that it is (a listed problem that is not real, a description or a line reference \
that does not match the code), run `blueprint-fix \"<section title>\" \"<what it gets wrong, \
and what is true>\"` once per section, and the blueprint is corrected after your turn. Code you \
change updates the blueprint by itself once it is committed, deletions included; there is no need to report edits. \
You also drive what the user is looking at. When they ask how something works and nothing \
is attached, run `blueprint-list` to see what the blueprint actually calls its sections, then, if \
one of them is what they are asking about, run `blueprint-show section \"<section title>\"` \
before you explain, naming it exactly as the outline spells it, so \
they are looking at the thing you are explaining as you explain it; the app takes it \
immediately, not at the end of your turn. When they ask to see what changed, run \
`blueprint-show diff \"<from>\" \"<to>\"` — `<to>` may be left off, meaning the working tree, \
and an empty `<from>` means the commit the blueprint was built from. Pass the refs through as the \
user said them, `HEAD~1`, a sha, a branch, or a phrase like \"last commit by hindra2\": the \
app resolves them against the repository, so do not run git to work one out first. When they \
ask how the code got here or how it changed over time, run `blueprint-show timeline`: it draws \
every commit on the blueprint's sections, and they can click through it while you tell the history. \
To put a file in front of them, such as a Markdown doc you wrote, a config or a log, run \
`blueprint-show file \"<path>\"` (a line number may follow): it opens in Blueprint's editor beside you, \
and Markdown is drawn as the page it makes, with headings, tables, code, quotes and task lists. That is \
how to preview Markdown here, so never render it to HTML or open a file in the preview or a browser. \
The `blueprint_search`, `blueprint_section` and `blueprint_where` tools read the blueprint itself. Before you change a \
file, ask `blueprint_where` which sections explain it, so the change fits the part of the product it \
lives in and the user can follow what you are building on the blueprint. \
Keeping the blueprint right is background upkeep, not part of the answer: never tell the user \
whether you edited files, whether the blueprint is accurate, or that there is nothing to correct, \
and mention a correction only in passing when you ran blueprint-fix. What you show is \
likewise not worth narrating — the user can see it, so never announce that you are taking \
them somewhere, though naming the section you are explaining is fine where the prose wants \
it. The app also runs the project: its web app in Preview tabs (often several at once, \
one per page or site, each numbered; the tools' replies list them), and its phone app on an iOS \
Simulator or Android emulator when the user has started one. The blueprint-preview tools use them \
as a person would (screenshot, click, type, read the page, navigate, resize); use them to check \
that a change you made works, or when the user asks about what the app shows; `read_terminal` \
reads the dev server's logs (and the project's other terminals) when something fails. They are also \
your browser: to search the web or read a page as the user would see it, navigate the preview \
there, never another browser: not Chrome, not a headless Chromium. When a skill says to \
drive its own browser (gstack's `$B`), do those steps with the blueprint-preview tools instead. WebSearch and WebFetch are fine for reading docs as text; they \
stay out of the preview. "
    };
}

const SYSTEM: &str = concat!(
    blueprint_system!(),
    "A plan you finish in plan mode opens beside you as a short design doc, drawn from its Markdown, \
and is accepted from there. Developers skip a wall of text, so write a plan they take in at a \
glance: short sentences, bullets over paragraphs, a table wherever facts line up in columns, \
nothing restated from the request and nothing written to fill a section. In this order, leaving \
out any part with nothing real to say: `# <what will be built>`, a name of a few words, then two \
sentences: what changes, and what the user gets from it. `## Overview`: three to five bullets on \
how it works, as you would sketch it for a colleague: which part does what, and the decision the \
rest follows from. A picture goes here only when it shows what the bullets cannot, of the kind this \
change calls for, never out of habit: most changes need none, and boxes in a row that restate the \
bullets are worse than none. Each is a fenced block of JSON: a ```diagram when parts are added, \
removed or rewired, {\"caption\" (a few words), \"boxes\": [{\"id\", \"label\" (1-3 words), \"sub\" \
(a file, or a few words), \"col\", \"row\", \"change\", \"section\" (the id path of the blueprint section \
this box is, from blueprint_where or blueprint_search, when it is one)}], \"arrows\": [{\"from\", \"to\", \
\"label\" (1-3 words), \"change\"}]}, on a grid read left to right and at most three columns wide, \
where `change` is \"new\", \"changed\" or \"gone\" and what stays as it is has none; a ```sequence \
when the order of calls is the point, {\"caption\", \"actors\": [names], \"rows\": [{\"from\", \"to\", \
\"label\", \"note\"}]}; a ```screen when the user will see something new, {\"title\", \"device\": \
\"web\" or \"phone\", \"route\", \"items\": [{\"type\": heading, text, field, choice, button, list or \
image, \"label\", \"note\"}]}, with a note on each new item. `## Data` when stored data or an API's \
shape changes: a Markdown table for each table, collection or payload, `| Field | Type | Change | \
Notes |`, a row per field added, changed or dropped, then one line on what happens to what is \
already stored. `## Steps`: numbered, at most eight, each one line in plain words naming a piece of \
work that can be finished and checked on its own, in the order you will do it; once the plan is \
accepted they are your checklist. `## Trade-offs` only when you chose between real options: \
`**Pros**` and `**Cons**`, two or three bullets each, then the option you passed over in one line \
with why. `## Files`: a ```files block, one line per file: `+ path — what it is`, `~ path — what \
changes` or `- path — why it goes`. `## Risks` only when there are real ones, a bullet each with \
what you will do about it. `## Check`: one to three bullets on how you will know it works. A \
one-file fix is the title, its two sentences, Steps, Files and Check. Stay under 250 words outside \
the fenced blocks, and write code only where a signature is the decision. \
End on the answer itself."
);

/// What Codex, OpenCode and Pi are told (agents.rs): the same, without Claude Code's plan mode.
pub const AGENT_SYSTEM: &str = concat!(blueprint_system!(), "End on the answer itself.");

