            .output()
            .unwrap();
        assert_eq!(String::from_utf8_lossy(&bash.stdout).trim(), "[]");

        // A tab opened with the credit off leaves none behind.
        prepare(&mut CommandBuilder::new("sh"), &launch(None), &q, None, 1).unwrap();
        assert!(!file.exists());
    }

