    #[cfg(unix)]
    #[test]
    fn the_terminal_sees_only_a_link_to_the_plan_and_the_file_gets_it_back() {
        use std::io::Write as _;
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        let file = dir.path().join("plan.md");
        let whole = "# Fix\n\nIt works.\n\n```diagram\n{\"boxes\": []}\n```\n\n```screen\n{}\n```\n\n## Steps\n1. Do it\n";
        let hide = || {
            let mut child = Command::new("sh")
                .args(["-c", HIDE])
                .env("BLUEPRINT_CONTEXT", &q)
                .stdin(std::process::Stdio::piped())
                .spawn()
                .unwrap();
            let input = serde_json::json!({ "tool_name": "ExitPlanMode", "tool_input": { "plan": "…", "planFilePath": file } });
            child.stdin.take().unwrap().write_all(input.to_string().as_bytes()).unwrap();
            assert!(child.wait().unwrap().success());
        };
        let read = || std::fs::read_to_string(&file).unwrap();

        std::fs::write(&file, whole).unwrap();
        hide();
        assert_eq!(read(), "# Fix\n\n`\u{25b8} Open plan`\n");
        run(RESTORE, &q);
        assert_eq!(read(), whole);
        // Once: a later hook finds nothing waiting.
        std::fs::write(&file, "# Revised\n").unwrap();
        run(RESTORE, &q);
        assert_eq!(read(), "# Revised\n");

        // A plan the user rewrote while the dialog was up is theirs, and stays.
        std::fs::write(&file, whole).unwrap();
        hide();
        std::fs::write(&file, "# Mine\n").unwrap();
        run(RESTORE, &q);
        assert_eq!(read(), "# Mine\n");

        // A plan with no title still gets its link.
        std::fs::write(&file, "Just do it.\n").unwrap();
        hide();
        assert_eq!(read(), "`\u{25b8} Open plan`\n");
        run(RESTORE, &q);
        assert_eq!(read(), "Just do it.\n");
    }

    #[cfg(unix)]
    #[test]
    fn a_plan_opens_once_and_its_acceptance_is_heard_once() {
        use std::io::Write as _;
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        assert!(take_plan(&q).is_none());
        // ExitPlanMode's PreToolUse hook, handed what Claude Code hands it.
        let mut child = Command::new("sh")
            .args(["-c", PLAN])
            .env("BLUEPRINT_CONTEXT", &q)
            .stdin(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        child
            .stdin
            .take()
            .unwrap()
            .write_all(br##"{"tool_name":"ExitPlanMode","tool_input":{"plan":"# Add /health\n\nIt answers ok.","planFilePath":"/p/plan.md"}}"##)
            .unwrap();
        assert!(child.wait().unwrap().success());
        let plan = take_plan(&q).unwrap();
        assert_eq!(plan.text, "# Add /health\n\nIt answers ok.");
        assert_eq!(plan.file.as_deref(), Some("/p/plan.md"));
        assert!(take_plan(&q).is_none());

        assert!(!take_approved(&q));
        run(APPROVED, &q);
        assert!(take_approved(&q));
        assert!(!take_approved(&q));

        // What Claude hears on acceptance must be JSON Claude Code can read.
        let said: serde_json::Value = serde_json::from_str(&run(TODOS, &q)).unwrap();
        assert!(said["hookSpecificOutput"]["additionalContext"].as_str().unwrap().contains("blueprint-plan-step 1 doing"));
    }

    /// A hook as Claude Code runs it, handed `input`: what it printed, what it said to Claude, and its exit code.
    #[cfg(unix)]
    fn hand(cmd: &str, queue: &Path, input: &str) -> (String, String, i32) {
        use std::io::Write as _;
        let mut child = Command::new("sh")
            .args(["-c", cmd])
            .env("BLUEPRINT_CONTEXT", queue)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
        let out = child.wait_with_output().unwrap();
        (String::from_utf8(out.stdout).unwrap(), String::from_utf8(out.stderr).unwrap(), out.status.code().unwrap_or(-1))
    }

    #[cfg(unix)]
    #[test]
    fn an_accepted_plan_holds_claude_to_its_steps_until_each_is_marked() {
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        let file = dir.path().join("plan.md");
        std::fs::write(&file, "# Add /health\n\nIt answers ok.\n\n## Steps\n1. Add the route\n2) Test it\n\n## Check\n- 1. not a step\n").unwrap();
        let drafted = serde_json::json!({ "tool_name": "ExitPlanMode", "tool_input": { "plan": "…", "planFilePath": file } }).to_string();
        let stop = r#"{"hook_event_name":"Stop","stop_hook_active":false}"#;
        let mark = |args: &[&str]| {
            let s = Command::new("sh").arg("-c").arg(STEP).arg("blueprint-plan-step").args(args).env("BLUEPRINT_CONTEXT", &q).output().unwrap();
            s.status.code()
        };
        let status = || std::fs::read_to_string(q.with_extension("md.status")).unwrap_or_default();

        hand(PLAN, &q, &drafted);
        run(TODOS, &q);
        // Accepted but not started: nothing holds it yet, and the turn ends.
        assert_eq!(hand(UNFINISHED, &q, stop).2, 0);
        assert_eq!(status(), "done");
        assert_eq!(run(REMIND, &q), "");

        assert_eq!(mark(&["1", "doing"]), Some(0));
        assert_eq!(mark(&["one", "done"]), Some(2));
        assert_eq!(mark(&["1", "finished"]), Some(2));
        std::fs::remove_file(q.with_extension("md.status")).unwrap();
        let (_, said, code) = hand(UNFINISHED, &q, stop);
        assert_eq!(code, 2);
        assert!(said.contains("not marked done yet: 1, 2."), "{said}");
        // Sent back, the turn is not shown as finished.
        assert_eq!(status(), "");
        // Sent back once: the stop after that one goes through.
        assert_eq!(hand(UNFINISHED, &q, r#"{"stop_hook_active": true}"#).2, 0);

        // Compacting says the plan again, with the marks.
        let again = run(REMIND, &q);
        assert!(again.contains("## Steps\n1. Add the route") && again.contains("1\tdoing\t"), "{again}");

        mark(&["1", "done"]);
        mark(&["2", "skipped", "no", "test", "runner"]);
        assert_eq!(
            steps_of(&q),
            vec![
                Step { n: 1, state: "done".into(), note: None },
                Step { n: 2, state: "skipped".into(), note: Some("no test runner".into()) }
            ]
        );
        // All marked: the turn ends, and the plan is let go.
        assert_eq!(hand(UNFINISHED, &q, stop).2, 0);
        assert!(!q.with_extension("md.accepted").exists());
        assert_eq!(run(REMIND, &q), "");

        // A new plan clears the last one's marks.
        hand(PLAN, &q, &drafted);
        assert!(steps_of(&q).is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn a_plan_accepted_by_clearing_the_conversation_is_said_to_the_new_one() {
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        let file = dir.path().join("plan.md");
        std::fs::write(&file, "# Fix\n\n## Steps\n1. Do it\n").unwrap();
        // A clear with no plan waiting says nothing.
        assert_eq!(run(CLEARED, &q), "");
        hand(PLAN, &q, &serde_json::json!({ "tool_input": { "plan": "…", "planFilePath": file } }).to_string());
        let said = run(CLEARED, &q);
        assert!(said.starts_with("If the first message asks you to implement the plan below") && said.ends_with("# Fix\n\n## Steps\n1. Do it\n"), "{said}");
        // Once.
        assert_eq!(run(CLEARED, &q), "");
        // A new Claude in the tab is not held to it.
        run(FRESH, &q);
        assert!(!q.with_extension("md.accepted").exists());
    }

    /// The launcher as a tab runs it, with `bin` standing in for Claude.
    #[cfg(unix)]
    fn launch(queue: &Path, bin: &str) -> std::process::ExitStatus {
        Command::new(launcher().unwrap())
            .env("BLUEPRINT_CONTEXT", queue)
            .env("BLUEPRINT_CLAUDE_BIN", bin)
            .env("BLUEPRINT_CLAUDE_SETTINGS", "{}")
            .env("BLUEPRINT_CLAUDE_SYSTEM", "")
            .env("CLAUDE_CONFIG_DIR", queue.parent().unwrap())
            .status()
            .unwrap()
    }

    #[cfg(unix)]
    #[test]
    fn the_launcher_marks_the_tab_live_while_claude_runs() {
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        // A stand-in Claude that reports whether the marker is there.
        let probe = dir.path().join("probe");
        std::fs::write(&probe, format!("#!/bin/sh\n[ -e '{}' ] && exit 7\nexit 3\n", live(&q).display())).unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&probe, std::fs::Permissions::from_mode(0o755)).unwrap();

        assert!(!running(&q));
        // Live while it ran (7), and Claude's own status comes back.
        assert_eq!(launch(&q, probe.to_str().unwrap()).code(), Some(7));
        assert!(!running(&q));
        // Gone after a failing exit too.
        assert!(!launch(&q, "/bin/false").success());
        assert!(!running(&q));
    }

    #[cfg(unix)]
    #[test]
    fn the_tab_keeps_its_conversation_while_claude_runs() {
        use std::io::Write as _;
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        let start = |input: &str| {
            let mut child = Command::new("sh")
                .args(["-c", SESSION])
                .env("BLUEPRINT_CONTEXT", &q)
                .stdin(std::process::Stdio::piped())
                .spawn()
                .unwrap();
            child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
            assert!(child.wait().unwrap().success());
        };
        start(r#"{"session_id": "abc-1", "source": "startup"}"#);
        assert_eq!(session_of(&q).as_deref(), Some("abc-1"));
        // A /clear is a new conversation; input without one changes nothing.
        start(r#"{"session_id":"abc-2","source":"clear"}"#);
        start("{}");
        assert_eq!(session_of(&q).as_deref(), Some("abc-2"));
        // A reopened tab has it from the start, and loses it when Claude exits.
        resuming(&q, "abc-3").unwrap();
        assert_eq!(session_of(&q).as_deref(), Some("abc-3"));
        assert!(!launch(&q, "/usr/bin/false").success());
        assert!(session_of(&q).is_none());
        // Claude is handed it as its own two arguments, once.
        let args = dir.path().join("args");
        let probe = dir.path().join("probe");
        std::fs::write(&probe, format!("#!/bin/sh
printf '[%s]' \"$@\" > '{}'\n", args.display())).unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&probe, std::fs::Permissions::from_mode(0o755)).unwrap();
        // Only a conversation Claude Code kept: one never written to starts afresh.
        resuming(&q, "abc-5").unwrap();
        launch(&q, probe.to_str().unwrap());
        assert!(!std::fs::read_to_string(&args).unwrap().contains("--resume"));
        std::fs::create_dir_all(dir.path().join("projects/p")).unwrap();
        std::fs::write(dir.path().join("projects/p/abc-4.jsonl"), "").unwrap();
        resuming(&q, "abc-4").unwrap();
        launch(&q, probe.to_str().unwrap());
        assert!(std::fs::read_to_string(&args).unwrap().ends_with("[--resume][abc-4]"));
        launch(&q, probe.to_str().unwrap());
        assert!(!std::fs::read_to_string(&args).unwrap().contains("--resume"));
    }

