use tauri::Manager;

pub fn run() {
    update::remember_exe();
    // CI's check that a release's updater works (.github/scripts/check-update.sh): swap in what
    // app/scripts/update.mjs staged, with no window.
    if std::env::args().any(|a| a == "--apply-update") {
        let code = match update::data_dir().ok_or("No data folder".to_string()).and_then(|d| update::apply(&d)) {
            Ok(_) => 0,
            Err(e) => {
                eprintln!("{e}");
                1
            }
        };
        std::process::exit(code);
    }
    tauri::Builder::default()
        // The folder picker for importing a project; nothing else.
        .plugin(tauri_plugin_dialog::init())
        // The terminal's copy and paste (Ctrl+Shift+C / V): plain text only.
        .plugin(tauri_plugin_clipboard_manager::init())
        .manage(pty::Ptys::default())
        .manage(preview::Previews::default())
        .manage(server::Server::default())
        // A reload of the app's page forgets what its tabs had running: the web
        // pages its Previews opened (browser.rs), which would stay drawn over the
        // new page and refuse its labels, and the terminals and Previews' proxies,
        // which the new page opens afresh, resuming each Claude's conversation in
        // a new one; left running, two Claudes would answer in one conversation.
        .on_page_load(|webview, load| {
            if webview.label() == "main" && matches!(load.event(), tauri::webview::PageLoadEvent::Started) {
                let app = webview.app_handle();
                for (label, view) in app.webviews() {
                    if label.starts_with("browser-") || label.starts_with(popup::PREFIX) {
                        let _ = view.close();
                    }
                }
                app.state::<pty::Ptys>().kill_all();
                app.state::<preview::Previews>().close_all();
            }
        })
        .setup(|app| {
            // What the app kept under its old name moves over before anything reads it.
            rename::migrate(app.handle());
            // Claude's way into the preview, for every Claude tab (mcp.rs).
            mcp::start(app.handle().clone());
            // Tab files a crashed or killed Blueprint left in the temp folder.
            std::thread::spawn(claude::sweep_stale);
            // Plans Claude Code wrote and nothing has touched in a month.
            std::thread::spawn(claude::prune_plans);
            // `app:dev` serves the page itself; the installed app starts its
            // snapshot's server first (server.rs), so the window never opens
            // onto a page that isn't there yet.
            if cfg!(debug_assertions) {
                open_main(app.handle())?;
            } else {
                let handle = app.handle().clone();
                std::thread::spawn(move || {
                    // A release staged by a Blueprint that ended without quitting goes in now, before its server starts.
                    if let Ok(data) = handle.path().app_data_dir() {
                        update::sweep(&data);
                        match update::apply(&data) {
                            Ok(true) => {
                                update::relaunch();
                                return handle.exit(0);
                            }
                            Ok(false) => {}
                            Err(e) => eprintln!("update: {e}"),
                        }
                    }
                    if let Err(e) = server::start(&handle).and_then(|()| open_main(&handle).map_err(|e| e.to_string())) {
                        use tauri_plugin_dialog::DialogExt;
                        handle.dialog().message(e).title("Blueprint couldn't start").blocking_show();
                        handle.exit(1);
                    }
                });
            }
            #[cfg(target_os = "macos")]
            app_menu(app)?;
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            attention_count,
            pty::pty_spawn,
            pty::pty_write,
            pty::pty_resize,
            pty::pty_kill,
            pty::pty_state,
            pty::pty_which,
            pty::context_add,
            pty::context_set,
            pty::context_pending,
            pty::context_where,
            claude::claude_detect,
            preview::preview_open,
            preview::preview_target,
            preview::preview_close,
            preview::preview_external,
            preview::port_owner,
            preview::free_port,
            mcp::preview_reply,
            browser::browser_open,
            browser::browser_place,
            browser::browser_go,
            browser::browser_eval,
            browser::browser_close,
            browser::browser_picture,
            signins::signin_project,
            signins::signin_keep,
            signins::signin_list,
            signins::signin_forget,
            browser::native_input,
            devices::project_detect,
            devices::device_status,
            devices::device_setup,
            devices::device_start,
            devices::device_frame,
            devices::device_input,
            devices::device_describe,
            devices::device_run,
            devices::device_run_result,
            dictate::dictate_status,
            dictate::dictate_download,
            dictate::dictate_remove,
            dictate::dictate_start,
            dictate::dictate_stop,
            dictate::dictate_cancel,
            dictate::dictate_hush,
            files::file_resolve,
            files::file_read,
            files::file_write,
            update::update_restart,
        ])
        .build(tauri::generate_context!())
        .expect("error while building the app")
        .run(|app, event| {
            if let tauri::RunEvent::Exit = event {
                dictate::unhush();
                dictate::stop_download();
                app.state::<pty::Ptys>().kill_all();
                app.state::<preview::Previews>().close_all();
                devices::stop_all();
                server::stop(app);
                if !cfg!(debug_assertions) {
                    update::on_exit(app);
                }
            }
        });
}

/// The main window, as `tauri.conf.json` describes it (`create: false` there,
/// so it opens only once there is a page to show).
fn open_main(app: &tauri::AppHandle) -> tauri::Result<()> {
    let opener = app.clone();
    let _window = tauri::WebviewWindowBuilder::from_config(app, &app.config().app.windows[0])?
        .on_new_window(move |url, features| popup::open(&opener, &url, features))
        .build()?;
    #[cfg(target_os = "linux")]
    {
        pinch_to_page(&_window);
        browser::overlay_app(&_window);
    }
    Ok(())
}

/// The Dock icon's badge: how many Claude tabs have finished or are waiting on
/// the user (components/agent/workspace.tsx), so it shows from any app, as Discord's does.
#[tauri::command]
fn attention_count(app: tauri::AppHandle, n: i64) {
    if let Some(w) = app.get_webview_window("main") {
        let _ = w.set_badge_count(if n == 0 { None } else { Some(n) });
    }
}

/// The menu bar: the app's actions, and its keys from anywhere. A key pressed in
/// a Preview's page (its own webview, or a frame) never reaches the page's
/// handler, but a menu key equivalent is the app's wherever focus is. A key
/// the page handles itself is not passed on to the menu, so it acts once.
#[cfg(target_os = "macos")]
fn app_menu(app: &tauri::App) -> tauri::Result<()> {
    use tauri::menu::{Menu, MenuItem, PredefinedMenuItem, Submenu};
    use tauri::Emitter;
    let menu = Menu::default(app.handle())?;
    // Items that open something in the page (components/chrome/menubar.tsx), each sent as `blueprint:menu`.
    let open = |id: &str, text: &str, key: Option<&str>| MenuItem::with_id(app, format!("open-{id}"), text, true, key);
    let named = |name: &str| -> tauri::Result<Option<Submenu<tauri::Wry>>> {
        Ok(menu.items()?.into_iter().filter_map(|i| i.as_submenu().cloned()).find(|s| s.text().is_ok_and(|t| t == name)))
    };
    if let Some(first) = menu.items()?.first().and_then(|i| i.as_submenu().cloned()) {
        // After About and its separator.
        first.insert_items(&[&open("settings", "Settings…", Some("Cmd+,"))?, &PredefinedMenuItem::separator(app)?], 2)?;
    }
    if let Some(file) = named("File")? {
        file.prepend_items(&[&open("new-project", "New Project…", Some("Cmd+N"))?, &open("open-folder", "Open Folder…", Some("Cmd+O"))?])?;
    }
    if let Some(view) = named("View")? {
        // Cmd+P, Cmd+K and Cmd+Shift+P are the palette's own keys (components/chrome/palette.tsx).
        // No zoom here: Cmd+= and Cmd+- are also the terminal's font size, and a menu key would take them from it.
        view.prepend_items(&[
            &open("palette", "Go to…", Some("Cmd+P"))?,
            &open("palette-code", "Find File or Symbol", Some("Cmd+K"))?,
            &open("palette-actions", "Actions", Some("Cmd+Shift+P"))?,
            &PredefinedMenuItem::separator(app)?,
            &open("blueprint", "Show Blueprint", None)?,
            &open("diff", "Changes", Some("Cmd+Shift+D"))?,
            &open("history", "History", None)?,
            &open("files", "Files", None)?,
            &PredefinedMenuItem::separator(app)?,
        ])?;
    }
    if let Some(help) = named("Help")? {
        help.append(&open("feedback", "Report a Bug or Send Feedback…", None)?)?;
    }
    let cmd = MenuItem::with_id(app, "terminal", "Toggle Terminal", true, Some("Cmd+`"))?;
    let ctrl = MenuItem::with_id(app, "terminal-ctrl", "Toggle Terminal", true, Some("Ctrl+`"))?;
    // Claude Code's send-now (components/agent/shell.tsx): Control-Return is otherwise
    // AppKit's key for the context menu, which opens and the terminal never sees it.
    let send = MenuItem::with_id(app, "send-now", "Send Now", true, Some("Ctrl+Enter"))?;
    let claude = open("claude", "Ask Claude", None)?;
    menu.append(&Submenu::with_items(app, "Terminal", true, &[&cmd, &ctrl, &send, &claude])?)?;
    // The title bar's project tabs (components/chrome/titlebar.tsx), for when focus is in a Preview's page.
    let manage = open("projects", "Manage Projects…", Some("Cmd+Shift+O"))?;
    let gap = PredefinedMenuItem::separator(app)?;
    let mut projects = Vec::new();
    for n in 1..=9 {
        projects.push(MenuItem::with_id(app, format!("project-{n}"), format!("Project {n}"), true, Some(&format!("Cmd+{n}")))?);
    }
    // No key: Ctrl+Tab steps through the tabs (the Window menu below), as in a browser.
    projects.push(MenuItem::with_id(app, "project-last", "Last Project", true, None::<&str>)?);
    let mut items: Vec<&dyn tauri::menu::IsMenuItem<tauri::Wry>> = vec![&manage, &gap];
    items.extend(projects.iter().map(|m| m as &dyn tauri::menu::IsMenuItem<tauri::Wry>));
    menu.append(&Submenu::with_items(app, "Projects", true, &items)?)?;
    // A Preview's own keys, as a browser's (components/preview/preview.tsx): its page is
    // a webview of its own or a frame, and the keys pressed in it stay there.
    let reload = MenuItem::with_id(app, "preview-reload", "Reload Page", true, Some("Cmd+R"))?;
    let back = MenuItem::with_id(app, "preview-back", "Back", true, Some("Cmd+["))?;
    let forward = MenuItem::with_id(app, "preview-forward", "Forward", true, Some("Cmd+]"))?;
    let address = MenuItem::with_id(app, "preview-address", "Open Location", true, Some("Cmd+L"))?;
    menu.append(&Submenu::with_items(app, "Preview", true, &[&reload, &back, &forward, &address])?)?;
    // A menu key reaches the menu before the page, so the page is handed these
    // and the tab strip with focus acts on them (components/agent/workspace.tsx).
    let next = MenuItem::with_id(app, "tab-next", "Next Tab", true, Some("Ctrl+Tab"))?;
    let prev = MenuItem::with_id(app, "tab-prev", "Previous Tab", true, Some("Ctrl+Shift+Tab"))?;
    let next_cmd = MenuItem::with_id(app, "tab-next-cmd", "Next Tab", true, Some("Cmd+Shift+]"))?;
    let prev_cmd = MenuItem::with_id(app, "tab-prev-cmd", "Previous Tab", true, Some("Cmd+Shift+["))?;
    let close = MenuItem::with_id(app, "tab-close", "Close Tab", true, Some("Cmd+W"))?;
    menu.append(&Submenu::with_items(app, "Tabs", true, &[&next, &prev, &next_cmd, &prev_cmd, &close])?)?;
    // Cmd+W closes a tab, never the window: the default Close Window took the
    // key first and, Blueprint being one window, quit the app.
    for item in menu.items()? {
        if let Some(sub) = item.as_submenu() {
            for inner in sub.items()? {
                if let Some(p) = inner.as_predefined_menuitem().filter(|p| p.text().is_ok_and(|t| t == "Close Window")) {
                    sub.remove(p)?;
                }
            }
        }
    }
    app.set_menu(menu)?;
    app.on_menu_event(|app, e| {
        let id = e.id().as_ref();
        if let Some(what) = id.strip_prefix("open-") {
            let _ = app.emit_to("main", "blueprint:menu", what.to_string());
        } else if id == "terminal" || id == "terminal-ctrl" {
            let _ = app.emit_to("main", "blueprint:toggle-workspace", ());
        } else if id == "send-now" {
            let _ = app.emit_to("main", "blueprint:send-now", ());
        } else if id == "tab-close" {
            let _ = app.emit_to("main", "blueprint:tab-close", ());
        } else if let Some(dir) = id.strip_prefix("tab-") {
            let _ = app.emit_to("main", "blueprint:tab-step", if dir.starts_with("next") { 1 } else { -1 });
        } else if let Some(n) = id.strip_prefix("project-") {
            let _ = app.emit_to("main", "blueprint:project", n.to_string());
        } else if let Some(key) = id.strip_prefix("preview-") {
            // The address bar is the app's page: the keyboard is taken back from a page's webview.
            if key == "address" {
                if let Some(main) = app.get_webview("main") {
                    let _ = main.set_focus();
                }
            }
            let _ = app.emit_to("main", "blueprint:preview-key", key.to_string());
        }
    });
    Ok(())
}

/// WebKitGTK answers a touchpad pinch by magnifying the whole page — the title
/// bar and status bar with it, out of view — and tells the page nothing. So
/// the pinch is taken here, before WebKit's own handler runs, and handed to
/// the level's zoom (components/chrome/zoom.tsx) as a `blueprint:pinch` event: only the
/// blueprint magnifies, as a pinch does on a Mac. `scale` is relative to the start
/// of the pinch, which is exactly 1.
#[cfg(target_os = "linux")]
fn pinch_to_page(window: &tauri::WebviewWindow) {
    use gtk::glib::Propagation;
    use gtk::prelude::WidgetExt;
    let target = window.clone();
    let _ = window.with_webview(move |webview| {
        webview.inner().connect_event(move |_, event| {
            let Some(pinch) = event.downcast_ref::<gtk::gdk::EventTouchpadPinch>() else {
                return Propagation::Proceed;
            };
            let (x, y) = pinch.position();
            let _ = target.eval(format!(
                "window.dispatchEvent(new CustomEvent('blueprint:pinch',{{detail:{{scale:{},x:{x},y:{y}}}}}))",
                pinch.scale()
            ));
            Propagation::Stop
        });
    });
}

