//! Claude's hands on the preview. Every Claude tab is started with this
//! server in its MCP config (claude.rs), so it can look at the project's
//! running app and use it, the way the Chrome extension lets it use a browser:
//! screenshot, click, type, read the page, navigate, resize the viewport, read
//! the console. And on a phone simulator, through `device` (devices.rs). And
//! the project's terminals, the dev server's logs first (`read_terminal`).
//!
//! Codex and OpenCode get it in their own config, and Pi through its extension
//! (agents.rs). `blueprint-terminal` (claude.rs) reaches `read_terminal` through
//! `/text` on the same URL: one tools/call, answered as its plain text.
//!
//! It is MCP's streamable HTTP transport in its simplest form: one JSON-RPC
//! message per POST, answered as plain JSON. The URL carries a secret, and the
//! tab the request came from, so each Claude drives its own project's
//! preview. The page does the work (components/preview/preview.tsx, and the agent
//! inside the frame, agent.js): a call is handed to it as a `blueprint:preview`
//! event and waits for `preview_reply`. A screenshot is WebKit's own picture
//! of the frame's part of the window.

use serde_json::{json, Value};
use std::collections::HashMap;
use std::io::BufReader;
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{mpsc, Mutex, OnceLock};
use std::time::Duration;
use tauri::{AppHandle, Emitter};

use crate::preview::{read_body, read_head, respond};

struct Server {
    port: u16,
    token: String,
}

static SERVER: OnceLock<Server> = OnceLock::new();

type Reply = Result<Value, String>;
static PENDING: OnceLock<Mutex<HashMap<u64, mpsc::Sender<Reply>>>> = OnceLock::new();
static NEXT: AtomicU64 = AtomicU64::new(1);
/// Claude sends a batch of actions at once, each on its own connection; taken
/// in turn, a click has landed before the typing after it looks for focus.
static ONE_AT_A_TIME: Mutex<()> = Mutex::new(());

fn pending() -> &'static Mutex<HashMap<u64, mpsc::Sender<Reply>>> {
    PENDING.get_or_init(Default::default)
}

/// 128 random bits, from the hasher std seeds from the OS.
fn secret() -> String {
    use std::hash::{BuildHasher, Hasher};
    let half = || std::collections::hash_map::RandomState::new().build_hasher().finish();
    format!("{:016x}{:016x}", half(), half())
}

pub fn start(app: AppHandle) {
    let Ok(listener) = TcpListener::bind(("127.0.0.1", 0)) else { return };
    let Ok(port) = listener.local_addr().map(|a| a.port()) else { return };
    let _ = SERVER.set(Server { port, token: secret() });
    std::thread::spawn(move || {
        for conn in listener.incoming().flatten() {
            let app = app.clone();
            std::thread::spawn(move || {
                let _ = handle(conn, &app);
            });
        }
    });
}

/// This server's address for tab `tab`, once it is up.
pub fn url(tab: u32) -> Option<String> {
    let s = SERVER.get()?;
    Some(format!("http://127.0.0.1:{}/mcp/{}/{tab}", s.port, s.token))
}

/// The `--mcp-config` for Claude in tab `tab`, once the server is up.
pub fn config(tab: u32) -> Option<String> {
    Some(json!({ "mcpServers": { "blueprint-preview": { "type": "http", "url": url(tab)? } } }).to_string())
}

fn handle(conn: TcpStream, app: &AppHandle) -> std::io::Result<()> {
    let s = SERVER.get().ok_or_else(|| std::io::Error::other("not started"))?;
    let mut r = BufReader::new(conn.try_clone()?);
    let mut w = conn;
    let head = read_head(&mut r)?;
    // Only ever addressed as itself: a page that rebinds a name to the loopback is turned away.
    let host = head.get("host").unwrap_or("");
    if host != format!("127.0.0.1:{}", s.port) && host != format!("localhost:{}", s.port) {
        return respond(&mut w, "403 Forbidden", "text/plain", b"", &[]);
    }
    let mut line = head.line.split_whitespace();
    let (method, path) = (line.next().unwrap_or(""), line.next().unwrap_or(""));
    let to = path
        .strip_prefix("/mcp/")
        .and_then(|rest| rest.split_once('/'))
        .filter(|(token, _)| *token == s.token)
        .and_then(|(_, rest)| {
            let (tab, sub) = rest.split_once('/').unwrap_or((rest, ""));
            Some((tab.parse::<u32>().ok()?, sub)).filter(|(_, sub)| ["", "text", "codex-trust"].contains(sub))
        });
    let Some((tab, sub)) = to else {
        return respond(&mut w, "404 Not Found", "text/plain", b"", &[]);
    };
    let text = sub == "text";
    if method != "POST" {
        // No stream of server-sent messages: this server only ever answers.
        return respond(&mut w, "405 Method Not Allowed", "text/plain", b"", &[("Allow", "POST")]);
    }
    let body = read_body(&mut r, &head, false)?;
    let Ok(msg) = serde_json::from_slice::<Value>(&body) else {
        let e = json!({ "jsonrpc": "2.0", "id": null, "error": { "code": -32700, "message": "Parse error" } });
        return respond(&mut w, "400 Bad Request", "application/json", e.to_string().as_bytes(), &[]);
    };
    // The Codex launcher, before it starts Codex (agents.rs).
    if sub == "codex-trust" {
        let field = |k: &str| msg.get(k).and_then(Value::as_str).unwrap_or("").to_string();
        return match crate::agents::trust_codex(&field("bin"), &field("home")) {
            Ok(()) => respond(&mut w, "200 OK", "text/plain", b"", &[]),
            Err(e) => respond(&mut w, "500 Internal Server Error", "text/plain", e.as_bytes(), &[]),
        };
    }
    if text {
        let r = rpc(&msg, tab, app).unwrap_or(Value::Null);
        let result = &r["result"];
        let said: Vec<&str> = result["content"].as_array().into_iter().flatten().filter_map(|c| c["text"].as_str()).collect();
        let body = format!("{}\n", said.join("\n"));
        let status = if result["isError"] == true || result.is_null() { "422 Unprocessable Entity" } else { "200 OK" };
        return respond(&mut w, status, "text/plain; charset=utf-8", body.as_bytes(), &[]);
    }
    let out = match &msg {
        Value::Array(all) => {
            let replies: Vec<Value> = all.iter().filter_map(|m| rpc(m, tab, app)).collect();
            (!replies.is_empty()).then(|| Value::Array(replies))
        }
        m => rpc(m, tab, app),
    };
    match out {
        Some(v) => respond(&mut w, "200 OK", "application/json", v.to_string().as_bytes(), &[]),
        None => respond(&mut w, "202 Accepted", "text/plain", b"", &[]),
    }
}

const INSTRUCTIONS: &str = "These tools use the Preview tab in Blueprint: the user's project, \
running as a web app beside you, exactly as the user sees it, and any page on the web. Use them \
to check that what you built works: take a screenshot, then click, type and read the page, as \
you would in a browser. They are your browser here: to look something up or read a page on \
the web, navigate the preview there (an address, or words to search for) instead of opening \
another browser, so the user sees it beside you. To research the web while working on the \
project's own page, navigate with `new_tab` so the page stays open in its own Preview tab, \
and once there are several, name the one each call is for with `tab`. The user often keeps several \
open at once (the app, its landing page, an admin page): with more than one, every reply lists them all \
with the page each shows, so when yours shows a different page than you need, pick the right one with \
`tab`, or navigate yours there, rather than taking the page you want for closed. Other agents in the \
project have Previews of their own: a call without `tab` goes to yours, and one marked as another \
agent's is used only when you name it. WebFetch and WebSearch are fine for reading \
docs as text; they stay out of the preview. `device` does the same on an iOS Simulator or \
Android emulator running in the app. `read_terminal` reads the project's terminals, the dev \
server's logs by default: read it when the page misbehaves, a build fails or a request errors. When a page \
needs an account (a login wall on Instagram, X, a private dashboard), call `sign_in` and let the user sign in \
themselves; never type a password. Sign-ins are kept, so a site signed in to once opens signed in later. `blueprint_search`, `blueprint_section` and `blueprint_where` read the project's \
blueprint in Blueprint: what each part of the code is for and which section explains it. Ask `blueprint_where` about a \
file before changing it, and name sections by the id path these tools give.";

/// One JSON-RPC message; nothing back for a notification.
fn rpc(msg: &Value, tab: u32, app: &AppHandle) -> Option<Value> {
    let id = msg.get("id")?.clone();
    let params = msg.get("params").cloned().unwrap_or(Value::Null);
    let result = match msg.get("method").and_then(Value::as_str).unwrap_or("") {
        "initialize" => Ok(json!({
            "protocolVersion": params.get("protocolVersion").and_then(Value::as_str).unwrap_or("2025-06-18"),
            "capabilities": { "tools": { "listChanged": false } },
            "serverInfo": { "name": "blueprint", "version": env!("CARGO_PKG_VERSION") },
            "instructions": INSTRUCTIONS,
        })),
        "ping" => Ok(json!({})),
        "tools/list" => Ok(json!({ "tools": tools() })),
        "tools/call" => {
            let name = params.get("name").and_then(Value::as_str).unwrap_or("");
            let args = params.get("arguments").cloned().unwrap_or_else(|| json!({}));
            // A sign-in waits on the user for minutes: other calls are not held up behind it.
            let _turn = (name != "sign_in").then(|| ONE_AT_A_TIME.lock().unwrap_or_else(|e| e.into_inner()));
            Ok(match call(name, &args, tab, app) {
                Ok(content) => json!({ "content": content }),
                Err(e) => json!({ "content": [{ "type": "text", "text": e }], "isError": true }),
            })
        }
        _ => Err(json!({ "code": -32601, "message": "Method not found" })),
    };
    Some(match result {
        Ok(r) => json!({ "jsonrpc": "2.0", "id": id, "result": r }),
        Err(e) => json!({ "jsonrpc": "2.0", "id": id, "error": e }),
    })
}

fn text(t: impl Into<String>) -> Vec<Value> {
    vec![json!({ "type": "text", "text": t.into() })]
}

fn said(v: Value) -> Vec<Value> {
    text(match v {
        Value::String(s) => s,
        v => v.to_string(),
    })
}

fn call(name: &str, args: &Value, tab: u32, app: &AppHandle) -> Result<Vec<Value>, String> {
    // Which Preview tab a call is for, when the project has more than one (components/agent/workspace.tsx).
    let on = |mut cmd: Value| {
        cmd["tab"] = args.get("tab").cloned().unwrap_or(Value::Null);
        cmd
    };
    match name {
        "computer" if args.get("action").and_then(Value::as_str) == Some("screenshot") => screenshot(on(json!({ "op": "frame" })), tab, app),
        "computer" | "read_page" | "find" | "form_input" | "get_page_text" | "javascript" => {
            ask(app, tab, on(json!({ "op": "agent", "name": name, "args": args }))).map(said)
        }
        "navigate" => ask(app, tab, on(json!({ "op": "navigate", "url": args.get("url"), "newTab": args.get("new_tab") }))).map(said),
        "sign_in" => ask_for(app, tab, on(json!({ "op": "sign_in", "url": args.get("url") })), 600).map(said),
        "resize_preview" => ask(app, tab, on(json!({ "op": "resize", "args": args }))).map(said),
        "read_console_messages" => ask(app, tab, on(json!({ "op": "console", "args": args }))).map(said),
        "device" => crate::devices::tool(args, app),
        "blueprint_search" | "blueprint_section" | "blueprint_where" => ask(app, tab, json!({ "op": "blueprint", "name": name, "args": args })).map(said),
        "read_terminal" => ask(app, tab, json!({ "op": "terminal", "args": args })).map(said),
        _ => Err(format!("No tool called {name}.")),
    }
}

/// Hands a call to the page and waits for its answer.
fn ask(app: &AppHandle, tab: u32, cmd: Value) -> Reply {
    ask_for(app, tab, cmd, 60)
}

fn ask_for(app: &AppHandle, tab: u32, cmd: Value, secs: u64) -> Reply {
    let id = NEXT.fetch_add(1, Ordering::Relaxed);
    let (tx, rx) = mpsc::channel();
    pending().lock().unwrap().insert(id, tx);
    let sent = app.emit_to("main", "blueprint:preview", json!({ "id": id, "tab": tab, "cmd": cmd }));
    let out = match sent {
        Ok(()) => rx
            .recv_timeout(Duration::from_secs(secs))
            .unwrap_or_else(|_| Err(format!("The preview did not answer within {} seconds.", secs))),
        Err(e) => Err(e.to_string()),
    };
    pending().lock().unwrap().remove(&id);
    out
}

/// The page's answer to `ask`.
#[tauri::command]
pub fn preview_reply(id: u64, ok: bool, value: Value) {
    if let Some(tx) = pending().lock().unwrap().remove(&id) {
        let _ = tx.send(if ok {
            Ok(value)
        } else {
            Err(value.as_str().map_or_else(|| value.to_string(), String::from))
        });
    }
}

/// Where the frame is in the window, and how big its viewport is.
#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
struct Frame {
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    viewport_width: f64,
    viewport_height: f64,
    dpr: f64,
    url: String,
    /// A page from the web has a webview of its own (browser.rs).
    view: Option<String>,
}

fn screenshot(cmd: Value, tab: u32, app: &AppHandle) -> Result<Vec<Value>, String> {
    let frame: Frame = serde_json::from_value(ask(app, tab, cmd)?).map_err(|e| e.to_string())?;
    // Asked for at the viewport's own size in pixels, so a point in the
    // picture is a point to click.
    let png = snapshot(app, &frame, frame.viewport_width / frame.dpr.max(1.0))?;
    let (w, h) = png_size(&png).unwrap_or((0, 0));
    let mut note = format!(
        "{} — viewport {}×{}.",
        frame.url, frame.viewport_width as u32, frame.viewport_height as u32
    );
    if w != frame.viewport_width as u32 && w > 0 {
        note.push_str(&format!(
            " The screenshot is {w}×{h} pixels: scale its coordinates by {:.3} before clicking.",
            frame.viewport_width / w as f64
        ));
    }
    Ok(vec![
        json!({ "type": "image", "data": base64(&png), "mimeType": "image/png" }),
        json!({ "type": "text", "text": note }),
    ])
}

#[cfg(target_os = "macos")]
fn snapshot(app: &AppHandle, frame: &Frame, points: f64) -> Result<Vec<u8>, String> {
    use objc2_app_kit::{NSBitmapImageFileType, NSBitmapImageRep, NSImage};
    use objc2_foundation::{NSDictionary, NSError, NSNumber, NSPoint, NSRect, NSSize};
    use objc2_web_kit::{WKSnapshotConfiguration, WKWebView};
    use tauri::Manager;

    let own = frame.view.is_some();
    let view = app.get_webview(frame.view.as_deref().unwrap_or("main")).ok_or("The window is gone.")?;
    let (tx, rx) = mpsc::channel::<Option<Vec<u8>>>();
    let rect = NSRect::new(NSPoint::new(frame.x, frame.y), NSSize::new(frame.width, frame.height));
    view
        .with_webview(move |webview| unsafe {
            let view = &*(webview.inner() as *const WKWebView);
            // This closure runs on the main thread: Tauri's promise.
            let config = WKSnapshotConfiguration::new(objc2::MainThreadMarker::new_unchecked());
            // A page in its own webview is the whole of it.
            if !own {
                config.setRect(rect);
            }
            config.setSnapshotWidth(Some(&NSNumber::new_f64(points)));
            let tx = tx.clone();
            let done = block2::RcBlock::new(move |image: *mut NSImage, _: *mut NSError| {
                let png = image.as_ref().and_then(|image| {
                    let tiff = image.TIFFRepresentation()?;
                    let rep = NSBitmapImageRep::imageRepWithData(&tiff)?;
                    let png = rep.representationUsingType_properties(NSBitmapImageFileType::PNG, &NSDictionary::new())?;
                    Some(png.to_vec())
                });
                let _ = tx.send(png);
            });
            view.takeSnapshotWithConfiguration_completionHandler(Some(&config), &done);
        })
        .map_err(|e| e.to_string())?;
    rx.recv_timeout(Duration::from_secs(10))
        .ok()
        .flatten()
        .ok_or_else(|| "The screenshot did not come back.".into())
}

#[cfg(not(target_os = "macos"))]
fn snapshot(_: &AppHandle, _: &Frame, _: f64) -> Result<Vec<u8>, String> {
    Err("Screenshots of the preview are only taken on macOS so far: read_page and get_page_text show what is on it.".into())
}

/// A PNG's width and height, from its header.
pub(crate) fn png_size(png: &[u8]) -> Option<(u32, u32)> {
    let w = png.get(16..20)?;
    let h = png.get(20..24)?;
    Some((u32::from_be_bytes(w.try_into().ok()?), u32::from_be_bytes(h.try_into().ok()?)))
}

pub(crate) fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for c in bytes.chunks(3) {
        let n = (c[0] as u32) << 16 | (*c.get(1).unwrap_or(&0) as u32) << 8 | *c.get(2).unwrap_or(&0) as u32;
        for i in 0..4 {
            if i <= c.len() {
                out.push(T[(n >> (18 - 6 * i) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

