//! The preview: the project's running web app, in a workspace tab
//! (components/preview/preview.tsx). The page is not framed from its dev server
//! directly. It is framed through a small proxy on its own port here, which
//! passes every request on and adds one script to each HTML page: the agent
//! (agent.js), which lets the app, and Claude through it (mcp.rs), read the
//! page and click, type and scroll in it. A page from another origin cannot be
//! reached into from the window around it any other way.
//!
//! The proxy is plain HTTP/1.1 over std, one request per connection: every
//! response says `Connection: close`, so nothing here has to follow a
//! keep-alive stream, and anything it does not change is copied through byte
//! for byte. A WebSocket (the dev server's hot reload) is tunnelled as it is.
//! The frame is served from `localhost` like the app itself, so the two are
//! the same site and the page keeps its cookies.

use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{Shutdown, TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::{Arc, Mutex};

const AGENT: &str = include_str!("agent.js");

/// Where a preview's requests go: the dev server's host and port.
#[derive(Clone)]
struct Upstream {
    host: String,
    port: u16,
}

impl Upstream {
    /// `http://localhost:5173/x`, `localhost:5173`, `0.0.0.0:3000`. A server
    /// that says it listens everywhere is reached on the loopback.
    fn parse(target: &str) -> Option<Self> {
        let rest = target.trim().trim_start_matches("http://");
        let authority = rest.split(['/', '?', '#']).next()?;
        let (host, port) = match authority.strip_prefix('[') {
            Some(v6) => {
                let (h, p) = v6.split_once("]:")?;
                (h.to_string(), p)
            }
            None => {
                let (h, p) = authority.rsplit_once(':')?;
                (h.to_string(), p)
            }
        };
        let host = if host == "0.0.0.0" || host == "::" { "127.0.0.1".into() } else { host };
        Some(Self { host, port: port.parse().ok()? })
    }

    fn authority(&self) -> String {
        if self.host.contains(':') {
            format!("[{}]:{}", self.host, self.port)
        } else {
            format!("{}:{}", self.host, self.port)
        }
    }

    fn origin(&self) -> String {
        format!("http://{}", self.authority())
    }
}

struct Proxy {
    port: u16,
    upstream: Arc<Mutex<Upstream>>,
    closed: Arc<AtomicBool>,
}

#[derive(Default)]
pub struct Previews {
    next: AtomicU32,
    open: Mutex<HashMap<u32, Proxy>>,
}

impl Previews {
    pub fn close_all(&self) {
        for (_, p) in self.open.lock().unwrap().drain() {
            stop(&p);
        }
    }
}

fn stop(p: &Proxy) {
    p.closed.store(true, Ordering::Relaxed);
    // The accept loops are blocked; one connection each wakes it to see the flag.
    let _ = TcpStream::connect(("127.0.0.1", p.port));
    let _ = TcpStream::connect(("::1", p.port));
}

#[derive(serde::Serialize)]
pub struct Opened {
    id: u32,
    /// The proxy's port: the frame loads `http://localhost:{port}`.
    port: u16,
}

/// A proxy in front of `target`, on a port of its own.
#[tauri::command]
pub fn preview_open(target: String, previews: tauri::State<Previews>) -> Result<Opened, String> {
    let upstream = Upstream::parse(&target).ok_or_else(|| format!("Not an address the preview can open: {target}"))?;
    let listener = TcpListener::bind(("127.0.0.1", 0)).map_err(|e| e.to_string())?;
    let port = listener.local_addr().map_err(|e| e.to_string())?.port();
    // `localhost` may be looked up as ::1 first; the same port there too, if it is free.
    let v6 = TcpListener::bind(("::1", port)).ok();
    let upstream = Arc::new(Mutex::new(upstream));
    let closed = Arc::new(AtomicBool::new(false));
    for l in std::iter::once(listener).chain(v6) {
        let (upstream, closed) = (upstream.clone(), closed.clone());
        std::thread::spawn(move || {
            for conn in l.incoming() {
                if closed.load(Ordering::Relaxed) {
                    break;
                }
                let Ok(conn) = conn else { continue };
                let to = upstream.lock().unwrap().clone();
                std::thread::spawn(move || {
                    let _ = serve(conn, &to, port);
                });
            }
        });
    }
    let id = previews.next.fetch_add(1, Ordering::Relaxed) + 1;
    previews.open.lock().unwrap().insert(id, Proxy { port, upstream, closed });
    Ok(Opened { id, port })
}

/// Points a preview at another server, keeping its port: the frame's origin,
/// and so the page's storage, stay the same when a dev server restarts elsewhere.
#[tauri::command]
pub fn preview_target(id: u32, target: String, previews: tauri::State<Previews>) -> Result<(), String> {
    let upstream = Upstream::parse(&target).ok_or_else(|| format!("Not an address the preview can open: {target}"))?;
    let open = previews.open.lock().unwrap();
    let p = open.get(&id).ok_or("no such preview")?;
    *p.upstream.lock().unwrap() = upstream;
    Ok(())
}

#[tauri::command]
pub fn preview_close(id: u32, previews: tauri::State<Previews>) {
    if let Some(p) = previews.open.lock().unwrap().remove(&id) {
        stop(&p);
    }
}

/// The page in the user's own browser, from the preview's toolbar.
#[tauri::command]
pub fn preview_external(url: String) -> Result<(), String> {
    if !(url.starts_with("http://") || url.starts_with("https://")) {
        return Err("Only a web address opens in the browser.".into());
    }
    let mut opener = if cfg!(windows) {
        let mut c = crate::proc::command("rundll32");
        c.arg("url.dll,FileProtocolHandler");
        c
    } else {
        crate::proc::command(if cfg!(target_os = "macos") { "open" } else { "xdg-open" })
    };
    opener.arg(&url).spawn().map(|_| ()).map_err(|e| e.to_string())
}

/// The folder the program serving `port` on this machine runs in, by `lsof`:
/// a dev server whose port is taken shows what holds it only when that is
/// the same project's (components/agent/workspace.tsx). None where it cannot tell.
#[tauri::command]
pub fn port_owner(port: u16) -> Option<String> {
    let out = |args: &[&str]| -> Option<String> {
        let o = crate::proc::command("lsof").args(args).output().ok()?;
        Some(String::from_utf8_lossy(&o.stdout).into_owned())
    };
    let pid = out(&["-nP", &format!("-iTCP:{port}"), "-sTCP:LISTEN", "-t"])?.lines().next()?.trim().to_string();
    out(&["-a", "-p", &pid, "-d", "cwd", "-Fn"])?.lines().find_map(|l| l.strip_prefix('n').map(str::to_string))
}

/// A port nothing on this machine is serving, for a dev server whose own is taken.
#[tauri::command]
pub fn free_port() -> Result<u16, String> {
    Ok(TcpListener::bind(("127.0.0.1", 0)).and_then(|l| l.local_addr()).map_err(|e| e.to_string())?.port())
}

/* ── HTTP, as little of it as a proxy needs ───────────────────── */

pub(crate) struct Head {
    /// The request or status line.
    pub line: String,
    pub headers: Vec<(String, String)>,
}

impl Head {
    pub fn get(&self, name: &str) -> Option<&str> {
        self.headers.iter().find(|(k, _)| k.eq_ignore_ascii_case(name)).map(|(_, v)| v.as_str())
    }

    fn has_token(&self, name: &str, token: &str) -> bool {
        self.get(name).is_some_and(|v| v.split(',').any(|t| t.trim().eq_ignore_ascii_case(token)))
    }
}

/// A message's head: its first line and headers, up to the blank line.
pub(crate) fn read_head(r: &mut impl BufRead) -> std::io::Result<Head> {
    let mut line = String::new();
    if r.read_line(&mut line)? == 0 {
        return Err(std::io::ErrorKind::UnexpectedEof.into());
    }
    let mut headers = Vec::new();
    let mut size = line.len();
    loop {
        let mut h = String::new();
        if r.read_line(&mut h)? == 0 {
            return Err(std::io::ErrorKind::UnexpectedEof.into());
        }
        size += h.len();
        if size > 64 * 1024 {
            return Err(std::io::Error::other("head too large"));
        }
        let h = h.trim_end_matches(['\r', '\n']);
        if h.is_empty() {
            break;
        }
        if let Some((k, v)) = h.split_once(':') {
            headers.push((k.trim().to_string(), v.trim().to_string()));
        }
    }
    Ok(Head { line: line.trim_end().to_string(), headers })
}

/// A body as its head frames it: chunked, a length, or (`to_eof`) the rest of
/// the stream, which is how a response with neither ends.
pub(crate) fn read_body(r: &mut impl BufRead, head: &Head, to_eof: bool) -> std::io::Result<Vec<u8>> {
    let mut body = Vec::new();
    let framed = head.has_token("transfer-encoding", "chunked") || head.get("content-length").is_some_and(|v| v.parse::<usize>().is_ok());
    if framed || to_eof {
        stream_body(r, head, &mut |b| {
            body.extend_from_slice(b);
            Ok(())
        })?;
    }
    Ok(body)
}

/// A body as its head frames it (chunked, a length, or the rest of the stream),
/// handed to `each` piece by piece as it arrives rather than once it has all come.
fn stream_body(r: &mut impl BufRead, head: &Head, each: &mut impl FnMut(&[u8]) -> std::io::Result<()>) -> std::io::Result<()> {
    if head.has_token("transfer-encoding", "chunked") {
        loop {
            let mut size = String::new();
            r.read_line(&mut size)?;
            let n = usize::from_str_radix(size.trim().split(';').next().unwrap_or(""), 16)
                .map_err(|_| std::io::Error::other("bad chunk"))?;
            if n == 0 {
                // Trailers, then the blank line.
                loop {
                    let mut t = String::new();
                    if r.read_line(&mut t)? == 0 || t.trim().is_empty() {
                        break;
                    }
                }
                return Ok(());
            }
            copy_out(r, Some(n), each)?;
            let mut crlf = [0u8; 2];
            r.read_exact(&mut crlf)?;
        }
    }
    copy_out(r, head.get("content-length").and_then(|v| v.parse::<usize>().ok()), each)
}

/// `left` bytes of `r` (all of it, when None) to `each`, a read at a time.
fn copy_out(r: &mut impl Read, mut left: Option<usize>, each: &mut impl FnMut(&[u8]) -> std::io::Result<()>) -> std::io::Result<()> {
    let mut buf = [0u8; 16 * 1024];
    loop {
        let want = left.map_or(buf.len(), |n| n.min(buf.len()));
        if want == 0 {
            return Ok(());
        }
        let n = r.read(&mut buf[..want])?;
        if n == 0 {
            return if left.is_some() { Err(std::io::ErrorKind::UnexpectedEof.into()) } else { Ok(()) };
        }
        each(&buf[..n])?;
        if let Some(l) = left.as_mut() {
            *l -= n;
        }
    }
}

pub(crate) fn respond(w: &mut impl Write, status: &str, kind: &str, body: &[u8], extra: &[(&str, &str)]) -> std::io::Result<()> {
    let mut head = format!("HTTP/1.1 {status}\r\nContent-Type: {kind}\r\nContent-Length: {}\r\nConnection: close\r\n", body.len());
    for (k, v) in extra {
        head.push_str(&format!("{k}: {v}\r\n"));
    }
    head.push_str("\r\n");
    w.write_all(head.as_bytes())?;
    w.write_all(body)?;
    w.flush()
}

/// Headers that belong to one hop, not to the message: each side of the proxy
/// sets its own.
fn hop(name: &str) -> bool {
    ["connection", "keep-alive", "proxy-connection", "te", "trailer", "upgrade", "transfer-encoding"]
        .iter()
        .any(|h| name.eq_ignore_ascii_case(h))
}

fn write_head(w: &mut impl Write, line: &str, headers: &[(String, String)]) -> std::io::Result<()> {
    let mut out = format!("{line}\r\n");
    for (k, v) in headers {
        out.push_str(&format!("{k}: {v}\r\n"));
    }
    out.push_str("\r\n");
    w.write_all(out.as_bytes())
}

/// One request from the frame, passed to the dev server and its answer back.
fn serve(client: TcpStream, to: &Upstream, port: u16) -> std::io::Result<()> {
    let mut from = BufReader::new(client.try_clone()?);
    let mut client = client;
    let req = read_head(&mut from)?;
    // Only ever addressed as the loopback: the dev server is told it is asked for
    // as itself, so a page that rebinds a name of its own to here would get past
    // the dev server's own check of who is asking.
    if !req.get("host").is_some_and(loopback) {
        return respond(&mut client, "403 Forbidden", "text/plain", b"", &[]);
    }
    let here = format!("http://localhost:{port}");
    let there = to.origin();
    let swap = |v: &str| match v.strip_prefix(&here) {
        Some(rest) => format!("{there}{rest}"),
        None => v.to_string(),
    };

    let Ok(mut server) = TcpStream::connect((to.host.as_str(), to.port)) else {
        return respond(&mut client, "502 Bad Gateway", "text/html; charset=utf-8", waiting(&there).as_bytes(), &[]);
    };

    // The dev server sees itself asked for, by its own origin: Vite checks the
    // host, Next.js the origin of its own dev requests.
    let upgrade = req.has_token("connection", "upgrade") && req.get("upgrade").is_some();
    let mut headers: Vec<(String, String)> = req
        .headers
        .iter()
        // The body's length is said again below, once it is read: a server
        // turns away a request that says it twice.
        .filter(|(k, _)| {
            !k.eq_ignore_ascii_case("host") && !k.eq_ignore_ascii_case("accept-encoding") && (upgrade || (!hop(k) && !k.eq_ignore_ascii_case("content-length")))
        })
        .map(|(k, v)| match k.to_ascii_lowercase().as_str() {
            "origin" | "referer" => (k.clone(), swap(v)),
            _ => (k.clone(), v.clone()),
        })
        .collect();
    headers.insert(0, ("Host".into(), to.authority()));

    if upgrade {
        // Hot reload: the handshake goes through as asked, then the two
        // streams are joined until either side hangs up.
        write_head(&mut server, &req.line, &headers)?;
        server.write_all(from.buffer())?;
        let mut up = server.try_clone()?;
        let mut down = client.try_clone()?;
        let mut inner = from.into_inner();
        let a = std::thread::spawn(move || {
            let _ = std::io::copy(&mut inner, &mut up);
            let _ = up.shutdown(Shutdown::Write);
        });
        let _ = std::io::copy(&mut server, &mut down);
        let _ = down.shutdown(Shutdown::Both);
        let _ = a.join();
        return Ok(());
    }

    let body = read_body(&mut from, &req, false)?;
    headers.push(("Accept-Encoding".into(), "identity".into()));
    headers.push(("Connection".into(), "close".into()));
    if !body.is_empty() || req.get("content-length").is_some() || req.has_token("transfer-encoding", "chunked") {
        headers.push(("Content-Length".into(), body.len().to_string()));
    }
    write_head(&mut server, &req.line, &headers)?;
    server.write_all(&body)?;
    server.flush()?;

    let mut back = BufReader::new(server);
    let res = read_head(&mut back)?;
    let ok = res.line.split_whitespace().nth(1) == Some("200");
    let html = res.get("content-type").is_some_and(|t| t.to_ascii_lowercase().starts_with("text/html"));
    let encoded = res.get("content-encoding").is_some_and(|e| !e.eq_ignore_ascii_case("identity"));
    let inject = req.line.starts_with("GET ") && ok && html && !encoded;

    // Framing is this proxy's when the page is rewritten; otherwise the
    // server's own, copied as it is. The frame may always be framed.
    let headers: Vec<(String, String)> = res
        .headers
        .iter()
        .filter(|(k, _)| {
            let k = k.to_ascii_lowercase();
            k != "x-frame-options"
                && k != "content-security-policy"
                && k != "connection"
                && k != "keep-alive"
                && !(inject && (k == "content-length" || k == "transfer-encoding"))
        })
        .map(|(k, v)| match k.to_ascii_lowercase().as_str() {
            "location" => (k.clone(), v.strip_prefix(&there).map_or_else(|| v.clone(), |rest| format!("{here}{rest}"))),
            _ => (k.clone(), v.clone()),
        })
        .chain(std::iter::once(("Connection".to_string(), "close".to_string())))
        .collect();

    if inject {
        // The page goes on as it arrives: a dev server streams it, each part as it
        // is ready, and held whole the frame would show nothing until the slowest
        // had come. Only its start waits, until the head the agent goes in has
        // come. Its length is no longer the server's, so the close ends it.
        let mut headers = headers;
        headers.push(("Cache-Control".into(), "no-store".into()));
        write_head(&mut client, &res.line, &headers)?;
        let mut start = Some(Vec::new());
        stream_body(&mut back, &res, &mut |b| {
            if let Some(held) = start.as_mut() {
                held.extend_from_slice(b);
                if after_tag(&held.to_ascii_lowercase(), b"<head").is_none() && held.len() < HOLD {
                    return Ok(());
                }
                let page = with_agent(held);
                start = None;
                client.write_all(&page)?;
            } else {
                client.write_all(b)?;
            }
            client.flush()
        })?;
        if let Some(held) = start {
            client.write_all(&with_agent(&held))?;
        }
    } else {
        write_head(&mut client, &res.line, &headers)?;
        client.write_all(back.buffer())?;
        let mut rest = back.into_inner();
        // Copied as it arrives, so a stream of events is not held back.
        let mut buf = [0u8; 16 * 1024];
        loop {
            match rest.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    client.write_all(&buf[..n])?;
                    client.flush()?;
                }
            }
        }
    }
    client.flush()?;
    let _ = client.shutdown(Shutdown::Both);
    Ok(())
}

/// A Host naming this machine, with any port: `localhost` or a name under it
/// (which no public DNS can answer for), `127.0.0.1`, `[::1]`.
fn loopback(host: &str) -> bool {
    let name = match host.rsplit_once(':') {
        Some((name, port)) if port.bytes().all(|b| b.is_ascii_digit()) => name,
        _ => host,
    }
    .to_ascii_lowercase();
    name == "localhost" || name.ends_with(".localhost") || name == "127.0.0.1" || name == "[::1]"
}

/// The agent, first thing in the page's head, so it hears the page's own
/// console from the start. It takes itself out of the page as it runs: React
/// hydrates a server-rendered head in order, and would read a script left
/// there as the page's own first one, and call the page mismatched.
fn with_agent(page: &[u8]) -> Vec<u8> {
    let script = format!("<script data-blueprint-agent>document.currentScript.remove();\n{AGENT}</script>");
    let lower = page.to_ascii_lowercase();
    let at = after_tag(&lower, b"<head").or_else(|| after_tag(&lower, b"<html")).or_else(|| after_tag(&lower, b"<!doctype")).unwrap_or(0);
    let mut out = Vec::with_capacity(page.len() + script.len());
    out.extend_from_slice(&page[..at]);
    out.extend_from_slice(script.as_bytes());
    out.extend_from_slice(&page[at..]);
    out
}

/// How much of a page's start is held for its head: a page with none by then
/// gets the agent where with_agent can put it, and the rest is passed on.
const HOLD: usize = 64 * 1024;

/// Just past the end of the first `tag` in `lower` (a lowercased page), if it has come.
fn after_tag(lower: &[u8], tag: &[u8]) -> Option<usize> {
    let at = lower.windows(tag.len()).position(|w| w == tag)?;
    lower[at..].iter().position(|&c| c == b'>').map(|end| at + end + 1)
}

/// What the frame shows while the dev server is not answering: it tries again
/// every second, so a server that restarts comes back by itself. It tells the
/// tab each time, which goes back to the dev server if it was pointed at
/// another that has stopped.
fn waiting(origin: &str) -> String {
    format!(
        // A server that stopped never answers, so the page says where to see why.
        r#"<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="1"><title>Waiting</title><script>window.__blueprint&&__blueprint.down()</script><body style="font:13px/1.6 -apple-system,system-ui,sans-serif;color:#85858e;display:grid;place-items:center;height:100vh;margin:0;text-align:center"><div>Waiting for {origin}…<br>If the dev server stopped, <b style="font-weight:500">Server</b> above shows its terminal.</div></body>"#
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_the_addresses_dev_servers_print() {
        let u = Upstream::parse("http://localhost:5173/").unwrap();
        assert_eq!((u.host.as_str(), u.port), ("localhost", 5173));
        assert_eq!(Upstream::parse("0.0.0.0:3000").unwrap().authority(), "127.0.0.1:3000");
        assert_eq!(Upstream::parse("http://[::1]:8080/x?y").unwrap().authority(), "[::1]:8080");
        assert!(Upstream::parse("http://localhost/").is_none());
    }

    #[test]
    fn the_agent_goes_first_in_the_head() {
        let page = with_agent(b"<!DOCTYPE html><html lang=en><HEAD><title>x</title></head></html>");
        let page = String::from_utf8(page).unwrap();
        assert!(page.starts_with("<!DOCTYPE html><html lang=en><HEAD><script data-blueprint-agent>"));
        assert!(page.ends_with("<title>x</title></head></html>"));
        // A fragment with no head still gets it.
        assert!(String::from_utf8(with_agent(b"<p>hi")).unwrap().starts_with("<script"));
    }

    /// A dev server that answers once, as told.
    fn server(reply: &'static [u8]) -> (u16, std::thread::JoinHandle<String>) {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        let t = std::thread::spawn(move || {
            let (s, _) = l.accept().unwrap();
            let mut r = BufReader::new(s.try_clone().unwrap());
            let head = read_head(&mut r).unwrap();
            let mut s = s;
            s.write_all(reply).unwrap();
            format!("{}\n{}", head.line, head.headers.iter().map(|(k, v)| format!("{k}: {v}")).collect::<Vec<_>>().join("\n"))
        });
        (port, t)
    }

    fn through(port: u16, request: &str) -> String {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let me = l.local_addr().unwrap().port();
        let mut c = TcpStream::connect(("127.0.0.1", me)).unwrap();
        let (conn, _) = l.accept().unwrap();
        let to = Upstream { host: "127.0.0.1".into(), port };
        let h = std::thread::spawn(move || serve(conn, &to, me).unwrap());
        c.write_all(request.replace("{me}", &me.to_string()).as_bytes()).unwrap();
        let mut out = String::new();
        c.read_to_string(&mut out).unwrap();
        h.join().unwrap();
        out
    }

    #[test]
    fn a_page_gets_the_agent_and_can_be_framed() {
        let (port, seen) = server(
            b"HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nX-Frame-Options: DENY\r\nTransfer-Encoding: chunked\r\n\r\n6\r\n<head>\r\n7\r\n</head>\r\n0\r\n\r\n",
        );
        let out = through(port, "GET / HTTP/1.1\r\nHost: localhost:{me}\r\nOrigin: http://localhost:{me}\r\nAccept-Encoding: gzip\r\n\r\n");
        assert!(out.contains("<head><script data-blueprint-agent>"));
        assert!(out.ends_with("</head>"));
        assert!(!out.to_ascii_lowercase().contains("x-frame-options"));
        assert!(!out.to_ascii_lowercase().contains("chunked"));
        // The server was asked as itself, for plain bytes.
        let seen = seen.join().unwrap();
        assert!(seen.contains(&format!("Host: 127.0.0.1:{port}")));
        assert!(seen.contains(&format!("Origin: http://127.0.0.1:{port}")));
        assert!(seen.contains("Accept-Encoding: identity") && !seen.contains("gzip"));
    }

    /// A dev server streams a page: its head at once, the rest as each part of
    /// it is ready. The frame starts on the head without waiting for the rest.
    #[test]
    fn a_page_is_passed_on_as_it_arrives() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        std::thread::spawn(move || {
            let (s, _) = l.accept().unwrap();
            let _ = read_head(&mut BufReader::new(s.try_clone().unwrap())).unwrap();
            let mut s = s;
            s.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nTransfer-Encoding: chunked\r\n\r\n16\r\n<html><head></head><p>\r\n").unwrap();
            s.flush().unwrap();
            std::thread::sleep(std::time::Duration::from_millis(1500));
            s.write_all(b"5\r\nlater\r\n0\r\n\r\n").unwrap();
        });
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let me = l.local_addr().unwrap().port();
        let mut c = TcpStream::connect(("127.0.0.1", me)).unwrap();
        let (conn, _) = l.accept().unwrap();
        let to = Upstream { host: "127.0.0.1".into(), port };
        let h = std::thread::spawn(move || serve(conn, &to, me).unwrap());
        c.write_all(b"GET / HTTP/1.1\r\nHost: localhost\r\n\r\n").unwrap();
        let t0 = std::time::Instant::now();
        let mut first = String::new();
        let mut r = BufReader::new(c);
        while !first.contains("<p>") {
            let mut buf = [0u8; 4096];
            let n = r.read(&mut buf).unwrap();
            assert!(n > 0, "the page ended before its start came");
            first.push_str(&String::from_utf8_lossy(&buf[..n]));
        }
        assert!(t0.elapsed().as_millis() < 1000, "the page's start waited {} ms for its end", t0.elapsed().as_millis());
        assert!(first.contains("<head><script data-blueprint-agent>"));
        let mut rest = String::new();
        r.read_to_string(&mut rest).unwrap();
        h.join().unwrap();
        assert!(format!("{first}{rest}").ends_with("<p>later"));
    }

    #[test]
    fn everything_else_is_copied_through() {
        let (port, _) = server(b"HTTP/1.1 302 Found\r\nLocation: http://127.0.0.1:PORT/next\r\nContent-Length: 2\r\n\r\nok");
        let out = through(port, "GET /a.js HTTP/1.1\r\nHost: localhost:{me}\r\n\r\n");
        assert!(out.starts_with("HTTP/1.1 302 Found"));
        assert!(out.ends_with("\r\n\r\nok"));
        assert!(!out.contains("blueprint-agent"));
    }

    #[test]
    fn a_body_is_sent_on_with_its_length_said_once() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        let seen = std::thread::spawn(move || {
            let (s, _) = l.accept().unwrap();
            let mut r = BufReader::new(s.try_clone().unwrap());
            let head = read_head(&mut r).unwrap();
            let body = read_body(&mut r, &head, false).unwrap();
            let mut s = s;
            s.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n").unwrap();
            (head.headers.iter().filter(|(k, _)| k.eq_ignore_ascii_case("content-length")).count(), body)
        });
        through(port, "POST /api HTTP/1.1\r\nHost: 127.0.0.1:{me}\r\nContent-Length: 4\r\n\r\nping");
        assert_eq!(seen.join().unwrap(), (1, b"ping".to_vec()));
    }

    #[test]
    fn a_server_that_is_down_is_waited_for() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        drop(l);
        let out = through(port, "GET / HTTP/1.1\r\nHost: [::1]:{me}\r\n\r\n");
        assert!(out.starts_with("HTTP/1.1 502"));
        assert!(out.contains("http-equiv=\"refresh\""));
    }

    #[test]
    fn a_name_rebound_to_the_loopback_is_turned_away() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        let out = through(port, "GET / HTTP/1.1\r\nHost: evil.example:{me}\r\n\r\n");
        assert!(out.starts_with("HTTP/1.1 403"));
        assert!(through(port, "GET / HTTP/1.1\r\n\r\n").starts_with("HTTP/1.1 403"));
        assert!(loopback("app.localhost:3000") && loopback("LOCALHOST") && !loopback("localhost.evil.io:80") && !loopback("127.0.0.1.nip.io"));
    }
}

app/src-tauri/src/proc.rs:
//! Programs the app runs behind the scenes: git, `where`, `adb`, Claude's
//! `--version`. On Windows a console program started from a windowed app
//! opens a console window of its own, which flashes on screen for every call;
//! `command` starts it without one.

use std::ffi::OsStr;
use std::process::Command;

#[cfg(windows)]
const CREATE_NO_WINDOW: u32 = 0x0800_0000;

pub fn command(program: impl AsRef<OsStr>) -> Command {
    #[allow(unused_mut)]
    let mut cmd = Command::new(program);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(CREATE_NO_WINDOW);
    }
    cmd
}

/// The user's home folder: `HOME` where there is one, else Windows' own.
pub fn home() -> Option<std::path::PathBuf> {
    std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE")).map(Into::into)
}

/// Which `program`s on PATH Windows would run, by `where`, in its order.
#[cfg(windows)]
pub fn where_is(program: &str) -> Vec<std::path::PathBuf> {
    command("where")
        .arg(program)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).lines().map(|l| l.trim().into()).collect())
        .unwrap_or_default()
}

app/src-tauri/src/pty.rs:
//! The workspace's tabs. Each one is a real pty running the user's shell in the
//! open blueprint's checkout; its output streams to the webview over a `Channel` as
//! raw bytes (xterm decodes UTF-8 itself, so a character split across two
//! reads is fine), and one final JSON `{"exit": code}` says it ended.
//!
//! A tab can start Claude Code in the shell first (claude.rs), and Claude can
//! be started again in any tab. Every tab owns a context queue for it,
//! removed with the tab.

use portable_pty::{native_pty_system, Child, CommandBuilder, MasterPty, PtySize};
use std::collections::HashMap;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::{Arc, Mutex};
use tauri::ipc::{Channel, InvokeResponseBody};

use crate::claude;

struct Pty {
    master: Box<dyn MasterPty + Send>,
    writer: Box<dyn Write + Send>,
    child: Box<dyn Child + Send + Sync>,
    /// Where picks wait for the next prompt to Claude in this tab.
    context: PathBuf,
    #[cfg(windows)]
    job: Option<Job>,
}

impl Pty {
    fn new(master: Box<dyn MasterPty + Send>, writer: Box<dyn Write + Send>, child: Box<dyn Child + Send + Sync>, context: PathBuf) -> Self {
        #[cfg(windows)]
        let job = child.as_raw_handle().and_then(Job::holding);
        Pty {
            master,
            writer,
            child,
            context,
            #[cfg(windows)]
            job,
        }
    }

    /// Blocks until the console is gone, so never on the main thread.
    fn end(mut self) {
        #[cfg(windows)]
        drop(self.job.take());
        let _ = self.child.kill();
        // A Windows console opens by asking the terminal where its cursor is
        // (portable-pty inherits the cursor), and does nothing, closing included,
        // until it is told. A tab ended before xterm answered would never close;
        // this answers for it, to a console with no program left to read it.
        #[cfg(windows)]
        let _ = self.writer.write_all(b"[1;1R").and_then(|()| self.writer.flush());
        claude::forget(&self.context);
    }

    /// Ends `ptys` on a thread of their own.
    fn end_apart(ptys: Vec<Pty>) {
        if !ptys.is_empty() {
            std::thread::spawn(move || ptys.into_iter().for_each(Pty::end));
        }
    }
}

/// Everything a tab's shell started, Claude's own processes too. A Windows
/// console stays open while any program is still attached to it, and closing
/// it waits for that; so the whole tree goes with the shell, and with the app
/// should it die.
#[cfg(windows)]
struct Job(windows_sys::Win32::Foundation::HANDLE);

#[cfg(windows)]
unsafe impl Send for Job {}
#[cfg(windows)]
unsafe impl Sync for Job {}

#[cfg(windows)]
impl Job {
    fn holding(process: std::os::windows::io::RawHandle) -> Option<Job> {
        use windows_sys::Win32::System::JobObjects::*;
        unsafe {
            let job = Job(CreateJobObjectW(std::ptr::null(), std::ptr::null()));
            if job.0.is_null() {
                return None;
            }
            let mut limits: JOBOBJECT_EXTENDED_LIMIT_INFORMATION = std::mem::zeroed();
            limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
            let set = SetInformationJobObject(
                job.0,
                JobObjectExtendedLimitInformation,
                &limits as *const _ as *const _,
                std::mem::size_of_val(&limits) as u32,
            );
            (set != 0 && AssignProcessToJobObject(job.0, process as _) != 0).then_some(job)
        }
    }
}

#[cfg(windows)]
impl Drop for Job {
    fn drop(&mut self) {
        unsafe { windows_sys::Win32::Foundation::CloseHandle(self.0) };
    }
}

#[derive(Default)]
pub struct Ptys {
    next: AtomicU32,
    open: Arc<Mutex<HashMap<u32, Pty>>>,
}

impl Ptys {
    /// Every shell still running, ended. Called when the app exits, so
    /// closing the window never leaves a shell behind.
    pub fn kill_all(&self) {
        let all = self.open.lock().unwrap().drain().map(|(_, p)| p).collect();
        Pty::end_apart(all);
    }
}

fn size(cols: u16, rows: u16) -> PtySize {
    PtySize { rows: rows.max(1), cols: cols.max(1), pixel_width: 0, pixel_height: 0 }
}

fn shell() -> String {
    #[cfg(windows)]
    return std::env::var("COMSPEC").unwrap_or_else(|_| "powershell.exe".into());
    #[cfg(not(windows))]
    return std::env::var("SHELL").unwrap_or_else(|_| "/bin/bash".into());
}

/// Claude first in the tab, resuming `resume` when the tab reopens a conversation.
fn start(cmd: &mut CommandBuilder, program: &str, name: &str, login: bool, context: &std::path::Path, resume: Option<&str>) -> std::io::Result<()> {
    if let Some(id) = resume {
        claude::resuming(context, id)?;
    }
    if cfg!(unix) {
        cmd.args(["-c", if login { r#""$BLUEPRINT_LAUNCHER"; exec "$SHELL" -l"# } else { r#""$BLUEPRINT_LAUNCHER"; exec "$SHELL""# }]);
        cmd.env("SHELL", program);
    } else if name.eq_ignore_ascii_case("cmd") {
        cmd.args(["/k", "blueprint-claude"]);
    } else {
        cmd.args(["-NoExit", "-Command", "blueprint-claude"]);
    }
    Ok(())
}

/// What the tab is called: the shell's own name, `zsh` for `/usr/bin/zsh`.
#[derive(serde::Serialize)]
pub struct Spawned {
    id: u32,
    shell: String,
}

/// `outline` is the open blueprint's sections, so Claude in this tab can name one it
/// was not handed (claude.rs's LIST).
#[tauri::command]
pub fn pty_spawn(
    cols: u16,
    rows: u16,
    on_data: Channel<InvokeResponseBody>,
    launch: Option<claude::Launch>,
    start_claude: bool,
    resume: Option<String>,
    cwd: Option<String>,
    outline: Option<String>,
    ptys: tauri::State<Ptys>,
) -> Result<Spawned, String> {
    let pair = native_pty_system().openpty(size(cols, rows)).map_err(|e| e.to_string())?;
    let id = ptys.next.fetch_add(1, Ordering::Relaxed) + 1;
    let context = claude::queue(id);
    let program = shell();
    let name = std::path::Path::new(&program)
        .file_stem()
        .map_or_else(|| program.clone(), |s| s.to_string_lossy().into_owned());
    let mut cmd = CommandBuilder::new(&program);
    // A Mac app opened from Finder gets a bare PATH; Terminal.app's shells are
    // login shells, and only those read /etc/zprofile (path_helper, which adds
    // /usr/local/bin) and ~/.zprofile (Homebrew's shellenv).
    let login = cfg!(target_os = "macos");
    if login {
        cmd.arg("-l");
    }
    // With Claude found, the launcher works in this tab; asked to, Claude runs
    // first and the user's ordinary interactive shell takes over when it exits.
    // Without Claude, the tab still runs the other agents through their launchers (agents.rs).
    if launch.is_none() {
        claude::prepare_tab(&mut cmd, &context, outline.as_deref(), id).map_err(|e| e.to_string())?;
    }
    if let Some(launch) = &launch {
        claude::prepare(&mut cmd, launch, &context, outline.as_deref(), id).map_err(|e| e.to_string())?;
        if start_claude {
            start(&mut cmd, &program, &name, login, &context, resume.as_deref()).map_err(|e| e.to_string())?;
        }
    }
    // The checkout the page named, if it is really there; home otherwise.
    let dir = cwd.map(PathBuf::from).filter(|d| d.is_dir());
    if let Some(dir) = dir.or_else(crate::proc::home) {
        cmd.cwd(dir);
    }
    // An app started from a Claude Code session would hand down its markers,
    // and a Claude in a tab would then take itself for a child of that one.
    cmd.env_remove("CLAUDECODE");
    cmd.env_remove("CLAUDE_CODE_CHILD_SESSION");
    cmd.env("TERM", "xterm-256color");
    cmd.env("COLORTERM", "truecolor");
    let child = pair.slave.spawn_command(cmd).map_err(|e| {
        // A tab that never started is never closed, which is what clears its files, the credit among them.
        claude::forget(&context);
        e.to_string()
    })?;
    // The slave end belongs to the shell now; holding it here would keep the
    // reader below from ever seeing EOF.
    drop(pair.slave);

    let mut reader = pair.master.try_clone_reader().map_err(|e| e.to_string())?;
    let writer = pair.master.take_writer().map_err(|e| e.to_string())?;
    ptys.open.lock().unwrap().insert(id, Pty::new(pair.master, writer, child, context));

    let open = ptys.open.clone();
    // Reads go to a second thread that sends them on. Claude Code redraws in
    // many small writes; whatever piles up while one send is crossing to the
    // webview goes in the next as one message, rather than a message per read.
    let (tx, rx) = std::sync::mpsc::channel::<Vec<u8>>();
    std::thread::spawn(move || {
        let mut buf = [0u8; 16 * 1024];
        loop {
            match reader.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    if tx.send(buf[..n].to_vec()).is_err() {
                        break;
                    }
                }
            }
        }
    });
    std::thread::spawn(move || {
        while let Ok(mut chunk) = rx.recv() {
            while let Ok(more) = rx.try_recv() {
                chunk.extend_from_slice(&more);
            }
            if on_data.send(InvokeResponseBody::Raw(chunk)).is_err() {
                break;
            }
        }
        // Gone from the blueprint already if it was killed from the UI.
        let ended = open.lock().unwrap().remove(&id);
        let code = ended
            .and_then(|mut p| {
                claude::forget(&p.context);
                p.child.wait().ok()
            })
            .map_or(0, |s| s.exit_code());
        let _ = on_data.send(InvokeResponseBody::Json(format!(r#"{{"exit":{code}}}"#)));
    });
    Ok(Spawned { id, shell: name })
}

fn with<T>(ptys: &Ptys, id: u32, f: impl FnOnce(&mut Pty) -> std::io::Result<T>) -> Result<T, String> {
    let mut open = ptys.open.lock().unwrap();
    let p = open.get_mut(&id).ok_or("no such terminal")?;
    f(p).map_err(|e| e.to_string())
}

#[tauri::command]
pub fn pty_write(id: u32, data: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    with(&ptys, id, |p| {
        p.writer.write_all(data.as_bytes())?;
        p.writer.flush()
    })
}

#[tauri::command]
pub fn pty_resize(id: u32, cols: u16, rows: u16, ptys: tauri::State<Ptys>) -> Result<(), String> {
    with(&ptys, id, |p| p.master.resize(size(cols, rows)).map_err(std::io::Error::other))
}

#[tauri::command]
pub fn pty_kill(id: u32, ptys: tauri::State<Ptys>) -> Result<(), String> {
    let ended = ptys.open.lock().unwrap().remove(&id);
    Pty::end_apart(ended.into_iter().collect());
    Ok(())
}

/// Which of `names` the user's shell can run, found the way their own
/// terminal finds them: an interactive shell, so PATH set in its rc counts.
/// Only plain names are asked about, never anything the shell would parse.
fn which(names: Vec<String>) -> Vec<String> {
    let names: Vec<String> = names
        .into_iter()
        .filter(|n| !n.is_empty() && n.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'))
        .collect();
    if names.is_empty() {
        return Vec::new();
    }
    runnable(names)
}

/// Windows' own lookup: PATH and PATHEXT, as cmd and PowerShell use them.
#[cfg(windows)]
fn runnable(names: Vec<String>) -> Vec<String> {
    names.into_iter().filter(|n| !crate::proc::where_is(n).is_empty()).collect()
}

#[cfg(not(windows))]
fn runnable(names: Vec<String>) -> Vec<String> {
    let script = names
        .iter()
        .map(|n| format!("command -v {n} >/dev/null 2>&1 && echo {n}"))
        .collect::<Vec<_>>()
        .join("; ");
    let out = std::process::Command::new(shell())
        .args(["-ic", &script])
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output();
    let text = out.map(|o| String::from_utf8_lossy(&o.stdout).into_owned()).unwrap_or_default();
    // An rc may print its own lines too; only exact names count.
    names.into_iter().filter(|n| text.lines().any(|l| l.trim() == n)).collect()
}

/// The coding agents a tab can start besides Claude. Async so the shell's
/// start-up never blocks the window.
#[tauri::command]
pub async fn pty_which(names: Vec<String>) -> Vec<String> {
    which(names)
}

/// A tab's queue.
fn queue_of(ptys: &Ptys, id: u32) -> Result<PathBuf, String> {
    Ok(ptys.open.lock().unwrap().get(&id).ok_or("no such terminal")?.context.clone())
}

/// What is in front in a tab: Claude through the launcher (able to take
/// context), or some other program the shell started, or the shell itself,
/// waiting at its prompt.
#[derive(serde::Serialize)]
pub struct State {
    claude: bool,
    /// Which agent's launcher is in front: `claude`, or one of agents.rs's.
    agent: Option<String>,
    busy: bool,
    /// What Claude is doing: `working`, `waiting` for the user, or `done`.
    status: Option<String>,
    /// Claude finished a turn the blueprint should follow; reported once.
    turn: Option<claude::Turn>,
    /// What Claude asked the app to show — a section, a diff — taken mid-turn
    /// so the user is looking at it while the answer streams; reported once.
    acts: Vec<claude::Act>,
    /// A plan Claude is waiting to have accepted; reported once.
    plan: Option<claude::Plan>,
    /// The plan was accepted; reported once.
    approved: bool,
    /// The accepted plan's steps as Claude has marked them; every poll.
    steps: Vec<claude::Step>,
    /// The conversation Claude is having, to resume it after a restart.
    session: Option<String>,
}

#[tauri::command]
pub fn pty_state(id: u32, ptys: tauri::State<Ptys>) -> Result<State, String> {
    let open = ptys.open.lock().unwrap();
    let p = open.get(&id).ok_or("no such terminal")?;
    // An interactive shell gives each command its own process group, and
    // hands it the terminal: someone else leading the foreground group means
    // a program is running.
    #[cfg(unix)]
    let busy = match (p.master.process_group_leader(), p.child.process_id()) {
        (Some(front), Some(shell)) => front as u32 != shell,
        _ => false,
    };
    #[cfg(not(unix))]
    let busy = false;
    Ok(State {
        claude: claude::running(&p.context),
        agent: claude::agent_of(&p.context),
        busy,
        status: claude::status_of(&p.context),
        turn: claude::take_turn(&p.context),
        acts: claude::take_acts(&p.context),
        plan: claude::take_plan(&p.context),
        approved: claude::take_approved(&p.context),
        steps: claude::steps_of(&p.context),
        session: claude::session_of(&p.context),
    })
}

/// Queues a section for the next prompt to Claude in this tab.
#[tauri::command]
pub fn context_add(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::append(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// Rewrites what is still waiting, after a pick is taken back. Empty clears it.
#[tauri::command]
pub fn context_set(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::replace(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// Where the user is on the blueprint, for every prompt to say (claude::place).
#[tauri::command]
pub fn context_where(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::place(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// True while something queued has not gone out with a prompt yet.
#[tauri::command]
pub fn context_pending(id: u32, ptys: tauri::State<Ptys>) -> Result<bool, String> {
    Ok(claude::pending(&queue_of(&ptys, id)?))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_tab_ended_while_a_program_runs_in_it_lets_go_at_once() {
        let pair = native_pty_system().openpty(size(80, 24)).unwrap();
        let mut cmd = CommandBuilder::new(shell());
        #[cfg(windows)]
        cmd.args(["/k", "ping", "-t", "127.0.0.1"]);
        #[cfg(unix)]
        cmd.args(["-c", "sleep 600"]);
        let child = pair.slave.spawn_command(cmd).unwrap();
        drop(pair.slave);
        let mut reader = pair.master.try_clone_reader().unwrap();
        std::thread::spawn(move || {
            let mut buf = [0u8; 4096];
            while reader.read(&mut buf).is_ok_and(|n| n > 0) {}
        });
        let writer = pair.master.take_writer().unwrap();
        let pty = Pty::new(pair.master, writer, child, std::env::temp_dir().join("blueprint-test-context.md"));
        std::thread::sleep(std::time::Duration::from_secs(2));
        let (done, ended) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            pty.end();
            let _ = done.send(());
        });
        assert!(ended.recv_timeout(std::time::Duration::from_secs(10)).is_ok(), "ending the shell hung");
    }

    #[test]
    fn a_reopened_tab_resumes_its_conversation_in_every_shell() {
        for name in ["sh", "cmd", "powershell"] {
            let context = std::env::temp_dir().join("blueprint").join(format!("context-test-resume-{name}.md"));
            let _ = std::fs::remove_file(context.with_extension("md.resume"));
            let mut cmd = CommandBuilder::new(name);
            start(&mut cmd, name, name, false, &context, Some("abc-1")).unwrap();
            assert_eq!(std::fs::read_to_string(context.with_extension("md.resume")).ok().as_deref(), Some("abc-1"), "{name}");
            assert_eq!(claude::session_of(&context).as_deref(), Some("abc-1"), "{name}");
            claude::forget(&context);
        }
    }

    #[cfg(unix)]
    #[test]
    fn which_finds_only_plain_names_the_shell_can_run() {
        let asked = ["sh", "surely-not-a-program-xyz", "sh; echo oops", ""].map(String::from).to_vec();
        assert_eq!(which(asked), vec!["sh".to_string()]);
    }
}

app/src-tauri/src/rename.rs:
//! The folders the app kept while it was called Bluprint (`dev.bluprint.app`):
//! its data, its webview's storage and its caches. Before the server or the
//! window opens, what each holds is merged into the folder of the same kind
//! under the new identifier. A file already in the new folder wins; what could
//! not move (a file held open) stays, and moves on a later launch.

use std::path::{Path, PathBuf};

const OLD: &str = "dev.bluprint.app";

/// The old app's own server snapshot (server.rs, scripts/install.sh): the
/// new install builds its own, so the old one is dropped, not merged.
const REBUILT: &[&str] = &["server", "server-next", "server.old"];

pub fn migrate(app: &tauri::AppHandle) {
    use tauri::Manager;
    // A Bluprint still open is writing to its folders; they move once it is closed.
    if std::net::TcpStream::connect_timeout(&([127, 0, 0, 1], crate::server::PORT).into(), std::time::Duration::from_millis(300)).is_ok() {
        return;
    }
    let p = app.path();
    let mut dirs: Vec<PathBuf> = [p.app_data_dir(), p.app_local_data_dir(), p.app_config_dir(), p.app_cache_dir()]
        .into_iter()
        .flatten()
        .collect();
    #[cfg(target_os = "macos")]
    if let Some(h) = crate::proc::home() {
        let id = &app.config().identifier;
        dirs.push(h.join("Library/WebKit").join(id));
        dirs.push(h.join("Library/HTTPStorages").join(id));
    }
    dirs.sort();
    dirs.dedup();
    for to in dirs {
        if let Some(from) = to.parent().map(|d| d.join(OLD)) {
            for name in REBUILT {
                let _ = std::fs::remove_dir_all(from.join(name));
            }
            merge(&from, &to);
        }
    }
}

/// Moves everything in `from` into `to`, folder into folder, and removes each
/// folder of `from` it empties.
fn merge(from: &Path, to: &Path) {
    let Ok(entries) = std::fs::read_dir(from) else { return };
    if std::fs::create_dir_all(to).is_err() {
        return;
    }
    for e in entries.flatten() {
        let dest = to.join(e.file_name());
        if !dest.exists() {
            let _ = std::fs::rename(e.path(), &dest);
        } else if dest.is_dir() && e.path().is_dir() {
            merge(&e.path(), &dest);
        }
    }
    let _ = std::fs::remove_dir(from);
}

#[cfg(test)]
mod tests {
    use super::merge;
    use std::fs;

    #[test]
    fn merges_folders_keeps_newer_and_leaves_conflicts() {
        let t = tempfile::tempdir().unwrap();
        let (old, new) = (t.path().join("old"), t.path().join("new"));
        fs::create_dir_all(old.join("projects/a")).unwrap();
        fs::create_dir_all(old.join("projects/b")).unwrap();
        fs::write(old.join("projects.json"), "old").unwrap();
        fs::write(old.join("projects/a/blueprint.json"), "a").unwrap();
        fs::write(old.join("projects/b/blueprint.json"), "b-old").unwrap();
        fs::create_dir_all(new.join("projects/b")).unwrap();
        fs::write(new.join("projects/b/blueprint.json"), "b-new").unwrap();

        merge(&old, &new);

        assert_eq!(fs::read_to_string(new.join("projects.json")).unwrap(), "old");
        assert_eq!(fs::read_to_string(new.join("projects/a/blueprint.json")).unwrap(), "a");
        assert_eq!(fs::read_to_string(new.join("projects/b/blueprint.json")).unwrap(), "b-new");
        assert!(old.join("projects/b/blueprint.json").exists());
        assert!(!old.join("projects/a").exists());

        fs::remove_file(old.join("projects/b/blueprint.json")).unwrap();
        merge(&old, &new);
        assert!(!old.exists());
    }

    #[test]
    fn a_missing_old_folder_is_nothing_to_do() {
        let t = tempfile::tempdir().unwrap();
        merge(&t.path().join("none"), &t.path().join("new"));
        assert!(!t.path().join("new").exists());
    }
}

app/src-tauri/src/server.rs:
//! The installed app's own server. `npm run app:install` copies `app/` into
//! `<app_data_dir>/server` and builds it there, so the Next server behind the
//! window is a snapshot that editing the checkout never touches. The app starts
//! it on launch and stops it on quit; `app:dev` never comes here.
//!
//! An app opened from Finder gets a bare PATH, so the install records the Node
//! and PATH of the shell that ran it in `env.json`, and the server (and the
//! git, claude and tsx it runs) sees what it would in a terminal.

use std::net::TcpStream;
use std::path::PathBuf;
use std::process::{Child, Stdio};
use std::sync::Mutex;
use std::time::{Duration, Instant};
use tauri::Manager;

/// Fixed in `tauri.conf.json`'s `frontendDist`; `app:dev` keeps 3000.
pub const PORT: u16 = 3123;

#[derive(Default)]
pub struct Server(Mutex<Option<Child>>);

#[derive(serde::Deserialize)]
struct Env {
    node: PathBuf,
    path: String,
}

fn up() -> bool {
    TcpStream::connect_timeout(&([127, 0, 0, 1], PORT).into(), Duration::from_millis(200)).is_ok()
}

/// Returns once the server answers. A server already answering is one a crashed
/// Blueprint left behind, and is used as it is.
pub fn start(app: &tauri::AppHandle) -> Result<(), String> {
    if up() {
        return Ok(());
    }
    let data = app.path().app_data_dir().map_err(|e| e.to_string())?;
    let dir = data.join("server");
    let env: Env = std::fs::read_to_string(dir.join("env.json"))
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .ok_or("Blueprint's server isn't installed. Run `npm run app:install` in the repo's app folder.")?;
    let log = std::fs::File::create(data.join("server.log")).map_err(|e| e.to_string())?;
    let child = crate::proc::command(&env.node)
        .arg(dir.join("node_modules/next/dist/bin/next"))
        .args(["start", "-p", &PORT.to_string(), "-H", "127.0.0.1"])
        .current_dir(&dir)
        .env("PATH", &env.path)
        .stdin(Stdio::null())
        .stdout(log.try_clone().map_err(|e| e.to_string())?)
        .stderr(log)
        .spawn()
        .map_err(|e| format!("Couldn't start {}: {e}", env.node.display()))?;
    *app.state::<Server>().0.lock().unwrap() = Some(child);
    let deadline = Instant::now() + Duration::from_secs(30);
    while Instant::now() < deadline {
        if up() {
            return Ok(());
        }
        if let Some(c) = app.state::<Server>().0.lock().unwrap().as_mut() {
            if let Ok(Some(status)) = c.try_wait() {
                return Err(format!("Blueprint's server exited ({status}). See {}.", data.join("server.log").display()));
            }
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    Err(format!("Blueprint's server didn't start in 30 s. See {}.", data.join("server.log").display()))
}

pub fn stop(app: &tauri::AppHandle) {
    if let Some(mut c) = app.state::<Server>().0.lock().unwrap().take() {
        let _ = c.kill();
        let _ = c.wait();
    }
}

app/src-tauri/src/signins.rs:
//! Sign-ins the preview keeps for pages from the web (browser.rs): a site the
//! user signed in to once opens signed in from then on, as in a browser. What
//! is kept is the site's own cookies, in WebKit's store; never a password,
//! which the user types into the page themselves (agent.js refuses to).
//!
//! There are two kinds of store. The shared one is WebKit's default, which
//! every project's preview uses, so a sign-in kept there (Instagram, YouTube)
//! works in all of them. And each project has one of its own, named by its
//! folder, for a sign-in the user keeps to that project only. Which sites go
//! in a project's store is listed in `sign-ins.json` in the app's data folder,
//! along with the shared ones, for settings to list: site names, nothing else.
//!
//! A project's store needs macOS 14; before that WebKit has only the shared one.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Mutex;
use tauri::{AppHandle, LogicalPosition, LogicalSize, Manager, Url, WebviewBuilder, WebviewUrl};

#[derive(Default, Serialize, Deserialize)]
pub struct Kept {
    #[serde(default)]
    global: Vec<String>,
    /// By project folder.
    #[serde(default)]
    projects: BTreeMap<String, Vec<String>>,
}

static FILE: Mutex<()> = Mutex::new(());
static NEXT: AtomicU32 = AtomicU32::new(1);

fn path(app: &AppHandle) -> Result<PathBuf, String> {
    app.path().app_data_dir().map(|d| d.join("sign-ins.json")).map_err(|e| e.to_string())
}

fn read(app: &AppHandle) -> Kept {
    path(app)
        .ok()
        .and_then(|p| std::fs::read(p).ok())
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default()
}

fn write(app: &AppHandle, kept: &Kept) -> Result<(), String> {
    let p = path(app)?;
    if let Some(dir) = p.parent() {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(p, serde_json::to_vec_pretty(kept).map_err(|e| e.to_string())?).map_err(|e| e.to_string())
}

/// A site as it is kept: `www.instagram.com` is `instagram.com`.
fn site_of(host: &str) -> String {
    host.trim_start_matches('.').trim_start_matches("www.").to_ascii_lowercase()
}

/// Whether a host is the site or one of its subdomains.
fn covers(site: &str, host: &str) -> bool {
    let host = site_of(host);
    host == site || host.ends_with(&format!(".{site}"))
}

/// A project's store, named by its folder: the same folder, the same store.
/// FNV-1a over 128 bits, marked as a UUID.
pub fn store_of(root: &str) -> [u8; 16] {
    let mut h: u128 = 0x6c62272e07bb014262b821756295c58d;
    for b in root.bytes() {
        h ^= b as u128;
        h = h.wrapping_mul(0x0000000001000000000000000000013B);
    }
    let mut id = h.to_be_bytes();
    id[6] = (id[6] & 0x0f) | 0x80;
    id[8] = (id[8] & 0x3f) | 0x80;
    id
}

/// Whether a page opens in the project's own store rather than the shared one.
#[tauri::command]
pub fn signin_project(app: AppHandle, root: String, url: String) -> bool {
    let Some(host) = Url::parse(&url).ok().and_then(|u| u.host_str().map(String::from)) else { return false };
    read(&app).projects.get(&root).is_some_and(|sites| sites.iter().any(|s| covers(s, &host)))
}

/// Keeps a site's sign-in for all projects, or for `root` only.
#[tauri::command]
pub fn signin_keep(app: AppHandle, root: String, site: String, project: bool) -> Result<(), String> {
    let _lock = FILE.lock().unwrap_or_else(|e| e.into_inner());
    let site = site_of(&site);
    let mut kept = read(&app);
    kept.global.retain(|s| *s != site);
    let mine = kept.projects.entry(root.clone()).or_default();
    mine.retain(|s| *s != site);
    if project {
        mine.push(site);
        mine.sort();
    } else {
        if mine.is_empty() {
            kept.projects.remove(&root);
        }
        kept.global.push(site);
        kept.global.sort();
    }
    write(&app, &kept)
}

#[tauri::command]
pub fn signin_list(app: AppHandle) -> Kept {
    read(&app)
}

/// Signs out of a site: its cookies are deleted from the store it was kept
/// in (the shared one when `root` is none), and it is no longer listed. A
/// project left with no sign-ins has its store removed.
#[tauri::command]
pub async fn signin_forget(app: AppHandle, root: Option<String>, site: String) -> Result<(), String> {
    let site = site_of(&site);
    clear(&app, root.as_deref().map(store_of), &site)?;
    let emptied = {
        let _lock = FILE.lock().unwrap_or_else(|e| e.into_inner());
        let mut kept = read(&app);
        let mut emptied = false;
        match &root {
            None => kept.global.retain(|s| *s != site),
            Some(r) => {
                if let Some(mine) = kept.projects.get_mut(r) {
                    mine.retain(|s| *s != site);
                    emptied = mine.is_empty();
                }
                if emptied {
                    kept.projects.remove(r);
                }
            }
        }
        write(&app, &kept)?;
        emptied
    };
    #[cfg(target_vendor = "apple")]
    if let (true, Some(r)) = (emptied, &root) {
        // Fails while a preview still has a page open in it; its cookies are gone either way.
        let _ = app.remove_data_store(store_of(r)).await;
    }
    #[cfg(not(target_vendor = "apple"))]
    let _ = emptied;
    Ok(())
}

/// A site's cookies deleted from a store, through a webview of that store
/// that nobody sees: a store is reached only through a webview of it.
fn clear(app: &AppHandle, store: Option<[u8; 16]>, site: &str) -> Result<(), String> {
    let window = app.get_window("main").ok_or("The window is gone.")?;
    let label = format!("forget-{}", NEXT.fetch_add(1, Ordering::Relaxed));
    let blank = Url::parse("about:blank").map_err(|e| e.to_string())?;
    let mut builder = WebviewBuilder::new(&label, WebviewUrl::External(blank));
    if let Some(id) = store {
        builder = builder.data_store_identifier(id);
    }
    let view = window
        .add_child(builder, LogicalPosition::new(0.0, 0.0), LogicalSize::new(1.0, 1.0))
        .map_err(|e| e.to_string())?;
    let _ = view.hide();
    let out = view.cookies().map_err(|e| e.to_string()).map(|all| {
        for c in all {
            if c.domain().is_some_and(|d| covers(site, d)) {
                let _ = view.delete_cookie(c);
            }
        }
    });
    let _ = view.close();
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_site_covers_its_subdomains_only() {
        assert!(covers("instagram.com", "www.instagram.com"));
        assert!(covers("instagram.com", ".instagram.com"));
        assert!(covers("instagram.com", "i.instagram.com"));
        assert!(!covers("instagram.com", "notinstagram.com"));
        assert!(!covers("instagram.com", "instagram.com.evil.io"));
    }

    #[test]
    fn a_folder_names_one_store() {
        assert_eq!(store_of("/a/b"), store_of("/a/b"));
        assert_ne!(store_of("/a/b"), store_of("/a/c"));
        assert_eq!(store_of("/a/b")[6] >> 4, 8);
    }
}

app/src-tauri/src/update.rs:
//! Swaps in the release the server staged in `<app_data_dir>/update` (app/scripts/update.mjs): its
//! server over `server/`, its app over this one. Done once Blueprint has quit, or as it starts if it
//! last ended without quitting, so neither is replaced while it runs. "Restart to update" quits,
//! swaps and opens the new one.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::OnceLock;
use std::time::Duration;

static EXE: OnceLock<PathBuf> = OnceLock::new();
static RELAUNCH: AtomicBool = AtomicBool::new(false);

/// Read before anything replaces it: Linux names a replaced executable "… (deleted)".
pub fn remember_exe() {
    if let Ok(p) = std::env::current_exe() {
        let _ = EXE.set(p);
    }
}

/// The app's data folder as Tauri's `app_data_dir` has it, for `--apply-update`, which runs without one.
pub fn data_dir() -> Option<PathBuf> {
    let base: PathBuf = if cfg!(target_os = "macos") {
        crate::proc::home()?.join("Library/Application Support")
    } else if cfg!(windows) {
        std::env::var_os("APPDATA")?.into()
    } else {
        std::env::var_os("XDG_DATA_HOME").map(PathBuf::from).or_else(|| crate::proc::home().map(|h| h.join(".local/share")))?
    };
    Some(base.join("dev.blueprint.app"))
}

/// The `.app` folder an executable runs from, on macOS.
fn bundle(exe: &Path) -> Option<PathBuf> {
    let app = exe.parent()?.parent()?.parent()?;
    (app.extension()? == "app").then(|| app.to_path_buf())
}

/// What a swap left: the server it moved aside (put back, if it never got a new one), and the app it replaced.
pub fn sweep(data: &Path) {
    let (server, old) = (data.join("server"), data.join("server.old"));
    if !server.exists() && old.exists() {
        let _ = std::fs::rename(&old, &server);
    }
    let _ = std::fs::remove_dir_all(&old);
    if let Some(exe) = EXE.get() {
        let _ = std::fs::remove_file(exe.with_file_name("blueprint.old.exe"));
        if let Some(app) = bundle(exe) {
            let _ = std::fs::remove_dir_all(app.with_file_name("Blueprint.app.old"));
        }
    }
}

/// Windows frees a killed server's open files a moment after it ends, and until then its folder can't move.
fn rename(from: &Path, to: &Path) -> Result<(), String> {
    for _ in 0..10 {
        if std::fs::rename(from, to).is_ok() {
            return Ok(());
        }
        std::thread::sleep(Duration::from_secs(1));
    }
    std::fs::rename(from, to).map_err(|e| format!("Couldn't move {} to {}: {e}", from.display(), to.display()))
}

/// Swaps in the staged release, if there is one; whether the app itself was replaced. The app goes
/// first: if it can't be, nothing changes and the update stays staged for next time.
pub fn apply(data: &Path) -> Result<bool, String> {
    let staged = data.join("update");
    if !staged.join("server").exists() {
        return Ok(false);
    }
    let replaced = match EXE.get() {
        Some(exe) => replace_app(exe, &staged)?,
        None => false,
    };
    let (server, old) = (data.join("server"), data.join("server.old"));
    let _ = std::fs::remove_dir_all(&old);
    if server.exists() {
        rename(&server, &old)?;
    }
    if let Err(e) = rename(&staged.join("server"), &server) {
        let _ = std::fs::rename(&old, &server);
        return Err(e);
    }
    let _ = std::fs::remove_dir_all(&old);
    let _ = std::fs::remove_dir_all(&staged);
    Ok(replaced)
}

#[cfg(target_os = "macos")]
fn replace_app(exe: &Path, staged: &Path) -> Result<bool, String> {
    let new = staged.join("bundle/macos/Blueprint.app");
    let Some(app) = bundle(exe).filter(|_| new.exists()) else { return Ok(false) };
    let old = app.with_file_name("Blueprint.app.old");
    let _ = std::fs::remove_dir_all(&old);
    rename(&app, &old)?;
    // The data folder and /Applications can be on different volumes, where a folder can't be renamed across.
    let copied = || Command::new("ditto").arg(&new).arg(&app).status().is_ok_and(|s| s.success());
    if std::fs::rename(&new, &app).is_err() && !copied() {
        let _ = std::fs::remove_dir_all(&app);
        let _ = std::fs::rename(&old, &app);
        return Err(format!("Couldn't replace {}.", app.display()));
    }
    let _ = std::fs::remove_dir_all(&old);
    Ok(true)
}

#[cfg(windows)]
fn replace_app(exe: &Path, staged: &Path) -> Result<bool, String> {
    let new = staged.join("blueprint.exe");
    if !new.exists() {
        return Ok(false);
    }
    // A running exe can't be written over, but it can be moved aside; `sweep` deletes it next launch.
    let old = exe.with_file_name("blueprint.old.exe");
    let _ = std::fs::remove_file(&old);
    rename(exe, &old)?;
    if let Err(e) = std::fs::copy(&new, exe) {
        let _ = std::fs::rename(&old, exe);
        return Err(format!("Couldn't replace {}: {e}", exe.display()));
    }
    Ok(true)
}

#[cfg(target_os = "linux")]
fn replace_app(exe: &Path, staged: &Path) -> Result<bool, String> {
    let new = staged.join("blueprint");
    if !new.exists() {
        return Ok(false);
    }
    // Beside the running executable, then over it: one can't be written in place.
    let tmp = exe.with_file_name(".blueprint.new");
    std::fs::copy(&new, &tmp).map_err(|e| format!("Couldn't copy {}: {e}", new.display()))?;
    rename(&tmp, exe)?;
    Ok(true)
}

/// Opens Blueprint again, once this one has quit and swapped.
pub fn relaunch() {
    let Some(exe) = EXE.get() else { return };
    if let Some(app) = bundle(exe) {
        let _ = Command::new("open").arg("-n").arg(app).spawn();
    } else {
        let _ = Command::new(exe).spawn();
    }
}

/// When Blueprint quits: the staged release goes in, and the new one opens if "Restart to update" asked.
pub fn on_exit(app: &tauri::AppHandle) {
    use tauri::Manager;
    if let Ok(data) = app.path().app_data_dir() {
        if let Err(e) = apply(&data) {
            eprintln!("update: {e}");
        }
    }
    if RELAUNCH.load(Ordering::SeqCst) {
        relaunch();
    }
}

/// "Restart to update" in the status bar.
#[tauri::command]
pub fn update_restart(app: tauri::AppHandle) {
    RELAUNCH.store(true, Ordering::SeqCst);
    app.exit(0);
}

