"use client";
/* eslint-disable @next/next/no-img-element -- the site is a static export, which next/image cannot optimize; these are small public-domain photos. */

import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import f from "./landing-features.module.css";

/**
 * The desktop app's other tools, drawn: the workspace, plans, diffs and the
 * running app need the desktop app, so the live frame (a static export of a
 * blueprint) can't show them. Each is drawn from the real components' markup in
 * the app's Dark theme, with the real names from this repo's blueprint and the Wikipedia app's,
 * and plays once when its tab opens.
 */
export type Drawing = "claude" | "plan" | "review" | "run";

/**
 * The size the drawings are laid out for. They scale to the stage, never
 * smaller than this in either direction, so a short laptop screen and a phone
 * see the same composition, only smaller.
 */
const WIDE = 1100;
const TALL = 680;

/** When a piece arrives (`--t`) and, for one that passes, leaves (`--u`): seconds after the tab opens. */
const at = (t: number, u?: number) => ({ "--t": `${t}s`, ...(u === undefined ? {} : { "--u": `${u}s` }) }) as CSSProperties;

export function Drawn({ drawing }: { drawing: Drawing }) {
  const box = useRef<HTMLDivElement>(null);
  const [fit, setFit] = useState<{ k: number; w: number; h: number } | null>(null);
  useLayoutEffect(() => {
    const el = box.current!;
    const measure = () => {
      if (!el.clientWidth || !el.clientHeight) return;
      const k = Math.min(1.2, el.clientWidth / WIDE, el.clientHeight / TALL);
      setFit({ k, w: el.clientWidth / k, h: el.clientHeight / k });
    };
    measure();
    const watch = new ResizeObserver(measure);
    watch.observe(el);
    return () => watch.disconnect();
  }, []);
  // A scene that loops plays again from the start once it has finished, until a tab in it is clicked.
  const [round, setRound] = useState(0);
  const [held, setHeld] = useState<Drawing | null>(null);
  useEffect(() => {
    const s = LOOP[drawing];
    if (!s || held === drawing) return;
    const t = window.setTimeout(() => setRound((r) => r + 1), s * 1000);
    return () => window.clearTimeout(t);
  }, [drawing, round, held]);
  // A tab marked `data-play` plays the scene again from that second and holds at `data-play-until`: a
  // fresh scene, so every piece has its animation still to run, skipped ahead.
  const scene = useRef<HTMLDivElement>(null);
  const jump = useRef<{ from: number; until: number } | null>(null);
  const go = (e: React.MouseEvent) => {
    const tab = (e.target as HTMLElement).closest<HTMLElement>("[data-play]");
    if (!tab) return;
    jump.current = { from: Number(tab.dataset.play) * 1000, until: Number(tab.dataset.playUntil) * 1000 };
    setHeld(drawing);
    setRound((r) => r + 1);
  };
  useLayoutEffect(() => {
    const j = jump.current;
    if (!j || !scene.current) return;
    jump.current = null;
    const timed = scene.current.getAnimations({ subtree: true }).filter((a) => a.effect?.getTiming().iterations !== Infinity);
    for (const a of timed) a.currentTime = j.from;
    const t = window.setTimeout(() => timed.forEach((a) => a.pause()), j.until - j.from);
    return () => window.clearTimeout(t);
  }, [round]);
  const Scene = SCENES[drawing];
  return (
    <div ref={box} aria-hidden className={f.fit}>
      {fit ? (
        <div
          ref={scene}
          className={f.app}
          data-held={held === drawing || undefined}
          onClick={go}
          style={{ width: fit.w, height: fit.h, transform: `scale(${fit.k})` }}
        >
          <Scene key={round} />
        </div>
      ) : null}
    </div>
  );
}

/* ── Claude Code beside the blueprint ─────────────────────────── */

