          <img src={img("ada")} alt="" />
          <small>Daguerreotype by Antoine Claudet, c. 1843</small>
          <dl>
            <dt>Born</dt>
            <dd>Augusta Ada Byron, 10 December 1815, London, England</dd>
            <dt>Died</dt>
            <dd>27 November 1852 (aged 36), Marylebone, London</dd>
            <dt>Known for</dt>
            <dd>
              <a>Mathematics</a>, <a>computing</a>
            </dd>
